&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;پڑھنے کا وقت : 22 minutes&lt;/div&gt;
&lt;p&gt;مجھ سے اکثر پوچھا جاتا ہے کہ میری AI کی استعمال کی لاگت کیا ہے؟ میں جواب دیتا ہوں « 20 گلیں فی ماہ » اور مجھے گُہرے آنکhon سے دیکھا جاتا ہے۔ اس لئے آج میں آپ کو سیاہ ڈبے کا اندرونی حصہ دکھا رہا ہوں۔ یہ مضمرہ میرے 73 دن کے وائب کُوڈنگ کا مکمل аудиٹ ہے: SQLite d&amp;#8217;OpenCode کے ڈیٹا بیس سے données نکالنے کا طریقہ کار، tables کے انکواiri کرنے کا SQL کوڈ، اور bazaar کے تمام فراہم کنندگان — مغربی اور چینی — کے ساتھ جامع موازنة۔ نتیجہ اس قدر غیر متوازن تھا کہ مجھےاپنے حساب three بار جانچ کرنے پڑے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;ٹک&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_اسٹیک_سمجھنا_کون_کیا_کرتا_ہے&quot;&gt;اسٹیک سمجھنا : کون کیا کرتا ہے؟&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;شماروں میں غوطہ ڈالنے سے پہلے، معماریت واضح کریں۔ میرے سیٹاپ میں تین متمایز شریک ہیں، اور انہیں معاہدہ نہیں کرنا ضروری ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontSize 12

title میری LLM سٹیک کے تین ایکٹر
left to right direction

actor &quot;میں (ڈیوالپر)&quot; as Dev

package &quot;OpenCode\n(github.com/anomalyco/opencode)&quot; as OC {
  rectangle &quot;CLI وائم کوڈنگ
اوپن سورس، مفت&quot; as CLI
  note right of CLI
    C&#39;est l&#39;outil que j&#39;utilise
    pour coder avec des agents IA.
    Il ne fournit AUCUN modèle.
    C&#39;est un terminal + un orchestrateur.
  end note
}

package &quot;Ollama (مقامی انسٹالیشن)&quot; as OL {
  rectangle &quot;انفرنس کلائن
میری مشین پر انستال کردہ&quot; as Client
  note right of Client
    C&#39;est le logiciel qui fait tourner
    les modèles. Il peut les exécuter
    en local OU les déléguer au cloud
    selon le tag (:cloud).
    Il s&#39;authentifie via clé SSH.
  end note
}

package &quot;Ollama Cloud
(ollama.com)&quot; as OCloud {
  rectangle &quot;خدمت الاستنتاج السحابي\nالاشتراك الاحترافي : 20€/شهر&quot; as Cloud
  note right of Cloud
    C&#39;est le fournisseur d&#39;inférence.
    Mes modèles avec le tag :cloud
    sont exécutés sur LEURS serveurs.
    L&#39;abonnement Pro donne accès
    à des quotas supérieurs.
  end note
}

Dev --&amp;gt; CLI : &quot;میں پرامپٹس ٹائپ کر رہا ہوں&quot;
CLI --&amp;gt; Client : &quot;یہ ماڈل کو بلاؤ&quot;
Client --&amp;gt; Cloud : &quot;کلید SSH + درخواست\n(مودیلز :کلاؤڈ)&quot;
Client --&amp;gt; Client : &quot;مقامی تنفیذ
(مُڈلز بغیر :cloud)&quot;

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;❗&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;OpenCode مودلز کا پیشہ ور فراہم کننده نہیں ہے۔&lt;/strong&gt;یہ ایک اوپن سروس CLI ہےhttps://github.com/anomalyco/opencode[github.com/anomalyco/opencode]) جو AI ایجنٹس کو منظم کرتا ہے۔ وہ سبسکرپشن نہیں فروخت کرتا، اور انفرنس فراہم نہیں کرتا۔ یہ معادلہ ہے`git`ورژننگ کے لیے: ایک آلہ، نہیں ایک سروس. &lt;strong&gt;Ollama Cloud استدلال کے فراہم کرنے والا ہے۔&lt;/strong&gt;میری مقامی Ollama ان اسٹالیسے &lt;strong&gt;کلائنٹ&lt;/strong&gt; کے طور پر عمل کرتی ہے — یہ اِس SSH کلید (Device Key) کے ذریعے Ollama سرویسرز سے تصدیق کرتی ہے اور ان کے ساتھ ٹیگ شدہ ماڈلیز کے نافذ کرنے کی ذمہ داری ان کو دیتی ہے۔`:cloud`Pro اشتراك (20€/mois) زيادہ حدود انلاک کرتا ہے اور Docker کے ذریعے ایک ہی مشین پر کئی حسابوں کو جمع کرنے کی اجازت دیتا ہے&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مقدمہ_کیوں_ایک_audit&quot;&gt;مقدمہ : کیوں ایک audit ؟&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;دو ماہ پہلے، میں اپنے لوکال Ollama انسٹالیشن پر مفت ماڈلز استعمال کر رہا تھا۔ پھر میں نے 20 یورو/ماہ کے پہلے Ollama Cloud Pro سابسکریپشن لیا، جو مجھےکلاؤڈ ماڈلز (ان کے ساتھ ٹاگ) استعمال کرنے کی اجازت دیتا ہے۔&lt;code&gt;:cloud&lt;/code&gt;) عبر المزود`ollama-cloud`. ایک دوسرا subscription ایک ماہ بعد شامل ہوا، ایک الگ Docker انسٹینس پر جس میں اس کا خود کا حساب اور خود کی SSH کلید تھی — جس tarīqe ka jamʿ &lt;a href=&quot;0120_cumuler_deux_abonnements_ollama_pro_docker_post.html&quot;&gt;mon article sur le cumul d&amp;#8217;abonnements&lt;/a&gt; mein bayān kiya gaya hai.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سوال جو مجھے پریشان کر رہا تھا: &lt;strong&gt;کیا یہ 20 يورو فی ماہ جائز ہیں؟&lt;/strong&gt; اندازہ لگانا نہیں. اعداد و شمار کے ساتھ۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جواب دینے کے لیے، مجھے دقیق ڈیٹا کی ضرورت تھی۔ تخمینات نہیں۔ وسطیٰ نہیں۔ میری &lt;strong&gt;réelle&lt;/strong&gt; استعمال، ٹوکن سے ٹوکن، مودل سے مودل، سیشن سے سیشن۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اور OpenCode — CLI — سب کچھ ایک SQLite ڈیٹابیس میں محفوظ کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_opencode_ڈیٹا_بیس_سونا_کی_کانی&quot;&gt;OpenCode ڈیٹا بیس : سونا کی کانی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;OpenCode اپنی سیشنوں کا مکمل تاریخچہ جگہ پر واقع ایک SQLite فائل میں محفوظ رکھتا ہے`~/.local/share/opencode/opencode.db`. La mienne pèse 660 Mo pour 73 jours d&amp;#8217;utilisation — une base de données de production tout à fait respectable.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ ls -lh ~/.local/share/opencode/opencode.db
-rw-r--r-- 1 cheroliv cheroliv 660M mai 18 12:25 opencode.db&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اسکیما&quot;&gt;اسکیما&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ڈیٹا بیس میں تقریباً بیس ٹیبلز ہیں، لیکن ان میں سے تین ہمارے аудиٹ کے لیے اہم ہیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontSize 12

title سادہ اسکیما — OpenCode SQLite
entity &quot;جلسة&quot; as S {
  * id : TEXT
  --
  * model : TEXT (JSON)
  * cost : REAL
  * tokens_input : INTEGER
  * tokens_output : INTEGER
  * tokens_reasoning : INTEGER
  * tokens_cache_read : INTEGER
  * tokens_cache_write : INTEGER
  * time_created : INTEGER
  * project_id : TEXT
}

entity &quot;پیغام&quot; as M {
  * id : TEXT
  --
  * session_id : TEXT &amp;lt;&amp;lt;FK&amp;gt;&amp;gt;
  * data : TEXT (JSON)
  * time_created : INTEGER
}

entity &quot;پروجیکٹ&quot; as P {
  * id : TEXT
  --
  * worktree : TEXT
  * name : TEXT
}

S ||--o{ M : &quot;session_id&quot;
S }o--|| P : &quot;پروجیکٹ آئی ڈی&quot;

note right of S
  La table session agrège
  tokens + coût + modèle.
  C&#39;est notre point d&#39;entrée
  principal.
end note

note right of M
  Les messages individuels.
  Le champ data contient
  le modèle utilisé (format JSON)
  même si la session change
  de modèle en cours de route.
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;میز`session`یہ عالمی audit کے لیے مکمل ہے: ہر سشن کا اس کا ٹوکنز کا مجموعہ، استعمال کردہ مودل، اور لاگت۔ میدان`model`خام JSON ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
  &quot;id&quot;: &quot;deepseek-v4-pro:cloud&quot;,
  &quot;providerID&quot;: &quot;ollama-cloud&quot;,
  &quot;variant&quot;: &quot;default&quot;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;❗&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;میدان`cost`OpenCode ڈیتابیس میں صرف &lt;strong&gt;frais d&amp;#8217;API externes&lt;/strong&gt; API کلید (Google Gemini، OpenAI، غیره) کے ذریعے استعمال پر ادا کی گئی رقمیں دکھائی جاتی ہیں۔ Ollama کے ذریعے किए गए کالز — سواء محليًا یا Ollama Cloud Pro کے ذریعے — mark کر دیے جاتے ہیں۔`cost=0`لہٰں، لاگت ثابت (ایباؤنمنٹ) ہے، per‑token نہیں۔ ان कालوں کی سچائی لاگت مہینہ ایباؤنمنٹ ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_استخراج_کا_کوڈ&quot;&gt;استخراج کا کوڈ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کسی چیز کو انسٹال کرنے کی ضرورت نہیں۔ Node.js 22+ ایک تجرباتی SQLite ماڈیول شامل کرتا ہے (&lt;code&gt;node:sqlite&lt;/code&gt;) پوری طرح کام کرتا ہے۔ یہ وہ سکرپٹ ہے جس نے مجھے سب کچھ دیا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;const { DatabaseSync } = require(&#39;node:sqlite&#39;);
const db = new DatabaseSync(
  `${process.env.HOME}/.local/share/opencode/opencode.db`,
  { readonly: true }
);

// 1. Statistiques globales
const global = db.prepare(`
  SELECT
    COUNT(*) as sessions,
    SUM(tokens_input) as total_input,
    SUM(tokens_output) as total_output,
    SUM(tokens_reasoning) as total_reasoning,
    SUM(tokens_cache_read) as total_cache_read,
    SUM(cost) as total_cost
  FROM session
`).get();

// 2. Ventilation par modèle et fournisseur
const byModel = db.prepare(`
  SELECT
    json_extract(model, &#39;$.id&#39;) as model_id,
    json_extract(model, &#39;$.providerID&#39;) as provider,
    COUNT(*) as sessions,
    SUM(tokens_input) as total_input,
    SUM(tokens_output) as total_output,
    SUM(cost) as total_cost
  FROM session
  WHERE model IS NOT NULL
  GROUP BY model_id, provider
  ORDER BY SUM(tokens_input) DESC
`).all();

// 3. Par mois
const monthly = db.prepare(`
  SELECT
    strftime(&#39;%Y-%m&#39;, datetime(time_created/1000, &#39;unixepoch&#39;)) as month,
    COUNT(*) as sessions,
    SUM(tokens_input) as total_input,
    SUM(tokens_output) as total_output,
    SUM(cost) as total_cost
  FROM session
  WHERE time_created IS NOT NULL
  GROUP BY month
  ORDER BY month
`).all();

// 4. Messages par modèle (détection des changements intra-session)
const msgByModel = db.prepare(`
  SELECT
    json_extract(m.data, &#39;$.model.providerID&#39;) as provider,
    json_extract(m.data, &#39;$.model.modelID&#39;) as model_id,
    COUNT(*) as messages
  FROM message m
  WHERE json_extract(m.data, &#39;$.model&#39;) IS NOT NULL
  GROUP BY provider, model_id
  ORDER BY COUNT(*) DESC
`).all();

console.log({ global, byModel, monthly, msgByModel });
db.close();&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;ℹ️&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;فلاج`--experimental-sqlite`Node.js 22.x پر ضروری ہے۔ Node.js 24+ پر، ماڈیول مستحکم ہے اور بعد میں Flag کی ضرورت نہیں ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
