&lt;li&gt;&lt;a href=&quot;#_کامل_ورکفلو_کا_خلاصہ&quot;&gt;کامل ورکفلو کا خلاصہ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_آخری_جانچ&quot;&gt;آخری جانچ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_کنفیگریشن_فائل_کھولیں&quot;&gt;📂 کنفیگریشن فائل کھولیں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_️_اضافہ_یا_ترمیم_font_size&quot;&gt;🖋️ اضافہ یا ترمیم `font_size&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_محفوظ_کریں_اور_kitty_کو_دوبارہ_چلائیں&quot;&gt;💾 محفوظ کریں اور Kitty کو دوبارہ چلائیں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_تنظیم_دیناميک_زوم_مؤقت&quot;&gt;✅ تنظیم دیناميک (زوم مؤقت)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_اوہ_مای_زش_کی_انسیٹال_اور_کائنفیگریشن&quot;&gt;اوہ مای زش کی انسیٹال اور کائنفیگریشن&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_oh_my_zsh_کی_انسٹالیشن&quot;&gt;Oh My Zsh کی انسٹالیشن&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ธีม_بدلئ&quot;&gt;ธีม بدلئ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_تصديق&quot;&gt;تصديق&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_استعمال_کے_کیس_کا_ڈائگرام&quot;&gt;استعمال کے کیس کا ڈائگرام&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kitty_میں_شفافیت_فعال_کریں&quot;&gt;Kitty میں شفافیت فعال کریں&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_شفافیت_کے_لئے_پیش_شرط&quot;&gt;شفافیت کے لئے پیش شرط&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kitty_conf_میں_شفافیت_کی_ترتیب&quot;&gt;kitty.conf میں شفافیت کی ترتیب&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_کٹی_کو_دوبارہ_شروع_کریں&quot;&gt;کٹی کو دوبارہ شروع کریں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ممکن_مکملات&quot;&gt;ممکن مکملات&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_سیکنسی_ڈائگرام_kitty_کی_انشئلائزیشن_شفافیت_کے_ساتھ&quot;&gt;سیکنسی ڈائگرام - Kitty کی انشئلائزیشن شفافیت کے ساتھ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_معروفة_محدودیتیں&quot;&gt;معروفة محدودیتیں&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_آواز_سے_آؤڈبیل_بیل_کو_غیر_فعال_کریں&quot;&gt;آواز سے���� (آؤڈبیل بیل) کو غیر فعال کریں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_کیتی_کا_اپ_ڈیٹ&quot;&gt;کیتی کا اپ ڈیٹ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_حوالہ_جات&quot;&gt;حوالہ جات&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_نتیجہ&quot;&gt;نتیجہ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ رہنمای قدم‑به‑قدم بتاتی ہے کہ Xubuntu پر ٹرمینل &lt;strong&gt;kitty&lt;/strong&gt; کو کیسے انسٹال کریں، اسے صحیح طریقے سے کنفیگر کریں، اور bash کی جگہ &lt;strong&gt;zsh&lt;/strong&gt; کو ڈیفالٹ شیل بنائیں۔ کیٹی پروجيکٹ یہاں دستیاب ہے: &lt;a href=&quot;https://github.com/kovidgoyal/kitty&quot; class=&quot;bare&quot;&gt;https://github.com/kovidgoyal/kitty&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Kitty ایک modern، تیز اور قابلِ تنظیم ٹرمنل ہے، خاص طور پر مطالبہ کرنے والے ڈویلپرز کے لیے مناسب ہے۔ &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_کیٹی_اور_zsh_کو_کیوں_چنیے&quot;&gt;کیٹی اور Zsh کو کیوں چنیے؟&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kitty تمیز رکھتی ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;GPU کی تيسر سے بہتر کارکردگی،&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ایک پوری طرح ایک متنی فائل پر مبنی تنظیم,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;فونٹس اور لگچرز کے لیے بہترین حمایت.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Zsh خود ایک طاقتور تعاملی شیل پیشکش کرتا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;ایک هوشمند تکملہ,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ایک قابلِ تنظیم پروامپٹ,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;بے حد مناسبیت بیک کے ساتھ۔&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kitty اور Zsh کو ملانے سے، آپ ایک مصنوعات اور خوبصورت ماحول سے فائدہ اٹھاتے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title سادہ معماری Kitty + Zsh
actor User

User --&amp;gt; Kitty : Lance le terminal
Kitty --&amp;gt; Zsh : Initialise le shell interactif
Zsh --&amp;gt; System : Interagit avec le système (fichiers, commandes)
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ رہنمای عمداً محدود ہے اسکریپٹ کے ذریعے انسٹالیشن اور Xubuntu تک۔&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_سیسٹم_کی_پیشِ_ضروریات&quot;&gt;سیسٹم کی پیشِ ضروریات&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;شروع کرنے سے پہلے، کرم یقینی بنائیں کہ آپ کے پاس:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Xubuntu انسٹال،&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;انترنت تک رسائی,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اسکرپٹ چلانے کے لیے ایک فاعل باش شیل۔&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اپنی ماحول کی جانچ کریں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;uname -a
lsb_release -a&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_کیٹی_کا_ڈاؤنلوڈ_اور_انسٹالیشن&quot;&gt;کیٹی کا ڈاؤنلوڈ اور انسٹالیشن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کٹی اسے ایک رسمی اسکرپٹ کے ذریعے انسٹال کرنے کی سِفارش کرتی ہے جو فائلز کو`~/.local/kitty.app`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;Important&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ طريقہ پاکج مینیجرز سے مستقل ہے (نہ`apt`).&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اسٹال_سکرپٹ_ڈاؤنلوڈ_کریں&quot;&gt;اسٹال سکرپٹ ڈاؤنلوڈ کریں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کمانڈ درج ذیل کو چلائیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;curl -L https://sw.kovidgoyal.net/kitty/installer.sh | sh /dev/stdin&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ کمانڈ انجام دےتی ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;بائنریز ڈاؤنلوڈ،&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;استخراج میں`~/.local/kitty.app`,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;سائمبولک لنکس کی بناؤ.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title Kitty کا ڈاؤنلوڈ اور انسٹال
start
:curl -L installer.sh;
:sh /dev/stdin;
:Décompression dans ~/.local/kitty.app;
:create symlinks;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_سمبولک_لنکس_کی_تخلیق&quot;&gt;سمبولک لنکس کی تخلیق&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;انکار کرنے کے لئے`kitty`ٹرمینال سے، ایک سمبولک لنک بنائیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;ln -s ~/.local/kitty.app/bin/kitty ~/.local/bin/kitty&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;افزائیں`~/.local/bin`اپنے PATH میں شامل کریں اگر پہلے سے نہیں کیا گیا ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;echo &#39;export PATH=&quot;$HOME/.local/bin:$PATH&quot;&#39; &amp;gt;&amp;gt; ~/.zshrc
source ~/.zshrc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ انسٹالیشن کی جانچ کر سکتے ہیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;kitty --version&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ایکسبونٹو_میں_کٹی_کی_انٹیگریشن&quot;&gt;ایکسبونٹو میں کٹی کی انٹیگریشن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kitty کو ایپلیکیشن مینو میں ظاہر ہونے کے لیے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ڈیٹاپ_فائل_کاپی_کریں&quot;&gt;ڈیٹاپ فائل کاپی کریں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;فائل کاپی کریں`.desktop`مہیا :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;cp ~/.local/kitty.app/share/applications/kitty.desktop ~/.local/share/applications/&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ڈیسک_ٹاپ_فائل_کو_ترمیم_کریں&quot;&gt;ڈیسک ٹاپ فائل کو ترمیم کریں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;فائل میں ترمیم کریں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;nano ~/.local/share/applications/kitty.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نوائن؟&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;[Desktop Entry]
Version=1.0
Type=Application
Name=Kitty Terminal
Comment=Fast GPU-based terminal emulator
Exec=/home/$USER/.local/kitty.app/bin/kitty
Icon=kitty
Categories=System;TerminalEmulator;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بدل کیجئے`YOURUSER`آپ کے صارف نام کے ذریعے&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title Xubuntu مینی میں Kitty کے شمول کی عمل
start
:Copier .desktop;
:Editer les chemins;
:Sauvegarder;
:Menu Applications;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کیٹی_کو_ڈیفالٹ_ٹرمینل_کے_طور_پر_منسوب_کریں_اختیاری&quot;&gt;کیٹی کو ڈیفالٹ ٹرمینل کے طور پر منسوب کریں (اختیاری)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کہ Kitty عادی طور پر چلنے والا ٹرمینل بن جائے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo update-alternatives --install /usr/bin/x-terminal-emulator x-terminal-emulator ~/.local/kitty.app/bin/kitty 50
sudo update-alternatives --config x-terminal-emulator&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;منتخب کریں`kitty`منو مُقترح میں&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_زیش_کی_انسٹالیشن&quot;&gt;زیش کی انسٹالیشن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر Zsh ابھی تک انسٹال نہیں ہے، چلاوئے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo apt install zsh&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;انستالیشن جانچ کریں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;zsh --version&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_zsh_کو_ڈفلٹ_شیل_بنائیں&quot;&gt;Zsh کو ڈفلٹ شیل بنائیں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ اپنی شیلی کو عالمی طور پر یا صرف Kitty میں تبدیل کر سکتے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ملکی_طریقہ_تمام_ٹرمنل_کے_لیے&quot;&gt;ملکی طریقہ (تمام ٹرمنل کے لیے)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پہچانیں مطلق مسار:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;which zsh&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;عام طور پر`/usr/bin/zsh`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ڈیفالٹ شیل کو بدل دیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;chsh -s /usr/bin/zsh&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;خروج ہوں اور پھر لاگ ان کریں&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title شیل کی عالمی تبدیلی
actor User

User --&amp;gt; Bash : Session actuelle
User --&amp;gt; System : chsh -s /usr/bin/zsh
System --&amp;gt; &quot;/etc/passwd&quot; : Modifie le shell
note right of &quot;/etc/passwd&quot; : Shell par défaut mis à jour
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کیٹی_کے_لئے_مخصوص_طریقہ&quot;&gt;کیٹی کے لئے مخصوص طریقہ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر آپ کیتی میں صرف شیل تبدیل کرنا چاہتے ہیں، تو تنظیم فائل کو ایڈٹ کریں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;nano ~/.config/kitty/kitty.conf&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ لائن شامل کریں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;shell zsh&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kitty کو محفوظ کریں اور رِسٹارٹ کریں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_zsh_کی_تنظیمات_اختیاری&quot;&gt;Zsh کی تنظیمات (اختیاری)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اپنے Zsh کو خودساز بنائیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ایک_zshrc_فائل_بنائیں&quot;&gt;ایک .zshrc فائل بنائیں&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;touch ~/.zshrc
nano ~/.zshrc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کم_سے_کم_کنفیگریشن_کا_مثال&quot;&gt;کم سے کم کنفیگریشن کا مثال&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;export ZSH_THEME=&quot;robbyrussell&quot;
export PATH=&quot;$HOME/.local/bin:$PATH&quot;
alias ll=&quot;ls -la&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_کامل_ورکفلو_کا_خلاصہ&quot;&gt;کامل ورکفلو کا خلاصہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نیچے دیا گیا نمودار مکمل عمل کا خلاصہ پیش کرتا ہے&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title انسٹالیشن اور کنفیگریشن کی ورک فلو
start
:Téléchargement script Kitty;
:Installation dans ~/.local;
:Création symlink;
:Ajout ~/.local/bin au PATH;
if (Zsh installé ?) then (non)
  :sudo apt install zsh;
endif
:Configurer Kitty.desktop;
:Optionnel - changer terminal par défaut;
:Optionnel - chsh -s /usr/bin/zsh;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_آخری_جانچ&quot;&gt;آخری جانچ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کیتی چلائیں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;kitty&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ کو یہ دیکھنا چاہیے`zsh`فعال ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;echo $SHELL&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مُتوقع نتیجہ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;/usr/bin/zsh&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;فونٹ کے سائز کو تبدیل کرنے کے لئے&lt;strong&gt;کیٹی&lt;/strong&gt;, ہمیں پیرامیٹر کو ایجسٹ کرنا پڑتا ہے`font_size`کنفیگریشن فائل میں۔ یہ تفصیلی عمل ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کنفیگریشن_فائل_کھولیں&quot;&gt;📂 کنفیگریشن فائل کھولیں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;م بنیادی تنظیمات فائل عموماً یہاں واقع ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;~/.config/kitty/kitty.conf&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر یہ فایل ابھی تک موجود نہیں ہے، تو آپ اسے بن سکتے ہیں۔ مثال :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;nano ~/.config/kitty/kitty.conf&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_️_اضافہ_یا_ترمیم_font_size&quot;&gt;🖋️ اضافہ یا ترمیم `font_size&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نیचे دی گئی ہدایت شامل کریں، یا اگر یہ پہلے سے موجود ہو تو اسے تبدیل کریں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;font_size 14.0&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہاں`14.0`خواہش کے حسب سائز سے مطابقت رکھتا ہے۔ آپ کسی بھی اعشاریہ مقدار رکھ سکتے ہیں، مثال کے طور پر`12.0`, &lt;code&gt;15.5&lt;/code&gt;, و غیرہ&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_محفوظ_کریں_اور_kitty_کو_دوبارہ_چلائیں&quot;&gt;💾 محفوظ کریں اور Kitty کو دوبارہ چلائیں&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;محفوظ کریں (&lt;code&gt;Ctrl + O&lt;/code&gt;, پھر`Entrée`) aur chlijiye (&lt;code&gt;Ctrl + X&lt;/code&gt;) اگر آپ استعمال کر رہے ہیں`nano`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;کٹی کی تمام وینڈوز بند کر دیں، پھر ٹرمینل کو دوبارہ شروع کریں تا تبدیل مؤثر ہو جائے۔&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تنظیم_دیناميک_زوم_مؤقت&quot;&gt;✅ تنظیم دیناميک (زوم مؤقت)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر آپ موقتاً زوم ان/آؤٹ کرنا چاہتے ہیں، ترکیب تبدیل کیے بغیر، براہِ کرم ڈیفالٹ کی بورڈ شرتکٹ استعمال کریں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;فونٹ کے سائز کو بڑھائیں&lt;/strong&gt; :&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;Ctrl + Shift + =&lt;/code&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;فونت کے سائز کو کم کریں&lt;/strong&gt; :&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;Ctrl + Shift + -&lt;/code&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;سائز ریست کریں&lt;/strong&gt;:&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;code&gt;Ctrl + Shift + Backspace&lt;/code&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ترتیبات ٹرمینال کی بند ہونے کے بعد برقرار نہیں رہتی۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_اوہ_مای_زش_کی_انسیٹال_اور_کائنفیگریشن&quot;&gt;اوہ مای زش کی انسیٹال اور کائنفیگریشن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;زیش کو انسٹال کردہ اور ڈیفالٹ شیل بنانے کے بعد، آپ &lt;strong&gt;Oh My Zsh&lt;/strong&gt; کے ذریعے Apni ماحول کو بہتر بن سکتے ہیں — Zsh کی ترتیب‑دینے کا فریم ورک — جو فراہم کرتا ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;پرمپت کے لیے موضوعات کی ایک مجموعہ,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;بہت سی پلاگنس،&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;کونفیگریشن کی واضح تنظیم۔&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_oh_my_zsh_کی_انسٹالیشن&quot;&gt;Oh My Zsh کی انسٹالیشن&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مطمئن ہوں کہ Zsh فعال ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;zsh --version&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر ضروری ہو، چلاو:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;zsh&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سپس ڈاؤنلوڈ کریں اور اجرا کریں، رسمی انسٹالیشن اسکرپت :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sh -c &quot;$(curl -fsSL https://raw.githubusercontent.com/ohmyzsh/ohmyzsh/master/tools/install.sh)&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ سکرپٹ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;فولڈر بنائیں`~/.oh-my-zsh`,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ممکناً اپنی فائل محفوظ کریں`~/.zshrc`,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;نئے پرامپٹ کو خودکار طور پر فعال کرتا ہے۔&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ธีม_بدلئ&quot;&gt;ธีม بدلئ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ کی تنظیم فائل کھولیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;nano ~/.zshrc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;متغیر کو بدل دیں`ZSH_THEME`ایک دیگر موضوع کو انتخاب کرنے کے لیے (مثلاً`agnoster`) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ZSH_THEME=&quot;agnoster&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;محفوظ کریں پھر رلوڈ کریں کنفیگریشن :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;source ~/.zshrc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تصديق&quot;&gt;تصديق&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kitty کو چلائیں اور جائز لیں کہ پرامپٹ مناسب طور پر بدل گیا ہے۔ آپ تصدیق کر سکتے ہیں کہ Oh My Zsh فعال ہے، اسچلائے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;echo $ZSH&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نتیجہ مماثل ہونا چاہیے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;/home/آپ_کا_صارف/.oh-my-zsh&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_استعمال_کے_کیس_کا_ڈائگرام&quot;&gt;استعمال کے کیس کا ڈائگرام&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title Use case Oh My Zsh کی انسٹالیشن اور استعمال
actor Utilisateur as User

package &quot;کیٹی ٹرمینال&quot; {
  component &quot;Zsh شل&quot; as Zsh
}

component &quot;اوہ می زش فریم ورک&quot; as OhMyZsh

User --&amp;gt; Kitty : Lance Kitty
Kitty --&amp;gt; Zsh : Initialise Zsh
Zsh --&amp;gt; OhMyZsh : Charge configuration (~/.zshrc, thèmes, plugins)
User --&amp;gt; OhMyZsh : Personnalise le thème et les plugins

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_kitty_میں_شفافیت_فعال_کریں&quot;&gt;Kitty میں شفافیت فعال کریں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kitty کی سب سے زیادہ محبوب خصوصیات میں سے ایک ٹرمینل کی پس منظر میں &lt;strong&gt;شفافیت&lt;/strong&gt; شامل کرنے کی قابلیت ہے۔ یہ نیچے الوالا ماحول (ویندو، ڈیسکٹاپ، وغیرہ) کو ہلکا سا دکھاتا ہے، جس کا استعمال مالتِٹاسک میں خاص طور پر مفید ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_شفافیت_کے_لئے_پیش_شرط&quot;&gt;شفافیت کے لئے پیش شرط&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کٹی میں شفافیت اس پر مبنی ہے&lt;strong&gt;کھڑکیوں کا مُصَنّف&lt;/strong&gt;گرافیکی ماحول توسط استعمال کیا جاتا ہے Xubuntu پر (XFCE پر مشتمل)، یقینی بنائیں کہ&lt;strong&gt;کمپوزیشن فعال ہے&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جانچ کرنے کے لیے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;راست کلیک ڈیسکاپ پر &amp;gt; ترتیبات &amp;gt;&lt;strong&gt;ویindow مینیجر کی تنظیمات&lt;/strong&gt;,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ٹاب&lt;strong&gt;موزِق نگار&lt;/strong&gt;: بکس &lt;strong&gt;ترکیب فعال کریں&lt;/strong&gt; چیک کرنا ضروری ہے۔&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title Use Case - Kitty میں شفافیت فعال کریں
actor Utilisateur

rectangle &quot;گرافیکی ماحول (XFCE/Xubuntu)&quot; {
  usecase &quot;کامپوزیشن فعال کریں&quot; as UC1
}

rectangle &quot;کیٹی ٹرمینل&quot; {
  usecase &quot;کٹی کنف میں شفافیت سیٹ کریں&quot; as UC2
}

Utilisateur --&amp;gt; UC1
Utilisateur --&amp;gt; UC2

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kitty_conf_میں_شفافیت_کی_ترتیب&quot;&gt;kitty.conf میں شفافیت کی ترتیب&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ کی کنفیگریشن فائل کھولیں`~/.config/kitty/kitty.conf` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;nano ~/.config/kitty/kitty.conf&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;شامل کریں یا ترمیم کریں بعد کی líneas:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-conf hljs&quot; data-lang=&quot;conf&quot;&gt;background_opacity 0.85&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ پیرامیٹر درجہ بیں قدر قبول کرتا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;1.0&lt;/code&gt;→ بے شفاف (کوئی شفافیت نہیں),&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;0.0&lt;/code&gt;→ کاملاً شفاف (استعمال نہیں)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;درمیانی قيمتیں جیسے`0.90`, &lt;code&gt;0.75&lt;/code&gt;, و غیرہ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک خوبصورت بصری تسالمعام طور پر درمیان`0.85` et &lt;code&gt;0.95&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کٹی_کو_دوبارہ_شروع_کریں&quot;&gt;کٹی کو دوبارہ شروع کریں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kitty کے تمام انسینسز بند کر دیں، پھر نئی وینڈو لاونچ کریں تاکہ تبدیلیاں اثر کر سکیں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;kitty&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ممکن_مکملات&quot;&gt;ممکن مکملات&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر آپ ایک کسٹم ٹرمنل پس منظر استعمال کر رہے ہیں، تو آپ ایک پس منظر کا رنگ بھی شفافیت کے ساتھ (RGBA میں) سیٹ کر سکتے ہیں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-conf hljs&quot; data-lang=&quot;conf&quot;&gt;background #1e1e2eff&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آخری جزو (&lt;code&gt;ff&lt;/code&gt;) بے شفافیت ظاہر کرتا ہے (de`00` à &lt;code&gt;ff&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_سیکنسی_ڈائگرام_kitty_کی_انشئلائزیشن_شفافیت_کے_ساتھ&quot;&gt;سیکنسی ڈائگرام - Kitty کی انشئلائزیشن شفافیت کے ساتھ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title کیٹی کے transparency کے ساتھ شروع ہونے کی سیکوانس
actor User
participant &quot;کیٹی&quot; as Kitty
participant &quot;XFCE کمپوزٹر&quot; as XFCE
participant &quot;جي بي يو/وینڈو مینیجر&quot; as WM

User -&amp;gt; Kitty : Lance Kitty
Kitty -&amp;gt; kitty.conf : Lit configuration
Kitty -&amp;gt; XFCE : Vérifie composition activée
XFCE --&amp;gt; Kitty : Composition = active
Kitty -&amp;gt; WM : Demande allocation fenêtrée transparente
WM --&amp;gt; Kitty : OK (rendu avec alpha &amp;lt; 1)
Kitty -&amp;gt; User : Affiche terminal translucide

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_معروفة_محدودیتیں&quot;&gt;معروفة محدودیتیں&lt;/h3&gt;
&lt;div class=&quot;admonitionblock warning&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-warning&quot; title=&quot;Warning&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;الشفافیت کام نہیں کرتی اگر : - XFCE کی کمپوزر غیر فعال ہے, - نامطابق window manager استعمال ہوتا ہے, - آپ Kitty کو ایک &lt;strong&gt;tmux&lt;/strong&gt; کے پس منظر موڈ میں استعمال کر رہے ہیں جس میں شفافیت کا سپورٹ نہیں ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_آواز_سے_آؤڈبیل_بیل_کو_غیر_فعال_کریں&quot;&gt;آواز سے���� (آؤڈبیل بیل) کو غیر فعال کریں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ڈفلٹ پر Kitty ایک &lt;strong&gt;bip&lt;/strong&gt; آواز پیدا کرتی ہے جب غلط 커맡نڈ داخل کی جاتی ہو یا ٹرمینل کے أي sự kiện سے یہ چلایا جائے۔ یہ آواز جلد ہی متنافر بن سکتی ہے، مخصوصاً tez taraqqiyati mohit میں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اس سلوک کو غیر فعال کرنے کے لیے، درج ذیل ہدایات کو فائل میں شامل کریں`~/.config/kitty/kitty.conf`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-conf hljs&quot; data-lang=&quot;conf&quot;&gt;audible_bell no&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ بھی &lt;strong&gt;بصری فِeedبَک&lt;/strong&gt; فعال کر سکتے ہیں بج کی آواز کی جگہ پر :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-conf hljs&quot; data-lang=&quot;conf&quot;&gt;visual_bell yes&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_کیتی_کا_اپ_ڈیٹ&quot;&gt;کیتی کا اپ ڈیٹ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کیونکہ Kitty اسکرپٹ کے ذریعے انسٹال کیا گیا ہے، پیکنج مینیجر نہیں۔ اپ ڈیٹ رسمی انسٹال اسکرپٹ کو دوبارہ چلایا کر کیا جاتا ہے۔ یہ آپ کو سب سے نئی ورژن ڈاؤنلوڈ کرنے اور اپنی موجودہ انسٹال کو اپ ڈیٹ کرنے میں اجازت دیتا ہے۔&lt;code&gt;~/.local/kitty.app&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لاحق`.app`راستے میں`~/.local/kitty.app`یہ Kitty کے لنکس پر رسمی سکرپٹ کے ذریعے انstalیشن کی رواج ہے، اور اس کا کوئی بھی مطلب نہیں ہے کہ صرف macOS کے ساتھ متوافق ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;Important&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ ڈیٹ کامینڈ چلانے سے پہلے، یقینی بنائیں کہ آپ اپنے گھر کے ڈائریکٹری میں ہیں (&lt;code&gt;~&lt;/code&gt;)&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اپنی ہوم ڈائریکٹری سے درج ذیل فرمان اجرائیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;curl -L https://sw.kovidgoyal.net/kitty/installer.sh | sh /dev/stdin&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ اسکرپٹ ذمہ دار ہوگا :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;نیا ورژن کے بائنریز ڈاؤنلوڈ کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;فائلوں کو نکال کریں`~/.local/kitty.app`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ضرورت ہونے پر سمبولک لنکس کو اپ ڈیٹ کریں۔&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ ڈیٹ کرنے کے بعد، تمام Kitty کے انسٹنسز بند کر کے پھر سے چلا دینے کی تجویز دی جاتی ہے تاکہ نئی ورژن صحیح طور پر مان لی جائے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_حوالہ_جات&quot;&gt;حوالہ جات&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر آپمزید تخصیص کرنا چاہتے ہیں, رسمی destructuwat ko dekhein :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;کیٹی : &lt;a href=&quot;https://sw.kovidgoyal.net/kitty/&quot; class=&quot;bare&quot;&gt;https://sw.kovidgoyal.net/kitty/&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://sw.kovidgoyal.net/kitty/conf/#opt-kitty.background_opacity&quot; class=&quot;bare&quot;&gt;https://sw.kovidgoyal.net/kitty/conf/#opt-kitty.background_opacity&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://sw.kovidgoyal.net/kitty/conf/#opt-kitty.audible_bell&quot; class=&quot;bare&quot;&gt;https://sw.kovidgoyal.net/kitty/conf/#opt-kitty.audible_bell&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;زِش : &lt;a href=&quot;https://zsh.sourceforge.io/&quot; class=&quot;bare&quot;&gt;https://zsh.sourceforge.io/&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;گیٹ ہب: &lt;a href=&quot;https://github.com/kovidgoyal/kitty&quot; class=&quot;bare&quot;&gt;https://github.com/kovidgoyal/kitty&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;زیش: &lt;a href=&quot;https://zsh.sourceforge.io/&quot; class=&quot;bare&quot;&gt;https://zsh.sourceforge.io/&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://ohmyz.sh/&quot; class=&quot;bare&quot;&gt;https://ohmyz.sh/&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/ohmyzsh/ohmyzsh/wiki&quot; class=&quot;bare&quot;&gt;https://github.com/ohmyzsh/ohmyzsh/wiki&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.xfce.org/xfce/xfwm4/compositor&quot; class=&quot;bare&quot;&gt;https://docs.xfce.org/xfce/xfwm4/compositor&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجہ&quot;&gt;نتیجہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اب آپ کے پاس ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;ایک جدید اور مؤثر ٹرمنل (Kitty)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ایک طاقتور اور قابل شخصی سازی شیل (Zsh) کا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ایک نظام کے پیکیجوں سے مستقل اور صاف کنفیگری&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ایک خوبصورت اور کارآمد ٹرمینل Oh My Zsh سے لاگ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

