&lt;col style=&quot;width: 2.2222%;&quot;&gt;
&lt;col style=&quot;width: 2.2222%;&quot;&gt;
&lt;col style=&quot;width: 2.2222%;&quot;&gt;
&lt;col style=&quot;width: 2.2222%;&quot;&gt;
