rectangle &quot; &quot; as ARROW2

rectangle &quot;**LAZY_EAGER_ESSENTIALS.adoc**\n**~50 خطوط — EAGER**&quot; as ESS #C8E6C9 {
  card &quot;P1 مختصر\n(15 سطر)&quot; as E1
  card &quot;P2 مكثفة
(35 سطر)&quot; as E2
}

rectangle &quot;**.agents/encyclopedies/**\n**LAZY_EAGER_ENCYCLOPEDIE.adoc**\n627 لائنوں — COLD&quot; as ENC #BBDEFB {
  card &quot;P1 کو انکسیوں
(مکمل، سالم)&quot; as C1
}

BEFORE -[#4CAF50]-&amp;gt; ESS : &quot;استخراج کا
حراجی علم&quot;
