&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہر فائل جاندار ہے کہ اس کی جگہ &lt;strong&gt;جس میں کیا موجود ہے&lt;/strong&gt; کے مطابق مقرر ہوتی ہے، &lt;strong&gt;نبھانے کے وقت&lt;/strong&gt; کے مطابق نہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_سلسلے_کی_منطقی_اگلا_حصہ&quot;&gt;سلسلے کی منطقی اگلا حصہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر آپ نے پہلے دو مضامین پڑھے ہیں، تو یہ ہے کہ تین حصے کیسے مل جاتے ہیں:&lt;/p&gt;
&lt;/div&gt;
&lt;div id=&quot;diag-trilogie&quot; class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultTextAlignment center
skinparam wrapWidth 220

title ایجن کی حکمرانی کی ٹرائیلوجی
left to right direction

package &quot;📖 **مادہ 0108**\nاستراتژی Eager/Lazy&quot; as A1 #E8F5E9 {
  card &quot;مموری ایجنٹ\nسیشنز کے درمیان&quot; as M1
  card &quot;EAGER فائلیں\n(خود لوڈ شدہ)&quot; as M2
  card &quot;LAZY فائلیں
(درخواست پر)&quot; as M3
  card &quot;6 مراحل کی کارروائی&quot; as M4
}

package &quot;🧊 **مادہ 0110**\nمیکانزم Hot/Warm/Cold&quot; as A2 #FFF9C4 {
  card &quot;بڑھاپا
سیاق و سباق کا&quot; as V1
  card &quot;سلائیڈ وینڈو
10 سیشنز&quot; as V2
  card &quot;ٹھنڈی لہر
یک جِسا&quot; as V3
  card &quot;سنسور
두 ٹriger&quot; as V4
}

package &quot;🔍 **مادہ 0111**
اوڈٹ +انسائیکلوپیڈیک سولوشن&quot; as A3 #BBDEFB {
  card &quot;فائلوں کی جانچ
EAGER&quot; as E1
  card &quot;شناخت
بے کارکردگی&quot; as E2
  card &quot;Split\nESSENTIALS/انسیکلوپیڈیٰ&quot; as E3
