  file &quot;SCRIPT_VERIFICATION\n(آخری)&quot; as VER_WARM
  file &quot;PROCEDURES.adoc\n(templates)&quot; as PRO_WARM
  file &quot;*_REFERENCE.adoc
(تقنی مستند)&quot; as REF_WARM
}

package &quot;COLD (backup/)
کبھی بار نہیں
صرف انسانی پڑھائی&quot; as COLD #BBDEFB {
