    file &quot;INDEX (مکمل)&quot; as IDX_COLD
    file &quot;SESSIONS_HISTORY
(مکمل)&quot; as HIS_COLD
    file &quot;COMPLETED_TASKS
(مکمل)&quot; as ARCH_COLD
    folder &quot;سیشن/ (001-039)&quot; as SESS_COLD
  }
  folder &quot;Y2026-040-???
(Mustaqbil)&quot; as FUTURE
}

