&lt;li&gt;&lt;a href=&quot;#_ملحق_فائلز_مجموعی_جائزہ&quot;&gt;ملحق فائلز — مجموعی جائزہ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_سیخے_سباقات&quot;&gt;سیخے سباقات&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_گھر_میں_انسٹال_کرنے_سے_سب_چیزیں_آزاد_ہو_جاتی_ہیں&quot;&gt;گھر میں انسٹال کرنے سے سب چیزیں آزاد ہو جاتی ہیں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_zoom_font_size_لیسٹ_کامپوننٹس_کے_لیے&quot;&gt;zoom` &amp;gt; &lt;code&gt;font-size&lt;/code&gt; لیسٹ کامپوننٹس کے لیے&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_custom_css_ایکسٹینشن_کو_صریح_اکٹیویشن_کی_ضرورت_ہوتی_ہے&quot;&gt;Custom CSS ایکسٹینشن کو صریح اکٹیویشن کی ضرورت ہوتی ہے&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ایک_اپ_ڈیٹ_سکرپٹ_ضروری_ہے&quot;&gt;ایک اپ ڈیٹ سکرپٹ ضروری ہے&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_جلدی_حوالے&quot;&gt;جلدی حوالے&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;وقت پڑھنے کا : 8 minutes&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;VS Code کو ان میں کیوں انسٹال کریں`/opt`یا via`apt`جب آپ اسے apne home میں رکھ سکتے ہیں اور apne IDE کو کھیل کا میدان بن سکتے ہیں، کبھی بھی ٹائپ نہیں کرتے۔&lt;code&gt;sudo&lt;/code&gt;? یہی ایک مقامی انسٹالیشن کی کہانی ہے، جس کے بعد مینو اور فائل ایکسپلورر کے فونٹوں کو بڑھانے کے لیے محنتی جنگ جاری رہی۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;ٹوک&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مسیر_کا_جائزہ&quot;&gt;مسیر کا جائزہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

actor Développeur as dev
actor &quot;opencode\n+ LLM&quot; as agent

package &quot;Home مستعمل (~)&quot; #LightGreen {
    package &quot;~/apps/&quot; {
        component &quot;VS Code
(ٹاربال)&quot; as vscode #SkyBlue
        component &quot;vscode-update.sh&quot; as script #LightYellow
    }
    package &quot;~/.config/Code/&quot; {
        component &quot;settings.json&quot; as settings #Lavender
    }
    package &quot;~/.vscode-custom-css/&quot; {
        component &quot;custom.css\n(zoom: 1.25)&quot; as customcss #Lavender
    }
}

cloud &quot;code.visualstudio.com&quot; as download

dev --&amp;gt; vscode : Télécharge &amp;amp; installe
dev --&amp;gt; script : Lance mise à jour
script --&amp;gt; download : wget dernière version
script --&amp;gt; vscode : Remplace + re-patch CSS
agent --&amp;gt; settings : Écrit config
agent --&amp;gt; customcss : Écrit zoom CSS
agent --&amp;gt; vscode : Patch workbench CSS

note right of vscode
  Installation dans le home
  = contrôle total sans sudo
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_کیوں_vs_code_گھر_میں&quot;&gt;کیوں: VS Code گھر میں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_نظام_کی_ان_اسٹالیشن_کا_مسئلہ&quot;&gt;نظام کی ان اسٹالیشن کا مسئلہ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;VS Code انسٹال ذریعے`apt`, &lt;code&gt;dnf`یا میں&lt;/code&gt;/opt`یہ ایپلیکیشن فائلوں کو ریشه کے حقوق کے پیچے بند کر دیتا ہے۔ نیٹیف CSS کی کوئی بھی تبدیلی،&lt;code&gt;product.json`یا انسٹالیشن فولڈر ضرورت رکھتا ہے`sudo&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اب، جب کسی اسے استعمال کرتا ہے&lt;strong&gt;opencode&lt;/strong&gt;(tool CLI اپنی کوڈ پر ایک LLM چلانے کے لیے) ایجنٹ کو کر سکنے کی ضرورت ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;لکھنا تنصیب فائلوں میں (&lt;code&gt;~/.config/Code/User/settings.json&lt;/code&gt;) — یہ، یہ پہلے سے ہی ہوم میں ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;IDE کے ایسیٹس (workbench کی CSS),&lt;code&gt;product.json&lt;/code&gt;) ادوار سیٹنگز کے لیے — یہ، سudo کے بغیر بلاک ہے&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_حل_ایک_مقامی_انسیٹلیشن&quot;&gt;حل : ایک مقامی انسیٹلیشن&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم رسمی tarball آرکائیو ڈاؤنلوڈ کرتے ہیں اور اسے direct طور پر decompress کرتے ہیں داخل`~/apps/`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;mkdir -p ~/apps
cd ~/apps
wget &quot;https://code.visualstudio.com/sha/download?build=stable&amp;amp;os=linux-x64&quot; -O vscode.tar.gz
tar -xzf vscode.tar.gz
rm vscode.tar.gz&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بائنری اب میں موجود ہے`~/apps/VSCode-linux-x64/bin/code`. کوئی نہیں`sudo`کسی فائل کو پڑھنے، ترمیم کرنے یا بدلنے کے لیے ضروری نہیں ہے زیر`~/apps/VSCode-linux-x64/`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ملموس_فائدے&quot;&gt;ملموس فائدے&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;نظام انسٹالیشن
(/opt, apt, dnf)&quot; #LightCoral {
    card &quot;VS Code root کی خاصیت&quot; {
        [CSS du workbench : sudo requis]
        [product.json : sudo requis]
        [Dossier d&#39;install : non modifiable]
    }
}

rectangle &quot;انسٹالیشن ہوم
(~/apps)&quot; #LightGreen {
    card &quot;VS Code صارف کی خاصیت&quot; {
        [CSS du workbench : libre]
        [product.json : libre]
        [Dossier d&#39;install : libre]
        [Script update maison]
    }
}

&quot;نظام انسٹالیشن
(/opt, apt, dnf)&quot; -right-&amp;gt; &quot;انسٹالیشن ہوم
(~/apps)&quot; : **Non, merci**\nJe prends le home

note bottom of &quot;انسٹالیشن ہوم
(~/apps)&quot;
  L&#39;agent opencode+LLM peut
  modifier les fichiers de l&#39;IDE
  sans aucune élévation de privilèges
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 66.6667%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;فائدہ&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;تفصیل&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Sudo نہیں&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;IDE کے تمام فائلیں صارف کے متعلق ہیں&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;CSS کی سست ترمیم&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;پچ کیا جا سکتا ہے`workbench.desktop.main.css`امتیازات کی اوپر اٹھانے کے بغیر&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ghar ka update script&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ایک سادہ شیل سکرپٹ خودکار طور پر ڈاؤن لوڈ کرتا ہے، بدلتا ہے اور دوبارہ پچ لگاتا ہے&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;عزلہ&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;نظام کی ان‑اسٹالیشن ملوث نہیں ہے؛ رول‑بیک = فولڈر حذف کریں&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_اصلی_منو_کی_فونٹ_کستومائز_کریں&quot;&gt;اصلی منو کی فونٹ کستومائز کریں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_نتیجہ&quot;&gt;نتیجہ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مینیو (File, Edit, View&amp;#8230;&amp;#8203;) اور ڈراپ ڈاؤنز کی ڈیفالٹ فونٹ بہت چھوٹی ہے۔ VS Code اسے تبدیل کرنے کے لیے کوئی سِٹنگ/پارامٹر نہیں فراہم کرتا۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تقنیت_css_مستقیم_پچ&quot;&gt;تقنیت : CSS مستقیم پچ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم فائل کے آخر میں CSS شامل کرتے ہیں`workbench.desktop.main.css`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor Développeur as dev
participant &quot;workbench.desktop
.main.css&quot; as css
participant &quot;product.json&quot; as product
participant &quot;VS کوڈ&quot; as vscode

== Patch CSS ==
dev -&amp;gt; css : Ajouter règles font-size\n(.menubar-menu-title, etc.)
dev -&amp;gt; vscode : Redémarrer VS Code
vscode -&amp;gt; vscode : Charge le CSS patché
vscode --&amp;gt; dev : Menus et dropdowns en 23px/22px ✓

== Suppression warning ==
vscode --&amp;gt; dev : ⚠️ &quot;آپ کی انسٹالیشن خراب ہے&quot;
dev -&amp;gt; product : Supprimer clé &quot;چیکسومز&quot;\n(python3 -c ...)
dev -&amp;gt; vscode : Redémarrer VS Code
vscode --&amp;gt; dev : Plus de warning ✓

note over css, product
  Deux fichiers dans ~/apps/
  = modifiables sans sudo
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;CSS_FILE=&quot;$HOME/apps/VSCode-linux-x64/resources/app/out/vs/workbench/workbench.desktop.main.css&quot;

cat &amp;gt;&amp;gt; &quot;$CSS_FILE&quot; &amp;lt;&amp;lt; &#39;EOF&#39;
.menubar-menu-title{font-size:23px!important}
.menubar&amp;gt;.menubar-menu-button{font-size:23px!important}
.monaco-menu-option{font-size:22px!important;line-height:34px!important}
.monaco-menu .action-label:not(.codicon){font-size:22px!important}
.menubar-menu-items-holder .monaco-menu .action-item .action-label{font-size:22px!important}
EOF&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_صحت_انتباہ_حذف_کریں&quot;&gt;صحت انتباہ حذف کریں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;VS Code apni files ki taghyīrāt ka izhar karta hai aur ek banner dikhata hai &quot;Your installation is corrupt&quot;. Iss se bachne ke liye, hum checksums ko hata dete hain.&lt;code&gt;product.json&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-python hljs&quot; data-lang=&quot;python&quot;&gt;import json
product_json = &quot;$HOME/apps/VSCode-linux-x64/resources/app/product.json&quot;
with open(product_json, &#39;r&#39;) as f:
    data = json.load(f)
data.pop(&#39;checksums&#39;, None)
with open(product_json, &#39;w&#39;) as f:
    json.dump(data, f, indent=2)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ریسٹارت کے بعد warnings نہیں ہیں اور منو واضح ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ایکسپلورر_پین_کی_فونٹ_کو_ترتیب_دیں_جگڑا&quot;&gt;ایکسپلورر پین کی فونٹ کو ترتیب دیں — جگڑا&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_آزمائش_1_پیرامیٹر_جو_موجود_نہیں&quot;&gt;آزمائش 1 : پیرامیٹر جو موجود نہیں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم اصل پارامٹر کو پہلے کوشش کرتے ہیں`workbench.tree.fontSize`میں`settings.json`(Empty output)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
    &quot;workbench.tree.fontSize&quot;: 20
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نتیجہ :&lt;strong&gt;کوئیاثر نہیں&lt;/strong&gt;. یہ سیٹنگ VS Code میں موجود نہیں ہے۔ دلیل یہ ہے کہ معترف نہیں ہونے والی سیٹنگ‌ها خاموشی سے نادیده کر دی جاتی ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تجربہ_2_کاسٹم_css_and_js_loader_ایکسٹینشن&quot;&gt;تجربہ 2 : کاسٹم CSS and JS Loader ایکسٹینشن&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم ایکسٹنشن انسیٹ کر رہے ہیں`be5invis.vscode-custom-css`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;~/apps/VSCode-linux-x64/bin/code --install-extension be5invis.vscode-custom-css&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم ایک CSS فائل بناتے ہیں`~/.vscode-custom-css/custom.css`explorer کے عناصر کو نشانہ بنانے والے سلیکٹر کے ساتھ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.monaco-tree-rows .monaco-tree-row,
.sidebar .monaco-list-row,
.explorer-viewlet .monaco-list-row,
.monaco-list-row .monaco-icon-label {
    font-size: 22px !important;
    line-height: 36px !important;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اور ہم اس فائل کو سٹنگز میں رفرنس کرتے ہیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
    &quot;vscode_custom_css.imports&quot;: [
        &quot;file:///home/user/.vscode-custom-css/custom.css&quot;
    ]
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نتیجہ :&lt;strong&gt;تبدیلات لاگو نہیں ہوتی&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_پھنساں_ہر_بار_ایکسٹینشن_فعال_کرنا_ضروری_ہے&quot;&gt;پھنساں : ہر بار ایکسٹینشن فعال کرنا ضروری ہے&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایکسٹنشن کی دستاویز اس اہم نک پر خفیف ہے: ہر CSS custom کی ترمیم کے بعد، کرنا ضروری ہے&lt;strong&gt;ضروری طور پر&lt;/strong&gt;پالیٹ سے کمانڈ چلائیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;Ctrl+Shift+P&lt;/code&gt;→ ٹائپ کرنا&lt;strong&gt;کاستم CSS اور JS فعال کریں&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;VS Code ایک ریستارت کی درخواست کرتا ہے → قبول کریں&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اس مرحلے کے بغیر، CSS کبھی بھی IDE میں انجیکٹ نہیں ہوتا۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تجربہ_3_لائنز_ایک_دوسرے_کے_اوپر_آ_جاتی_ہیں&quot;&gt;تجربہ 3 : لائنز ایک دوسرے کے اوپر آ جاتی ہیں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بھی ساتھ`font-size: 22px` et &lt;code&gt;line-height: 36px&lt;/code&gt;, ذیل والے حروف (g, p, f, b) قربانی خطوط پر پھیل جاتے ہیں. ہم اضافہ کرنے کی کوشش کر رہے ہیں`height` et &lt;code&gt;min-height&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.monaco-list-row {
    height: 36px !important;
    min-height: 36px !important;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نتیجہ:&lt;strong&gt;کوئی تبدیلی نہیں&lt;/strong&gt;. VS Code لائنوں کی اونچائیں جاواسکریپٹ میں حساب کرتا ہے اور CSS کی قيمتیں اووررائیڈ کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_حل_zoom_پر_والد_کنٹینر&quot;&gt;حل: &lt;code&gt;zoom&lt;/code&gt; پر والد کنٹینر&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;کوشش 1
پیرامیٹر موجود نہیں&quot; #LightCoral {
    card &quot;workbench.tree.fontSize&quot; as t1 {
        [VS Code ignore le paramètre]
    }
}

rectangle &quot;محاولہ 2
کسٹم CSS + فونٹ سائز&quot; #LightYellow {
    card &quot;.monaco-list-row { font-size: 22px }&quot; as t2 {
        [Texte plus grand\nmais lignes superposées]
    }
}

rectangle &quot;امتحانی 3
font-size + line-height + height&quot; #LightYellow {
    card &quot;height: 36px !important&quot; as t3 {
        [VS Code override\npar JavaScript]
        [Aucun effet]
    }
}

rectangle &quot;حل
والد کنٹینر پر زوم&quot; #LightGreen {
    card &quot;.monaco-list-rows { zoom: 1.25 }&quot; as t4 {
        [Texte + espacement\nproportionnels]
        [Layout JS respecté]
        [✓ Résultat conforme]
    }
}

t1 -down-&amp;gt; t2 : Pas de paramètre ?\nOn essaie le CSS
t2 -down-&amp;gt; t3 : Lignes superposées ?\nOn force la hauteur
t3 -down-&amp;gt; t4 : Override JS ?\nOn utilise zoom

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جاواسکریپٹ کے لاء آؤٹ کے مقابلے میں لڑنے کی جگہ ہم خاصیت استعمال کرتے ہیں`zoom`لائنوں کے کنٹینر پر:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.explorer-viewlet .monaco-list-rows,
.sidebar .monaco-list-rows {
    zoom: 1.25;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`zoom`یہ کٹینر کے رینڈرنگ — متنی اور فاصلہ — کویکساں طور پر بڑھاتا ہے، VS Code کے جاواسکریپٹ انجن کے حساب سے لگئی لاوٹ کو توڑا نہیں۔ عامل 1.25 تقریباً 13px سے 16px کے转换 کے مساوی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نتیجہ :&lt;strong&gt;فائل کے نام اب پڑھنے کے قابل ہیں، اور لائن صحیح طور پر فاصلے رکھتی ہیں&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_سیلیکٹورز_کا_خلاصہ_اور_جو_کام_کرتا_ہے&quot;&gt;سیلیکٹورز کا خلاصہ اور جو کام کرتا ہے&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 25%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 25%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;اپروچ&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;CSS&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;نتیجہ&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;font-size`پر&lt;/code&gt;.monaco-list-row`&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;font-size: 22px !important&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;بڑا متن لیکن overlap والی لائنیں&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;line-height&lt;/code&gt;+&lt;code&gt;height`پر&lt;/code&gt;.monaco-list-row`&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;line-height: 36px; height: 36px&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;کوئی اثر نہیں (override JS)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;zoom`پر&lt;/code&gt;.monaco-list-rows`&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;zoom: 1.25&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ناجح — متن + فاصلہ نسبتی&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_خودکار_اپ_ڈیٹ_سکرپٹ&quot;&gt;خودکار اپ ڈیٹ سکرپٹ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;ڈویلپر
یا cron&quot; as dev
participant &quot;vscode-update.sh&quot; as script
participant &quot;vscode ٹاربال
(code.visualstudio.com)&quot; as remote
participant &quot;~/apps/\nVSCode-linux-x64/&quot; as local
participant &quot;~/apps/\nvscode-backup/&quot; as backup
participant &quot;کام کا بنچ
.desktop.main.css&quot; as css
participant &quot;product.json&quot; as product

dev -&amp;gt; script : ./vscode-update.sh
script -&amp;gt; local : Lire version courante
script -&amp;gt; remote : wget dernière version
script -&amp;gt; script : Comparer versions

alt Version identique
    script --&amp;gt; dev : &quot;ابھی سے اپ ڈیٹ ہے!&quot;
else Nouvelle version
    script -&amp;gt; backup : Sauvegarder installation courante\n(horodatée)
    script -&amp;gt; local : rm -rf ancienne installation
    script -&amp;gt; local : mv nouvelle installation
    script -&amp;gt; css : Ajouter patch CSS\n(menubar 23px, dropdown 22px)
    script -&amp;gt; product : Supprimer checksums\n(python3)
    script --&amp;gt; dev : &quot;اپ ڈیٹ مکمل
1.xx.yy → 1.zz.ww&quot;
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مشکل&quot;&gt;مشکل&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;VS Code کے اپ ڈیٹ ہونے پر، وہ انسٹال کرنے والے فولڈر کو بدل دیتا ہے اور&lt;strong&gt;تمام CSS پچوں کو حذف کرتا ہے&lt;/strong&gt;ہر بار دستی طور پر ترمیمات کو دوبارہ لاگو کرنا ضروری ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اسکرپٹ_vscode_update_sh&quot;&gt;اسکرپٹ `vscode-update.sh&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم بناتے ہیں`~/apps/vscode-update.sh`(Empty output)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;#!/bin/bash
set -e

VSCODE_DIR=&quot;$HOME/apps/VSCode-linux-x64&quot;
BACKUP_DIR=&quot;$HOME/apps/vscode-backup&quot;
TEMP_DIR=&quot;/tmp/vscode-update&quot;

MENUBAR_FONT_SIZE=&quot;23px&quot;
DROPDOWN_FONT_SIZE=&quot;22px&quot;

echo &quot;=== VS Code Local Updater ===&quot;

CURRENT_VERSION=$(&quot;$VSCODE_DIR/bin/code&quot; --version 2&amp;gt;/dev/null | head -1)
echo &quot;Current version: $CURRENT_VERSION&quot;

echo &quot;Downloading latest VS Code...&quot;
mkdir -p &quot;$TEMP_DIR&quot;
wget -q &quot;https://code.visualstudio.com/sha/download?build=stable&amp;amp;os=linux-x64&quot; \
    -O &quot;$TEMP_DIR/vscode.tar.gz&quot;

echo &quot;Extracting...&quot;
mkdir -p &quot;$TEMP_DIR/extracted&quot;
tar -xzf &quot;$TEMP_DIR/vscode.tar.gz&quot; -C &quot;$TEMP_DIR/extracted&quot;

NEW_VERSION=$(&quot;$TEMP_DIR/extracted/VSCode-linux-x64/bin/code&quot; \
    --version 2&amp;gt;/dev/null | head -1)
echo &quot;New version: $NEW_VERSION&quot;

if [ &quot;$CURRENT_VERSION&quot; = &quot;$NEW_VERSION&quot; ]; then
    echo &quot;Already up to date!&quot;
    rm -rf &quot;$TEMP_DIR&quot;
    exit 0
fi

echo &quot;Backing up current installation...&quot;
mkdir -p &quot;$BACKUP_DIR&quot;
cp -r &quot;$VSCODE_DIR&quot; &quot;$BACKUP_DIR/VSCode-linux-x64-$(date +%Y%m%d-%H%M%S)&quot;

echo &quot;Updating...&quot;
rm -rf &quot;$VSCODE_DIR&quot;
mv &quot;$TEMP_DIR/extracted/VSCode-linux-x64&quot; &quot;$VSCODE_DIR&quot;
rm -rf &quot;$TEMP_DIR&quot;

CSS_FILE=&quot;$VSCODE_DIR/resources/app/out/vs/workbench/workbench.desktop.main.css&quot;
echo &quot;Re-applying custom CSS patch \
    (menubar=${MENUBAR_FONT_SIZE}, dropdown=${DROPDOWN_FONT_SIZE})...&quot;
cat &amp;gt;&amp;gt; &quot;$CSS_FILE&quot; &amp;lt;&amp;lt; CSSEOF
.menubar-menu-title{font-size:${MENUBAR_FONT_SIZE}!important}\
.menubar&amp;gt;.menubar-menu-button{font-size:${MENUBAR_FONT_SIZE}!important}\
.monaco-menu-option{font-size:${DROPDOWN_FONT_SIZE}!important;\
line-height:34px!important}\
.monaco-menu .action-label:not(.codicon)\
{font-size:${DROPDOWN_FONT_SIZE}!important}\
.menubar-menu-items-holder .monaco-menu .action-item .action-label\
{font-size:${DROPDOWN_FONT_SIZE}!important}
CSSEOF

PRODUCT_JSON=&quot;$VSCODE_DIR/resources/app/product.json&quot;
if [ -f &quot;$PRODUCT_JSON&quot; ]; then
    echo &quot;Removing checksums to prevent integrity warning...&quot;
    python3 -c &quot;
import json
with open(&#39;$PRODUCT_JSON&#39;,&#39;r&#39;) as f: data=json.load(f)
data.pop(&#39;checksums&#39;, None)
with open(&#39;$PRODUCT_JSON&#39;,&#39;w&#39;) as f: json.dump(data,f,indent=2)
print(&#39;Done.&#39;)
&quot;
fi

echo &quot;=== Update complete: $CURRENT_VERSION -&amp;gt; $NEW_VERSION ===&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اسکریپٹ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;آخری مستحکم ورژن ڈاؤنلوڈ کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;جائزہ لیں کہ آیا ورژن موجودہ سے مختلف ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;موجودہ انسٹالیشن (ٹائم اسٹیمپ شدہ) میں محفوظ کریں`~/apps/vscode-backup/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;انسٹالنگ فولدہ بدل دیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;دوبارہ لاگو کریں&lt;/strong&gt;CSS کا پچ بنیادی منو&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;چیک سمرز حذف کریں&lt;/strong&gt; de `product.json`انٹیگریٹی warning سے بچنے کے لئے&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نوٹ: ایکسپ्लورر پین کی کستمائزیشنز، Custom CSS ایسٹینشън اور فائل کے ذریعے`~/.vscode-custom-css/custom.css`یہ اپ ڈیٹس سے بچ جاتے ہیں کیونکہ وہ انسٹالیشن فولدر کے باہر رہتے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ملحق_فائلز_مجموعی_جائزہ&quot;&gt;ملحق فائلز — مجموعی جائزہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

rectangle &quot;VS Code کی انسٹالیشن
(~/apps/VSCode-linux-x64/)&quot; #LightCoral {
    component &quot;workbench.desktop\n.main.css&quot; as css #LightCoral
    component &quot;product.json&quot; as product #LightCoral
    component &quot;بائنری
bin/code&quot; as binary #LightCoral
}

rectangle &quot;صارف کی تنظیم\n(~/.config/Code/)&quot; #LightGreen {
    component &quot;settings.json&quot; as settings #LightGreen
    component &quot;ایکسٹینشنز/&quot; as extensions #LightGreen
}

rectangle &quot;مستمر کیسٹومائزیشن\n(~/.vscode-custom-css/)&quot; #SkyBlue {
    component &quot;custom.css\n(zoom: 1.25)&quot; as customcss #SkyBlue
}

rectangle &quot;خودکاری
(~/apps/)&quot; #LightYellow {
    component &quot;vscode-update.sh&quot; as script #LightYellow
    component &quot;vscode-backup/&quot; as backup #LightYellow
}

script ..&amp;gt; css : Re-patch après MAJ
script ..&amp;gt; product : Supprime checksums\naprès MAJ
settings --&amp;gt; customcss : Référence via\nvscode_custom_css.imports
extensions ..&amp;gt; css : Custom CSS Loader\ninjecte custom.css

note bottom of css
  **Ne survit pas** aux mises à jour
  Re-patché par le script
end note

note bottom of customcss
  **Survit** aux mises à jour
  Vit hors du dossier d&#39;installation
end note

note bottom of settings
  **Survit** aux mises à jour
  Vit dans ~/.config/
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
