&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_سیخے_سباقات&quot;&gt;سیخے سباقات&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontName sans-serif
skinparam ArrowColor #444444

rectangle &quot;**مقامی تنصیب**\n ہوم میں&quot; as install #LightGreen {
    card &quot;sudo ضرورت نہیں
 CSS/config کو تبدیل کرنے کے لیے&quot; as i1
    card &quot;opencode+LLM
 سب چیزیں بدل سکتا ہے&quot; as i2
    card &quot;Rollback = بحال کرنا
 ٹائم اسٹیمپڈ بیکاپ&quot; as i3
}

rectangle &quot;CSS کی تخصیص
زوم مقابل فونٹ سائز&quot; as css #LightYellow {
    card &quot;zoom &amp;gt; font-size
 کمپوننتس کی فہرست کے لیے&quot; as c1
    card &quot;Layout JS اوورائز
 اونچائی/لائن-ہائیٹ&quot; as c2
    card &quot;ایکسٹنشن CSS کستم
کچاہی ضروری ہے
م دستی (Ctrl+Shift+P)&quot; as c3
}

rectangle &quot;**خودکار**
 اپ ڈیٹ سکرپٹ&quot; as auto #LightCoral {
    card &quot;CSS کو بعد میں دوبارہ پچ
 ہر اپ ڈیٹ&quot; as a1
    card &quot;حذف کریں checksums\n product.json&quot; as a2
    card &quot;ٹائم اسٹیمپڈ بیکاپ
بَدَل سے پہلے&quot; as a3
}

install -right-&amp;gt; css : ensuite
css -right-&amp;gt; auto : enfin

note top of install
  Contrôle total sans élévation
  de privilèges
end note

note top of auto
  Sans script, chaque MAJ
  efface les patches CSS
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_گھر_میں_انسٹال_کرنے_سے_سب_چیزیں_آزاد_ہو_جاتی_ہیں&quot;&gt;گھر میں انسٹال کرنے سے سب چیزیں آزاد ہو جاتی ہیں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک مقامی انسٹالیشن میں`~/apps`VS Code پر مکمل اختیار دیتا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;نہیں`sudo`CSS یا کنفیگریشن کو ترمیم کرنے کے لیے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;opencode+LLM ایجنٹ IDE کے کنفیگ فائلیں اور ایسیٹس میں لکھ سکتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ساده رول بیک : بیکاپ کی ٹائم اسٹیمپڈ بحال کریں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_zoom_font_size_لیسٹ_کامپوننٹس_کے_لیے&quot;&gt;zoom` &amp;gt; &lt;code&gt;font-size&lt;/code&gt; لیسٹ کامپوننٹس کے لیے&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;VS Code JavaScript کے ذریعے لائنوں کی اونچے کو کنٹرول کرتا ہے۔ تحرير کریں`font-size`لی آؤٹ انجن کی فراہم کردہ اونچائی پر ہاتھ لگانے سے ممانعت ہونے پر یہ متنیں بناتی ہیں جو باہر نکلتے ہیں۔ خاصیت`zoom`والد کنٹینر پر سب کو تناسباً بڑھایا جاتا ہے اور اس مسئلے سے بچا جاتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_custom_css_ایکسٹینشن_کو_صریح_اکٹیویشن_کی_ضرورت_ہوتی_ہے&quot;&gt;Custom CSS ایکسٹینشن کو صریح اکٹیویشن کی ضرورت ہوتی ہے&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ &quot;set and forget&quot; پارامیٹر نہیں ہے۔ CSS custom فائل کی ہر تبدیلی کے بعد &quot;Enable Custom CSS and JS&quot; کو کمانڈ پیلٹ سے دوبارہ چلانا ضروری ہے (&lt;code&gt;Ctrl+Shift+P&lt;/code&gt;)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ایک_اپ_ڈیٹ_سکرپٹ_ضروری_ہے&quot;&gt;ایک اپ ڈیٹ سکرپٹ ضروری ہے&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اسکرپٹ کے بغیر، VS Code کی ہر اپ ڈیٹ workbench کے CSS patches کو حذف کر دیتی ہے۔ اسکرپٹ`vscode-update.sh`یہ ڈاؤنلوڈ، تعویض، دوبارہ پیچنگ اور چیک سمرماتس کی صافکاری خودکار طور پر کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_جلدی_حوالے&quot;&gt;جلدی حوالے&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;VS Code ڈاؤنلوڈ: &lt;a href=&quot;https://code.visualstudio.com/Download&quot; class=&quot;bare&quot;&gt;https://code.visualstudio.com/Download&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ایسٹینشن کسٹم CSS اور JS لوڈر :`be5invis.vscode-custom-css`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;VS Code کا ایشو Explorer کے فونٹ کے لیے ایک نativ (نظامی) سیٹنگ مانگا رہا ہے :https://github.com/microsoft/vscode/issues/149[github.com/microsoft/vscode#149]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table des matières&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_سیاق_و_مقصد&quot;&gt;سیاق و مقصد&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_شروع_کرنے_کا_נקutta&quot;&gt;شروع کرنے کا נקutta&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_الهدف&quot;&gt;الهدف&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_پہلا_رکاوٹ_ruby_gems&quot;&gt;پہلا رکاوٹ : `ruby { gems() }&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_گراوی_کے_سینٹیکس_شُگر_جو_چھپاتا_ہے&quot;&gt;گراوی کے سینٹیکس شُگر جو چھپاتا ہے&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مکانیزم_کا_تجزئة&quot;&gt;مکانیزم کا تجزئة&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_تیس_حصوں_کا_حل&quot;&gt;تیس حصوں کا حل&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_حصہ_1_آئی_وی_ریپو_rubygems_کے_لیے&quot;&gt;حصہ 1 : آئی وی ریپو RubyGems کے لیے&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_حصہ_2_اسکیڈاکٹر_جیمز_پر_انحصار&quot;&gt;حصہ 2: اسکیڈاکٹر جیمز پر انحصار&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_بخش_3_settings_gradle_kts&quot;&gt;بخش 3 : settings.gradle.kts&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_api_کی_انٹروسپکشن_بائٹ_کوڈز_سے&quot;&gt;API کی انٹروسپکشن بائٹ کوڈز سے&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_کیوں_javap&quot;&gt;کیوں &lt;code&gt;javap&lt;/code&gt; ?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_کام_کی_ہئرچھی&quot;&gt;کام کی ہئرچھی&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_كشف_forkoptions&quot;&gt;كشف `forkOptions&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_جافافورک_آپشنز_grolifant_کی_api&quot;&gt;جافافورک آپشنز (grolifant) کی API&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_revealjsextension&quot;&gt;RevealJSExtension&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_جاوے_ٹولچین_کی_کنفیگریشن&quot;&gt;جاوے ٹولچین کی کنفیگریشن&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_javatoolchainservice_کا_مسئلہ&quot;&gt;JavaToolchainService کا مسئلہ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ڈوکر_خودکار_تشخیص&quot;&gt;ڈوکر خودکار تشخیص&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_سیاق&quot;&gt;سیاق&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_استراتژی&quot;&gt;استراتژی&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_نتیجہ_خاتم&quot;&gt;نتیجہ خاتم&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_صارف_buildscript&quot;&gt;صارف buildscript&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_settings_gradle_kts&quot;&gt;settings.gradle.kts&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_جالات_اور_حل_کی_خلاصہ&quot;&gt;جالات اور حل کی خلاصہ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_تحقیق_کا_طریقہ_جاویپ_سے_نامعلوم_api_پڑھنا&quot;&gt;تحقیق کا طریقہ : جاویپ سے نامعلوم API پڑھنا&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_اصل&quot;&gt;اصل&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحلہ_1_گریڈل_کیش_میں_جار_کو_ڈھونڈیں&quot;&gt;مرحلہ 1: گریڈل کیش میں جار کو ڈھونڈیں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحلہ_2_jar_کی_کلاسوں_کی_فہرست_بنانا&quot;&gt;مرحلہ 2: jar کی کلاسوں کی فہرست بنانا&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحلہ_3_کلاس_کا_جائزہ_لیں&quot;&gt;مرحلہ 3 : کلاس کا جائزہ لیں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحلہ_4_ہyerarkey_اوپر_جاؤ&quot;&gt;مرحلہ 4: ہyerarkey اوپر جاؤ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحلہ_5_غیر_معروف_انواع_کی_پیروی_کریں&quot;&gt;مرحلہ 5: غیر معروف انواع کی پیروی کریں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحلہ_6_پروجیکٹ_کے_ایسٹینشنز_جانچ_کریں&quot;&gt;مرحلہ 6: پروجیکٹ کے ایسٹینشنز جانچ کریں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_طریقے_کا_خلاصہ&quot;&gt;طریقے کا خلاصہ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_اگلا_مرحلہ&quot;&gt;اگلا مرحلہ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_سیاق_و_مقصد&quot;&gt;سیاق و مقصد&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_شروع_کرنے_کا_נקutta&quot;&gt;شروع کرنے کا נקutta&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پروجیکٹ`slider-gradle`Gradle پلاگین کے ذریعے AsciiDoc فائلوں سے Reveal.js پیشنِیشنز بناتا ہے`org.asciidoctor.jvm.revealjs`. مرکزی کام کی تنظیم`asciidoctorRevealJs`جڑ buildscript میں بی واسطہ رہتا تھا`build.gradle.kts`(No output - empty string)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;plugins { id(&quot;org.asciidoctor.jvm.revealjs&quot;) }

apply&amp;lt;slides.SlidesPlugin&amp;gt;()

project.tasks.getByName&amp;lt;AsciidoctorJRevealJSTask&amp;gt;(TASK_ASCIIDOCTOR_REVEALJS) {
    repositories { ruby { gems() } }
    revealjs {
        version = &quot;3.1.0&quot;
        templateGitHub {
            setOrganisation(&quot;hakimel&quot;)
            setRepository(&quot;reveal.js&quot;)
            setTag(&quot;3.9.1&quot;)
        }
    }
    revealjsOptions {
        // ... configuration complète
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_الهدف&quot;&gt;الهدف&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اس تمام کنفیگریشن میں منتقل کریں`buildSrc/src/main/kotlin/slides/SlidesPlugin.kt`اس طوریے سے کہ consumerscript buildscript کم ہو جائے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;apply&amp;lt;slides.SlidesPlugin&amp;gt;()&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پلاگین کو مکمل طور پر خودمختار ہونا چاہیے: وہ خود اپنی پلاگین کی انحصارات لاگو کرتا ہے، اپنے ریپوزٹریز کنفیجر کرتا ہے، اور اپنی روبی gems کو منجاتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_پہلا_رکاوٹ_ruby_gems&quot;&gt;پہلا رکاوٹ : `ruby { gems() }&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_گراوی_کے_سینٹیکس_شُگر_جو_چھپاتا_ہے&quot;&gt;گراوی کے سینٹیکس شُگر جو چھپاتا ہے&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;خط`repositories { ruby { gems() } }`یہ Groovy DSL ایک extension ہے جو صرف buildscript کے execution context میں دستیاب ہے۔ یہ buildSrc سے قابل رسائی ہونے والی/static Kotlin API نہیں ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اس کو فون کرنے کی کوشش کرتے ہوئے`SlidesPlugin.kt`, کمپائلش فوراً ناکام ہو جاتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مکانیزم_کا_تجزئة&quot;&gt;مکانیزم کا تجزئة&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;گریڈل کییش کا تجزیہ کرنے کے بعد (&lt;code&gt;~/.gradle/caches/modules-2/files-2.1/rubygems/&lt;/code&gt;), فائل میں پاتا جاتا ہے`ivy-3.1.0.xml` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;artifact type=&#39;gem&#39; url=&#39;https://rubygems.org/gems/asciidoctor-revealjs-3.1.0.gem&#39; /&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`ruby { gems() }`واقع میں کر رہا تھا&lt;strong&gt;تلات الگ آپریشن&lt;/strong&gt; :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;ایوی ریپو کو &amp;#8230;&amp;#8203; کی طرف انظار رکھتے ہوئے محفوظ کریں`https://rubygems.org/gems/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;گروپ کو خارج کریں`rubygems`Maven کے ریپوزٹریوں کے لئے ٹکراؤ سے بچنے کے لیے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;gem کو کنفیگری میں محفوظ کریں`asciidoctorGems`جس طرح سے JRuby اسے رنٹائم پر لوڈ کرتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ان تین ذمہ داریوں کو Kotlin میں الگ الگ سے دوبارہ تیار کرنا ہوگا۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_تیس_حصوں_کا_حل&quot;&gt;تیس حصوں کا حل&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_حصہ_1_آئی_وی_ریپو_rubygems_کے_لیے&quot;&gt;حصہ 1 : آئی وی ریپو RubyGems کے لیے&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;project.repositories.mavenCentral() {
    content { excludeGroup(&quot;rubygems&quot;) }
}
project.repositories.ivy {
    url = project.uri(&quot;https://rubygems.org/gems/&quot;)
    patternLayout { artifact(&quot;[module]-[revision].gem&quot;) } &lt;i class=&quot;conum&quot; data-value=&quot;1&quot;&gt;&lt;/i&gt;&lt;b&gt;(1)&lt;/b&gt;
    metadataSources { artifact() }
    content { includeGroup(&quot;rubygems&quot;) }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;colist arabic&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td&gt;&lt;i class=&quot;conum&quot; data-value=&quot;1&quot;&gt;&lt;/i&gt;&lt;b&gt;1&lt;/b&gt;&lt;/td&gt;
&lt;td&gt;اضافہ`.gem`اسے ہارڈ کوڈ کردینا چاہیے۔&lt;code&gt;[ext]`ڈیفالٹ میں حل کرتا ہے&lt;/code&gt;.jar`, جس سے ایک غلطی ہوتی ہے`Resource missing`.&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نوٹ: آئی وی ریpository (Ivy) مستقیماً بیان کیا گیا پر`project.repositories` اور ایک بلاک میں نہیں`repositories { }`کیونکہ اس بلوک کا ریسیور یہ نہیں`RepositoryHandler`Gradle کا معیار لیکن ایک API grolifant extension کے ساتھ موافق نہیں`ivy`Kotlin DSL.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_حصہ_2_اسکیڈاکٹر_جیمز_پر_انحصار&quot;&gt;حصہ 2: اسکیڈاکٹر جیمز پر انحصار&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پلاگ ان`org.asciidoctor.jvm.gems`پہلا لاگو کرنا چاہیے — یہ کنفیگری بناتا ہے`asciidoctorGems`و کار`asciidoctorGemsPrepare` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;project.plugins.apply(&quot;org.asciidoctor.jvm.gems&quot;)
project.plugins.apply(&quot;org.asciidoctor.jvm.revealjs&quot;) &lt;i class=&quot;conum&quot; data-value=&quot;1&quot;&gt;&lt;/i&gt;&lt;b&gt;(1)&lt;/b&gt;

project.dependencies {
    add(&quot;asciidoctorGems&quot;, &quot;rubygems:asciidoctor-revealjs:3.1.0@gem&quot;) &lt;i class=&quot;conum&quot; data-value=&quot;2&quot;&gt;&lt;/i&gt;&lt;b&gt;(2)&lt;/b&gt;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;colist arabic&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td&gt;&lt;i class=&quot;conum&quot; data-value=&quot;1&quot;&gt;&lt;/i&gt;&lt;b&gt;1&lt;/b&gt;&lt;/td&gt;
&lt;td&gt;لاگو کرنے کا ترتيب اہم ہے :`gems`پہلے`revealjs`. &amp;lt;2&amp;gt; معیار`@gem`انحصار پر صحیح ایکسٹینشن لاگو کریں&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_بخش_3_settings_gradle_kts&quot;&gt;بخش 3 : settings.gradle.kts&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`dependencyResolutionManagement`میں`settings.gradle.kts`پروجیکٹس اپنی اپنی ریپوزٹریوں کو اعلان کرنے کی اجازت دینا چاہیے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Suppress(&quot;UnstableApiUsage&quot;)
dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.PREFER_PROJECT)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اس لائن کے بغیر، Gradle پلاگن میں اعلان کردہ ریپازٹریوں کو نظرانداز کرتا ہے اور gemز کی حل خراب ہو جاتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_api_کی_انٹروسپکشن_بائٹ_کوڈز_سے&quot;&gt;API کی انٹروسپکشن بائٹ کوڈز سے&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کیوں_javap&quot;&gt;کیوں &lt;code&gt;javap&lt;/code&gt; ?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پلاگین`asciidoctor-gradle-jvm-slides`نسخة میں`4.0.0-alpha.1`. اس کی دستاویزات غیر موجودہ یا ناقص ہیں۔ ایکمتبادل معتبر ذریعہ صرف مستخرج کلاسوں کی مستقیم تفتیش ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کام_کی_ہئرچھی&quot;&gt;کام کی ہئرچھی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;javap -p -classpath asciidoctor-gradle-jvm-slides-4.0.0-alpha.1.jar \
  org.asciidoctor.gradle.jvm.slides.AsciidoctorJRevealJSTask&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نتیجہ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;public class AsciidoctorJRevealJSTask
  extends org.asciidoctor.gradle.jvm.AbstractAsciidoctorTask
  implements org.asciidoctor.gradle.base.slides.SlidesToExportAware&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_كشف_forkoptions&quot;&gt;كشف `forkOptions&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جائزہ لیتے`AbstractAsciidoctorTask`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;javap -p -classpath asciidoctor-gradle-jvm-4.0.0-alpha.1.jar \
  org.asciidoctor.gradle.jvm.AbstractAsciidoctorTask | grep -i &quot;fork\|exec\|jvm&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پایا جاتا ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;final org.ysb33r.grolifant.api.v4.JavaForkOptions javaForkOptions;
public void forkOptions(org.gradle.api.Action&amp;lt;org.ysb33r.grolifant.api.v4.JavaForkOptions&amp;gt;);
public static final org.asciidoctor.gradle.base.process.ProcessMode JAVA_EXEC;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_جافافورک_آپشنز_grolifant_کی_api&quot;&gt;جافافورک آپشنز (grolifant) کی API&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`javaLauncher`یہ کام پر موجود نہیں ہے۔ واقعی API کا`org.ysb33r.grolifant.api.v4.JavaForkOptions`عرض :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;public void executable(java.lang.Object);  &lt;i class=&quot;conum&quot; data-value=&quot;1&quot;&gt;&lt;/i&gt;&lt;b&gt;(1)&lt;/b&gt;
public void setExecutable(java.lang.Object);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;colist arabic&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td&gt;&lt;i class=&quot;conum&quot; data-value=&quot;1&quot;&gt;&lt;/i&gt;&lt;b&gt;1&lt;/b&gt;&lt;/td&gt;
&lt;td&gt;طریقہ`executable(Object)`املا بدل دیتی ہے`executable = &amp;#8230;&amp;#8203;`جو کامپائل نہیں ہوتا (`val`نہیں دوبارہ قدر دی جا سکتا ہے).&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_revealjsextension&quot;&gt;RevealJSExtension&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`revealjs { }`یہ ٹاسک کا طریقہ نہیں بلکہ ایک&lt;strong&gt;پروجیکٹ کی extension&lt;/strong&gt; :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;javap -p -classpath asciidoctor-gradle-jvm-slides-4.0.0-alpha.1.jar \
  org.asciidoctor.gradle.jvm.slides.RevealJSExtension&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ رسائی کے ذریعے حاصل ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;project.extensions.getByType&amp;lt;RevealJSExtension&amp;gt;().apply {
    version = &quot;3.1.0&quot;
    templateGitHub {
        setOrganisation(&quot;hakimel&quot;)
        setRepository(&quot;reveal.js&quot;)
        setTag(&quot;3.9.1&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_جاوے_ٹولچین_کی_کنفیگریشن&quot;&gt;جاوے ٹولچین کی کنفیگریشن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_javatoolchainservice_کا_مسئلہ&quot;&gt;JavaToolchainService کا مسئلہ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`JavaToolchainService`یہ پروجیکٹ کی اضافہ نہیں ہے۔ مندرجہ ذیل کال ناموظف ہو جاتا ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// ERREUR : Extension of type &#39;JavaToolchainService&#39; does not exist
project.extensions.getByType&amp;lt;JavaToolchainService&amp;gt;()&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;درست API ہے`serviceOf`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;import org.gradle.kotlin.dsl.support.serviceOf

project.tasks.getByName&amp;lt;AsciidoctorJRevealJSTask&amp;gt;(TASK_ASCIIDOCTOR_REVEALJS) {
    setInProcess(&quot;JAVA_EXEC&quot;)
    forkOptions {
        executable(
            project.serviceOf&amp;lt;JavaToolchainService&amp;gt;()
                .launcherFor {
                    languageVersion.set(JavaLanguageVersion.of(17))
                    vendor.set(JvmVendorSpec.ADOPTIUM)
                }
                .get()
                .executablePath
                .asFile
                .absolutePath
        )
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ڈوکر_خودکار_تشخیص&quot;&gt;ڈوکر خودکار تشخیص&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_سیاق&quot;&gt;سیاق&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Asciidoctor/JRuby پلاگین Java 17 کی ضرورت ہوتی ہے۔ Kotlin 2.0.x buildSrc میں Java 25 کی سپورٹ نہیں کرتا۔ (ورژن پارس کراش ہوتا ہے پر`&quot;25.0.2&quot;`) گریڈیل ڈیمون کو اس لیے جاوا 17 پر چلنا پڑتا ہے یا ڈاکر استعمال کرنا پڑے گا۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_استراتژی&quot;&gt;استراتژی&lt;/h3&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Docker دستیاب → اجرا کے زیرے container`eclipse-temurin:17`(پیش فرض رویہ)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ڈوکر غائب + جاوے 17 → مقامی تنفیذ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Docker موجود نہیں + Java &amp;gt; 17 → واضح خطا&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val isDockerAvailable = try {
    Runtime.getRuntime().exec(arrayOf(&quot;docker&quot;, &quot;info&quot;)).waitFor() == 0
} catch (e: Exception) {
    false
}

val javaVersion = JavaVersion.current().majorVersion.toInt()

when {
    isDockerAvailable -&amp;gt; project.tasks.register&amp;lt;Exec&amp;gt;(TASK_ASCIIDOCTOR_REVEALJS) {
        group = GROUP_TASK_SLIDER
        description = &quot;Slider settings and generation (via Docker)&quot;
        dependsOn(TASK_CLEAN_SLIDES_BUILD)
        finalizedBy(TASK_DASHBOARD_SLIDES_BUILD)
        commandLine(
            &quot;docker&quot;, &quot;run&quot;, &quot;--rm&quot;,
            &quot;-v&quot;, &quot;${project.rootDir.absolutePath}:/workspace&quot;,
            &quot;-v&quot;, &quot;${System.getProperty(&quot;user.home&quot;)}/.gradle:/root/.gradle&quot;,
            &quot;-w&quot;, &quot;/workspace&quot;,
            &quot;eclipse-temurin:17&quot;,
            &quot;./gradlew&quot;, TASK_ASCIIDOCTOR_REVEALJS
        )
        workingDir = project.rootDir
    }
    javaVersion == 17 -&amp;gt; {
        project.repositories.mavenCentral() {
            content { excludeGroup(&quot;rubygems&quot;) }
        }
        project.repositories.ivy {
            url = project.uri(&quot;https://rubygems.org/gems/&quot;)
            patternLayout { artifact(&quot;[module]-[revision].gem&quot;) }
            metadataSources { artifact() }
            content { includeGroup(&quot;rubygems&quot;) }
        }
        project.extensions.getByType&amp;lt;RevealJSExtension&amp;gt;().apply {
            version = &quot;3.1.0&quot;
            templateGitHub {
                setOrganisation(&quot;hakimel&quot;)
                setRepository(&quot;reveal.js&quot;)
                setTag(&quot;3.9.1&quot;)
            }
        }
        project.tasks.getByName&amp;lt;AsciidoctorJRevealJSTask&amp;gt;(TASK_ASCIIDOCTOR_REVEALJS) {
            setInProcess(&quot;JAVA_EXEC&quot;)
            forkOptions {
                executable(
                    project.serviceOf&amp;lt;JavaToolchainService&amp;gt;()
                        .launcherFor {
                            languageVersion.set(JavaLanguageVersion.of(17))
                            vendor.set(JvmVendorSpec.ADOPTIUM)
                        }
                        .get()
                        .executablePath
                        .asFile
                        .absolutePath
                )
            }
            // ... reste de la configuration
        }
    }
    else -&amp;gt; error(
        &quot;Docker est requis pour exécuter $TASK_ASCIIDOCTOR_REVEALJS &quot; +
        &quot;avec Java $javaVersion. Installez Docker ou utilisez Java 17.&quot;
    )
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجہ_خاتم&quot;&gt;نتیجہ خاتم&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_صارف_buildscript&quot;&gt;صارف buildscript&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;apply&amp;lt;slides.SlidesPlugin&amp;gt;()&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ سب ہے۔ پلاگ این پورے ذمہ دار ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_settings_gradle_kts&quot;&gt;settings.gradle.kts&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;pluginManagement {
    repositories {
        mavenLocal()
        gradlePluginPortal()
    }
}

plugins {
    id(&quot;org.gradle.toolchains.foojay-resolver-convention&quot;) version &quot;0.8.0&quot;
}

@Suppress(&quot;UnstableApiUsage&quot;)
dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.PREFER_PROJECT)
}

rootProject.name = &quot;slider-gradle&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_جالات_اور_حل_کی_خلاصہ&quot;&gt;جالات اور حل کی خلاصہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 25%;&quot;&gt;
&lt;col style=&quot;width: 37.5%;&quot;&gt;
&lt;col style=&quot;width: 37.5%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;مشکل&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;سبب&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;حل&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;`ruby { gems() }`Kotlin میں دستیاب نہیں&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;صرف گرووی DSL ایکسٹینشن&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;три الگ الگ مکیانزمات : Ivy ریپو + استثناء Maven +&lt;code&gt;asciidoctorGems&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Gradle aik dhoondh raha hai`.jar`ایک کی جگہ`.gem`&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;`[ext]`حل کرتا ہے میں`jar`پیش فرض&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;سخت کوڈ کرنے والا`.gem`Ivy کے پтерن + مُعَيَّن`@gem`&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;ivy { }`کمپائل نہیں ہوتا میں`repositories { }&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ریسیفر grolifant Kotlin DSL کے ساتھ متوافق نہیں&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;مستقیم کال`project.repositories.ivy { }`&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;`javaLauncher`حل نہیں&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;موجود نہیں ہونے والی خاصیت پر`AsciidoctorJRevealJSTask`&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;setInProcess(&quot;JAVA_EXEC&quot;)&lt;/code&gt;(empty)&lt;code&gt;forkOptions { executable(&amp;#8230;&amp;#8203;) }&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;`executable = &amp;#8230;&amp;#8203;`کمپائل نہیں ہوتا&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ممتلكات`val`میں`JavaForkOptions`بڑا ہاتھی&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;طریقہ`executable(Object)`جگہ پر&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;JavaToolchainService`کے ذریعے نہیں ملنا`extensions&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;یہ ایک گرائل سروس ہے، ایک ایکسٹنشن نہیں&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;project.serviceOf&amp;lt;JavaToolchainService&amp;gt;()&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;`revealjs { }`محلول نہیں کام میں&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;پروجیکٹ کی ایکسٹنشن، کام کا طریقہ نہیں&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;project.extensions.getByType&amp;lt;RevealJSExtension&amp;gt;()&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;بِلڈ جاوہ 25 کے ساتھ خراب ہو جاتا ہے&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Kotlin 2.0.x دو رقمی Java ورژنوں کو پارس نہیں کرتا&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;خودکار ڈاکر تشخیص + جاوا 17 کا فالبک&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_تحقیق_کا_طریقہ_جاویپ_سے_نامعلوم_api_پڑھنا&quot;&gt;تحقیق کا طریقہ : جاویپ سے نامعلوم API پڑھنا&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اصل&quot;&gt;اصل&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جب دستاویز غائب یا پوری نہ ہو، bytecodes سچائی کا ذریعہ ہوتے ہیں۔ &lt;code&gt;javap`یہ JDK کا معیاری آلہ ہے جو فائلز ڈیکومپائل کرتا ہے&lt;/code&gt;.class`قابل پڑھنے والے جاوا سائنچرز میں, بغیر سروس کوڈ کی ضرورت&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مرحلہ_1_گریڈل_کیش_میں_جار_کو_ڈھونڈیں&quot;&gt;مرحلہ 1: گریڈل کیش میں جار کو ڈھونڈیں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle تمام اپنی وابستگی ڈاؤنلوڈ کرتا ہے میں`~/.gradle/caches/modules-2/files-2.1/`. پہلا قدم یہ ہے کہ وہ jar جس میں کلاس جس کو معائنہ کرنا ہے موجود ہو:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;find ~/.gradle/caches -name &quot;asciidoctor-gradle-jvm-slides*.jar&quot; 2&amp;gt;/dev/null&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نتیجہ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;/home/user/.gradle/caches/modules-2/files-2.1/org.asciidoctor/
asciidoctor-gradle-jvm-slides/4.0.0-alpha.1/.../
asciidoctor-gradle-jvm-slides-4.0.0-alpha.1.jar&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مرحلہ_2_jar_کی_کلاسوں_کی_فہرست_بنانا&quot;&gt;مرحلہ 2: jar کی کلاسوں کی فہرست بنانا&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک کلاس کا تفتیش کرنے سے پہلے، یہ جان لیا جاتا ہے کہ کلاس جار میں موجود ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;jar tf asciidoctor-gradle-jvm-slides-4.0.0-alpha.1.jar | grep -i &quot;RevealJS\|revealjs&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ تمام دستیاب کلاسوں کا مظاہرہ کرتا ہے: &lt;code&gt;AsciidoctorJRevealJSTask&lt;/code&gt;, &lt;code&gt;RevealJSExtension&lt;/code&gt;, &lt;code&gt;RevealJSOptions&lt;/code&gt;, etc.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مرحلہ_3_کلاس_کا_جائزہ_لیں&quot;&gt;مرحلہ 3 : کلاس کا جائزہ لیں&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;javap -p -classpath asciidoctor-gradle-jvm-slides-4.0.0-alpha.1.jar \
org.asciidoctor.gradle.jvm.slides.AsciidoctorJRevealJSTask&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اختیار`-p`یہ تمام رکنیں، خصوصی رکنیں شامل دکھاتا ہے۔ نتیجہ فوراً کلیدی لائن دکھاتا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;public class AsciidoctorJRevealJSTask
extends org.asciidoctor.gradle.jvm.AbstractAsciidoctorTask&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مرحلہ_4_ہyerarkey_اوپر_جاؤ&quot;&gt;مرحلہ 4: ہyerarkey اوپر جاؤ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کام پھیلاتا ہے`AbstractAsciidoctorTask`. اس کا دور آنے پر اسے جانچا جاتا ہے پہلے اس کے jar کو ڈھونڈ کر :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;find ~/.gradle/caches -name &quot;asciidoctor-gradle-jvm-[0-9]*.jar&quot; 2&amp;gt;/dev/null

javap -p -classpath asciidoctor-gradle-jvm-4.0.0-alpha.1.jar \
org.asciidoctor.gradle.jvm.AbstractAsciidoctorTask | grep -i &quot;fork\|exec\|jvm\|java&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہی جگہ ہے جہاں ہم دریافت کرتے ہیں`forkOptions`, &lt;code&gt;JAVA_EXEC&lt;/code&gt;, et &lt;code&gt;javaForkOptions&lt;/code&gt; کی قسم`org.ysb33r.grolifant.api.v4.JavaForkOptions`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مرحلہ_5_غیر_معروف_انواع_کی_پیروی_کریں&quot;&gt;مرحلہ 5: غیر معروف انواع کی پیروی کریں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;`JavaForkOptions`ایک نامعلوم grolifant کلاس ہے۔ هم اس کا jar ملتے ہیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;find ~/.gradle/caches -name &quot;grolifant*.jar&quot; 2&amp;gt;/dev/null&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پھر اسے جانچا جاتا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;javap -p -classpath grolifant40-legacy-api-2.0.0-alpha.6.jar \
org.ysb33r.grolifant.api.v4.JavaForkOptions&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;وہاں مل جاتا ہے`executable(java.lang.Object)&lt;code&gt;— بلانے کا صحیح طریقہ، کے مقابل`executable = &amp;#8230;&amp;#8203;`جسے کمپائل نہیں کیا جا سکتا کیونکہ یہ ایک پراپرٹی ہے`val&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مرحلہ_6_پروجیکٹ_کے_ایسٹینشنز_جانچ_کریں&quot;&gt;مرحلہ 6: پروجیکٹ کے ایسٹینشنز جانچ کریں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کے لیے`revealjs { }`، سوال تھا : کیا یہ کام کا ایک طریقہ ہے؟ یا ایک پروگرام کی توسیع؟ تفتیش کا`AsciidoctorJRevealJSTask` کسی طریقہ دکھاتا نہیں`revealjs`. پھر ہم جائزہ لیتے ہیں`RevealJSExtension`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;javap -p -classpath asciidoctor-gradle-jvm-slides-4.0.0-alpha.1.jar \
org.asciidoctor.gradle.jvm.slides.RevealJSExtension | head -5&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;public class RevealJSExtension implements groovy.lang.GroovyObject {
public static final java.lang.String NAME;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;موجودگی کا`NAME`یہ تصدیق کرتا ہے کہ یہ پراجیکٹ پر رجسٹر کردہ ایکٹنشن ہے, منصوب کے ذریعے`project.extensions.getByType&amp;lt;RevealJSExtension&amp;gt;()`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_طریقے_کا_خلاصہ&quot;&gt;طریقے کا خلاصہ&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 25%;&quot;&gt;
&lt;col style=&quot;width: 75%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;مرحلہ&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;عمل&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;1&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;find ~/.gradle/caches -name &quot;*.jar&quot;&lt;/code&gt;— جار کا مقام معلوم کرنا&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;2&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;jar tf jar.jar | grep NomClasse&lt;/code&gt;— کلاس موجود ہے یا نہیں جانچ کریں&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;3&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;javap -p -classpath jar.jar NomCompletClasse&lt;/code&gt;— کلاس کا معائنہ کریں&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;4&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;شناسائی`extends`اور ہیرارچھی اوپر چڑھنا&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;5&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;اپنے جار میں نامعلوم انواع کی پیروی کریں&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;6&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;تلاش کرنا`NAME`pour identifier une extension de projet&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ طریقہ کسی بھی Gradle پلاگین پر قابل اطلاق ہے جس کی API دستاویز شدہ نہیں ہے او جس کا alpha ورژن اب موجودہ توثیق سے مطابقت نہیں رکھتا۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_اگلا_مرحلہ&quot;&gt;اگلا مرحلہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ buildSrc پلاگ-إن ایک الگ پروجیکٹ میں نکال دیا جائے گا جو Gradle Plugin Portal یا Maven Local پر شائع ہو جائے گا۔ مصروف کرنے والا buildscript اب اس صورت میں بن جائے گا:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;plugins { id(&quot;slides&quot;) version &quot;1.0.0&quot; }&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Et &lt;code&gt;settings.gradle.kts`اس کو صرف کمترین حد تک کم کر دیا جائے گا، کسی ارجاع کے بغیر`foojay-resolver-convention&lt;/code&gt;, JDK کی فراہمی پلاگین خود خود منظم کی جاتی ہے یا اس کو prerequisite کے طور پر document کیا گیا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table des matières&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
