&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_معماری_رؤیت&quot;&gt;معماری رؤیت&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مبدأ_توجيهي&quot;&gt;مبدأ توجيهي&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;معمار、&lt;strong&gt;معاملات کی جدائی&lt;/strong&gt; کے اصول پر مبنی ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;محتوى&lt;/strong&gt; : ملفات AsciiDoc المنظمة مع بيانات تعريفية غنية&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;معرفی&lt;/strong&gt; : ٹیمپلیٹس Thymeleaf دوبارہ استعمال ہونے والی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ڈیٹا&lt;/strong&gt; : مودل خودکار طور پر JBake سے AsciiDoc کے صفات سے اخذ کیا گیا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Style&lt;/strong&gt; : Bootstrap 5 کے لیے ویجوال ہم آہنگی&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_استراتژیک_انتخاب_asciidoc_پورٹفولیو_کیلئے&quot;&gt;استراتژیک انتخاب: AsciiDoc پورٹفولیو کیلئے&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;.کیوں AsciiDoc ?&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 66.6667%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;معیار&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;فائدہ&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ہم آہنگی&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;بلاگ مضامین جیسے فارمیٹ&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;میتا ڈیٹا&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ساختگی اور قابل توسیع صفات (&lt;code&gt;project-*&lt;/code&gt;)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;رکھاوٹ کی قابلیت&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ساده متنی ترسیل، گِٹ ورژنبل&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;لچک&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;شامل ہو سکتا ہے غنى materiال (ٹبیل، کوڈ، تصاویر)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ٹیمپلتنگ&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;JBake خودکار طور پر Thymeleaf کے لیے صفات نکالتا ہے&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ڈیٹا_ماڈل&quot;&gt;ڈیٹا ماڈل&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہر پورٹوفلیو پروجیکٹ ایک AsciiDoc دستاویز ہے جس کے ساتھ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ہڈر میٹا ڈیٹا&lt;/strong&gt; : منظوم معلومات (کلائن، مدت، ٹیکنالوجیز، وغیرہ)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;دستاویز کا جسم&lt;/strong&gt; : روایتی تفصیل، چالن جیز، حل، نتائج&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;اخصائی خصوصیات&lt;/strong&gt; : پیش لگایا`project-*`خودکار نکال کے لئے&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam handwritten false

class ProjetAsciiDoc {
  +titre: String
  +jbake-type: &quot;پروجیکٹ&quot;
  +jbake-status: published|draft
  +jbake-date: Date
  +jbake-tags: List&amp;lt;String&amp;gt;
  --
  +project-category: String
  +project-client: String
  +project-duration: String
  +project-role: String
  +project-thumbnail: String
  +project-gallery: List&amp;lt;String&amp;gt;
  +project-tech-stack: String
  +project-highlights: List&amp;lt;String&amp;gt;
  +project-demo-url: String
  +project-github-url: String
  --
  +body: HTML (converti)
}

class JBakeEngine {
  +parse(asciidoc)
  +extractMetadata()
  +convertToHTML()
}

class ThymeleafTemplate {
  +portfolio.html
  +project.html
  +partials/project-card.html
}

class PortfolioPage {
  +published_projects: List
  +filtres: categories
}

ProjetAsciiDoc --&amp;gt; JBakeEngine : parse
JBakeEngine --&amp;gt; ThymeleafTemplate : fournit données
ThymeleafTemplate --&amp;gt; PortfolioPage : génère
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_استعمال_کے_مفصل_سيناريوهات&quot;&gt;استعمال کے مفصل سيناريوهات&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc1_پورٹ_فولیو_میں_ایک_عنصر_شامل_کریں&quot;&gt;UC1: پورٹ فولیو میں ایک عنصر شامل کریں&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_معیاری_فلکس&quot;&gt;معیاری فلکس&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;محرّر
متن&quot; as editor
participant &quot;فائل
AsciiDoc&quot; as file
participant &quot;JBake
انجن&quot; as jbake
participant &quot;سائٹ
استاتیک&quot; as site

dev -&amp;gt; editor : Créer nouveau fichier
activate editor
editor -&amp;gt; file : portfolio/nouveau-projet.adoc
activate file

dev -&amp;gt; editor : Rédiger en-tête avec métadonnées\n(titre, type=project, status=published,\nattributs project-*)
dev -&amp;gt; editor : Rédiger contenu narratif\n(contexte, défis, solutions)
dev -&amp;gt; editor : Ajouter images dans assets/img/portfolio/

editor -&amp;gt; file : Sauvegarder
deactivate editor

dev -&amp;gt; jbake : Lancer build (jbake -b)
activate jbake
jbake -&amp;gt; file : Lire et parser
jbake -&amp;gt; jbake : Extraire métadonnées
jbake -&amp;gt; jbake : Convertir AsciiDoc → HTML
jbake -&amp;gt; jbake : Appliquer template project.html
jbake -&amp;gt; jbake : Ajouter à la liste portfolio.html
jbake -&amp;gt; site : Générer pages statiques
deactivate jbake

dev -&amp;gt; site : Vérifier résultat
activate site
site --&amp;gt; dev : Afficher projet
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_بنانے_کے_لیے_فائل_کا_ٹیمپلیٹ&quot;&gt;بنانے کے لیے فائل کا ٹیمپلیٹ&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ڈویلپر بناتا ہے`content/portfolio/nom-projet.adoc`ایک معیاری ڈھانچے کے ساتھ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;سرعنوان میں تمام ضروری خصوصیات&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;معياری سیکشن (سیاق، چیلنجز، حلول، نتائج)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;تصاویر کی متفق نامگذاری&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_تصدیق_کے_نقاط&quot;&gt;تصدیق کے نقاط&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;ضروری خصوصیات موجود ہیں (&lt;code&gt;jbake-type&lt;/code&gt;, &lt;code&gt;jbake-status&lt;/code&gt;, &lt;code&gt;project-thumbnail&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;حوالہ شدہ تصاویر میں موجود ہیں`assets/img/portfolio/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;جبیک کا بیلڈ بغیر کسی خطا کے کامیاب ہوتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;پروجیکٹ پورٹ فولیو پیج پر ظاہر ہوتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;پروجیکٹ کی انفرادی صفحہ صحیح طور پر دکھائی دے رہی ہے&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc2_پورٹفولیو_سے_ایک_آئٹم_حذف_کریں&quot;&gt;UC2 : پورٹفولیو سے ایک آئٹم حذف کریں&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_معیاری_فلکس_2&quot;&gt;معیاری فلکس&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;نظام
فائِلز&quot; as fs
participant &quot;JBake
انجن&quot; as jbake
participant &quot;سائٹ\nستٹک&quot; as site
database &quot;كيش
JBake&quot; as cache

dev -&amp;gt; fs : Supprimer portfolio/projet-ancien.adoc
activate fs
fs --&amp;gt; dev : Fichier supprimé
deactivate fs

dev -&amp;gt; fs : (Optionnel) Supprimer images associées\nassets/img/portfolio/projet-ancien-*
activate fs
fs --&amp;gt; dev : Images supprimées
deactivate fs

dev -&amp;gt; cache : Nettoyer cache JBake
activate cache
cache --&amp;gt; dev : Cache vidé
deactivate cache

dev -&amp;gt; jbake : Rebuild complet (jbake -b)
activate jbake
jbake -&amp;gt; jbake : Scanner content/portfolio/
jbake -&amp;gt; jbake : Projet absent → non généré
jbake -&amp;gt; jbake : Régénérer portfolio.html\n(sans le projet supprimé)
jbake -&amp;gt; site : Déployer nouveau build
deactivate jbake

dev -&amp;gt; site : Vérifier
activate site
site --&amp;gt; dev : Projet absent de la liste
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_اختیاری_حکمت_عملی_آرشیو&quot;&gt;اختیاری حکمت عملی: آرشیو&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;دائمی طور پر حذف کرنے کی بجائے، فولدَر بنانے کی امکان`content/portfolio/archive/`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;فائل کو حذف کرنے کے بجائے اسے منتقل کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آسانی سےبحال کرنے کی اجازت دیتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;گٹ کا تاريخ کو زیادہ واضح رکھیں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_وسائل_کی_صفائی&quot;&gt;وسائل کی صفائی&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;بیچھی گئی تصاویر کا جائزہ لیں میں`assets/img/portfolio/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;حذف کریں وہ تصاویر جو دیگر منصوبوں سے ارجاع نہیں کی گئی ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;JBake کے کیش کو صاف کریں تاکہ بhootیا ارجحانات سے بچا جا سکے&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc3_غیر_شائع_کردہ_ڈرافٹ_بنائیں&quot;&gt;UC3 : غیر شائع کردہ (ڈرافٹ) بنائیں&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_نومینل_فلوکس&quot;&gt;نومینل فلوکس&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;فائل
AsciiDoc&quot; as file
participant &quot;JBake
انجن&quot; as jbake
participant &quot;سائٹ
ثابت&quot; as site

dev -&amp;gt; file : Ouvrir portfolio/projet.adoc
activate file

dev -&amp;gt; file : Modifier attribut\n:jbake-status: published\n↓\n:jbake-status: draft

file --&amp;gt; dev : Sauvegardé
deactivate file

dev -&amp;gt; jbake : Rebuild (jbake -b)
activate jbake
jbake -&amp;gt; file : Parser le fichier
jbake -&amp;gt; jbake : Détecter status=draft
jbake -&amp;gt; jbake : Exclure de published_projects
jbake -&amp;gt; jbake : Ne pas créer page publique
note right
  Le projet existe toujours
  mais n&#39;est pas publié
end note
jbake -&amp;gt; site : Générer site (sans ce projet)
deactivate jbake

dev -&amp;gt; site : Vérifier portfolio
activate site
site --&amp;gt; dev : Projet absent de la liste publique
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_ممکن_حالات&quot;&gt;ممکن حالات&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

[*] --&amp;gt; Draft : Création initiale
Draft --&amp;gt; Published : Validation et publication
Published --&amp;gt; Draft : Retrait temporaire
Draft --&amp;gt; Archived : Projet abandonné
Published --&amp;gt; Archived : Projet obsolète
Archived --&amp;gt; [*] : Suppression définitive
Published --&amp;gt; Published : Mises à jour

note right of Draft
  :jbake-status: draft
  Non visible publiquement
  Utile pour projets en cours
end note

note right of Published
  :jbake-status: published
  Visible sur le portfolio
  Indexé par JBake
end note

note right of Archived
  Déplacé dans archive/
  ou jbake-status: archived
  Non publié mais conservé
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_عام_استعمال_کے_حالات&quot;&gt;عام استعمال کے حالات&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;تیار ہونے والی پروجیکٹ&lt;/strong&gt; : ڈراфт بنائیں، جب تیار ہو تواشاعت کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پروژہ موقت خفیہ&lt;/strong&gt; : ڈرافٹ ہو جانا کلائنٹ کے معاہدے کے دوران&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;بڑا اپ ڈیٹ&lt;/strong&gt; : ڈرافٹ میں جانا، ترمیم کرنا، دوبارہ לפרش کرنا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;A/B testing&lt;/strong&gt; : ڈراфт میں نкал کریں، ٹیسٹ کریں، بہترین ویršن اشاعت کریں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ٹیمپلنٹنگ_کی_معماری&quot;&gt;ٹیمپلنٹنگ کی معماری&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_دوبارہ_استعمال_ہونے_والے_ٹیمپلیٹ_کی_حکمت_عملی&quot;&gt;دوبارہ استعمال ہونے والے ٹیمپلیٹ کی حکمت عملی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;ٹیمپلیٹس Thymeleaf&quot; {
  component [index.html] as index
  component [portfolio.html] as portfolio
  component [project.html] as project

  package &quot;حصص&quot; {
    component [header.html] as header
    component [footer.html] as footer
    component [project-card.html] as card
    component [tech-badge.html] as badge
    component [gallery.html] as gallery
  }
}

package &quot;ڈیٹا JBake&quot; {
  database &quot;منتشر کردہ پروجيكتس&quot; as data
  database &quot;مضمون (پروجیکٹ)&quot; as content
}

index --&amp;gt; header
index --&amp;gt; footer

portfolio --&amp;gt; header
portfolio --&amp;gt; footer
portfolio --&amp;gt; card
data --&amp;gt; portfolio : itération

project --&amp;gt; header
project --&amp;gt; footer
project --&amp;gt; badge
project --&amp;gt; gallery
content --&amp;gt; project : projet individuel

note right of card
  Fragment réutilisable
  pour afficher une carte
  de projet avec :
  - thumbnail
  - titre
  - tags
  - highlights
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ڈیٹا_نکالنے_کا_نمونہ&quot;&gt;ڈیٹا نکالنے کا نمونہ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBake خودکار طور پر AsciiDoc کے خصوصیات کو Thymeleaf میں رسائی کے قابل خصوصیات میں بدل دیتا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;دستاویز AsciiDoc&quot; {
  (&quot;:project-client: ایکمی کارپوریشن&quot;) as attr1
  (&quot;:project-duration: 6 ماہ&quot;) as attr2
  (&quot;:پروجیکٹ ٹیگز: java, react&quot;) as attr3
}

rectangle &quot;مودل JBake&quot; {
  (content[&#39;project-client&#39;]) as prop1
  (content[&#39;project-duration&#39;]) as prop2
  (content.tags) as prop3
}

rectangle &quot;ٹیمپلیٹ Thymeleaf&quot; {
  (th:text=&quot;${project[&#39;project-client&#39;]}&quot;) as tmpl1
  (th:text=&quot;${project[&#39;project-duration&#39;]}&quot;) as tmpl2
  (th:each=&quot;تیگ : ${project.tags}&quot;) as tmpl3
}

attr1 --&amp;gt; prop1 : parsing
attr2 --&amp;gt; prop2 : parsing
attr3 --&amp;gt; prop3 : parsing

prop1 --&amp;gt; tmpl1 : binding
prop2 --&amp;gt; tmpl2 : binding
prop3 --&amp;gt; tmpl3 : binding
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_نامگذاری_کے_اصول&quot;&gt;نامگذاری کے اصول&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پروجیکٹ کی خصوصیات&lt;/strong&gt; : پریفکس`project-*` (ex: &lt;code&gt;project-client&lt;/code&gt;, &lt;code&gt;project-tech-stack&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;فائلز&lt;/strong&gt; : kebab-case (ex:`ecommerce-platform.adoc`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Images&lt;/strong&gt; : منصوبہ کے نام کا پیشوند (مثلاً:`ecommerce-platform-thumb.jpg`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Templates&lt;/strong&gt; : عملی نام (مثال:`project-card.html`, &lt;code&gt;tech-badge.html&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_اشاعت_کا_وورک_فلو&quot;&gt;اشاعت کا وورک فلو&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_پائپ_لائن_ڈویلپمنٹ&quot;&gt;پائپ لائن ڈویلپمنٹ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam handwritten false

class ProjetAsciiDoc {
  +titre: String
  +jbake-type: &quot;پروجیکٹ&quot;
  +jbake-status: published|draft
  +jbake-date: Date
  +jbake-tags: List&amp;lt;String&amp;gt;
  __
  +project-category: String
  +project-client: String
  +project-duration: String
  +project-role: String
  +project-thumbnail: String
  +project-gallery: List&amp;lt;String&amp;gt;
  +project-tech-stack: String
  +project-highlights: List&amp;lt;String&amp;gt;
  +project-demo-url: String
  +project-github-url: String
  __
  +body: HTML (converti)
}

class JBakeEngine {
  +parse(asciidoc)
  +extractMetadata()
  +convertToHTML()
}

class ThymeleafTemplate {
  +portfolio.html
  +project.html
  +partials/project-card.html
}

class PortfolioPage {
  +published_projects: List
  +filtres: categories
}

ProjetAsciiDoc --&amp;gt; JBakeEngine : parse
JBakeEngine --&amp;gt; ThymeleafTemplate : fournit données
ThymeleafTemplate --&amp;gt; PortfolioPage : génère
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ماحولیات&quot;&gt;ماحولیات&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 20%;&quot;&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;ماحول&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;استعمال&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;مقبول وضع&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;مقامی&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;ترقی اور پیشنمائی&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;مسودہ، شائع&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;معراضی&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;پری پروڈکشن کی تصدیق&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;صرف شائع کیا گیا&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;پیداواری&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;عوامی سائٹ&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;صرف شائع&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_قابل_توسیع&quot;&gt;قابل توسیع&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_نئے_خصوصیات_کا_شامل&quot;&gt;نئے خصوصیات کا شامل&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ڈیٹا ماڈل کو بہتر بنانے کے لیے، صرف نئے پیشforegone خصوصیات شامل کریں`project-*`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-awards&lt;/code&gt;: ایوارڈز اور تحسینات&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-testimonial&lt;/code&gt;: کلائنٹ کی اقتباس&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-team-size&lt;/code&gt;: ٹیم کا سائز&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;`project-budget-range`بجٹ کی حد&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہویں خصوصیات خودکار طور پر ٹیمپلیٹس میں دستیاب ہو جاتی ہیں JBake انجن میں کسی تبدیلی کے بغیر۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ترقیاتی_تصنیف&quot;&gt;ترقیاتی تصنیف&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

object Projet {
  project-category = &quot;web&quot;
  project-subcategory = &quot;انلائن تجارت&quot;
  project-industry = &quot;خرد&quot;
  project-complexity = &quot;اونچا&quot;
}

object Taxonomie {
  categories : [web, mobile, data, devops]
  subcategories : Map&amp;lt;category, List&amp;gt;
  industries : [retail, finance, healthcare, ...]
  complexities : [low, medium, high]
}

Projet --&amp;gt; Taxonomie : classifié selon

note right of Taxonomie
  Permet filtrage multi-critères
  dans le template portfolio.html
  via JavaScript ou côté serveur
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_بہترین_طریقے&quot;&gt;بہترین طریقے&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فائلوں_کی_تنظیم&quot;&gt;فائلوں کی تنظیم&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ایک فائل = ایک پروجيکت&lt;/strong&gt; : کئی پروجيكتس کو مخلوط کرنے سے بچنا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;مخصوص فولڈر میں تصاویر&lt;/strong&gt; :`assets/img/portfolio/nom-projet/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;منسجم نامenклатура&lt;/strong&gt; : تحقیق اور مرامتیں کو آسان بناتی ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Versioning Git&lt;/strong&gt; : تبدیلیوں کا مکمل تعقیب&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_محتوى_کی_منیجمنٹ&quot;&gt;محتوى کی منیجمنٹ&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ڈیافالٹ ڈرافت کی حیثیت&lt;/strong&gt; : صرف جب Tayyār ho تو shāyir karein&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;منتشر ہونے سے قبل کا جائزہ&lt;/strong&gt; : جائزہ معیار اور رازداری&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;مکمل متا ڈیٹا&lt;/strong&gt; : تمام ذاتی فیلڈز پر بھریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;امیر روایت پر مبنی مواد&lt;/strong&gt; : میتا ڈیٹا تک خود کو محدود نہ کریں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_عمل&quot;&gt;عمل&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;تصاویر کو بہتر بنانا&lt;/strong&gt; : کمپریشن commit سے پہلے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پاجینیشن اگر ضروری ہو&lt;/strong&gt; : اگر &amp;gt;20 پروجیکٹ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;لاizi لودنگ&lt;/strong&gt; : گیلریوں کی تصاویر ضرورت کے مطابق لوڈ کی جاتی ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;براؤزر کیش&lt;/strong&gt; : ایسٹس کے لیے مناسب ہیڈرز&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجہ&quot;&gt;نتیجہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ معماریت اجازت دیتی ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;استعمال کی سادگی&lt;/strong&gt; : پروجیکٹ شامل کریں = متنی فائل بنائیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;لچک&lt;/strong&gt; : نئے خصوصیات کے ذریعے قابل تمدد&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;قابل نگہداری&lt;/strong&gt; : محتوا اور پیشگی کی جدائی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پیروی&lt;/strong&gt; : ورژننگ Git کامل&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;khud-kaari&lt;/strong&gt; : build aur tanseeb mustamer mumkin&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;AsciiDoc کی انتخاب، باقی ویب سائٹ کے ساتھ ہم آہمی (مطابقت) برقرار رکھتی ہے، اور پیشہ ورانہ پورٹ فولیو کے لئے ضروری میٹی ڈیٹا کی زادتی بھی فراہم کرتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;پڑھنے کا وقت : 12 minutes&lt;/div&gt;
&lt;p&gt;Supabase ki sādagī aur Spring Boot ki tāqat ke darmiyan chunne ke bajāye, kyun nahin donon ko milana? Janiye ek hibrid ārki ṭekchar jo har teknologi ka sab se behter faiyda uthati hai&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;ٹک&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_معماریت_مودرن_کا_جھوٹا_ڈیلیما&quot;&gt;معماریت مودرن کا جھوٹا ڈیلیما&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کسی مدرن ایپلیکیشن کے static frontend کے ساتھ بناتے وقت، ہم اکثر ایک بائنری انتخاب کے سامنے آتے ہیں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Backend-as-a-Service حل پر سارا زور لگائیں&lt;/strong&gt;(Supabase, Firebase) - سادہ لیکن محدود&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;مکمل backend بنائیں&lt;/strong&gt;(Spring Boot, Node.js) - طاقتور لیکن پیچیدہ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ انتخاب یک جھوٹلا معضل ہے۔ ہائبرڈ آڑکی ٹیکچر ایک Third way پیش کرتی ہے: &lt;strong&gt;ہر ٹیکنالوجی کو وہ جگہ استعمال کرنے پر جہاں وہ سب سے بہتر کام کرتی ہے&lt;/strong&gt;۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_عمارتی_نظر&quot;&gt;عمارتی نظر&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_روایتی_معمارتی_ایک_جوڑ&quot;&gt;روایتی معمارتی : ایک جوڑ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;روایتی معماری&quot; {
  actor Utilisateur as user
  component &quot;فرونتینڈ&quot; as frontend #LightBlue
  component &quot;بیکینڈ مونولیٹک&quot; as backend #LightCoral {
    [Authentification]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [APIs Tierces]
  }
  database &quot;ڈیٹا بیس&quot; as db #LightGray

  user --&amp;gt; frontend
  frontend --&amp;gt; backend : Toutes les requêtes
  backend --&amp;gt; db
}

note right of backend
  Tout passe par le backend
  même les opérations simples

  ⚠️ Point de congestion unique
  ⚠️ Complexité dès le départ
  ⚠️ Couplage fort
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اس رویے میں، سب سے سادہ عمل (مثلاً مضمون پڑھنا، تبصرہ بنانا) بھی آپ کے بیکینڈ سے گزرنا چاہیے۔ آپ پہلے دن سے پیچیدگی کی قیمت ادا کرتے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_baas_معماری_تمام_نمائندہ&quot;&gt;BaaS معماری : تمام نمائندہ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;معماری BaaS پاک&quot; {
  actor Utilisateur as user
  component &quot;فرینڈ-ایینڈ&quot; as frontend #LightBlue
  cloud &quot;سوپربیس / فایربیس&quot; as baas #LightGreen {
    [Auth]
    [Database]
    [Storage]
    [Edge Functions]
  }

  user --&amp;gt; frontend
  frontend --&amp;gt; baas : Toutes les opérations
}

note right of baas
  Développement rapide
  Pas de serveur à gérer

  ⚠️ Limité pour logique complexe
  ⚠️ Vendor lock-in
  ⚠️ Edge Functions contraintes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بالعکس، ایک BaaS میں تمام چیزوں کو deputی کرنا ابتداء میں پر کشش کے ساتھ ہوتا ہے لیکن جب کاروباری منطق پیچیدہ ہوتا ہے، جلد ہی اس کی حدیں ظاہر ہو جاتی ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ہائبرڈ_آركٹیکچر_ذمے_داریوں_کا_انحصار&quot;&gt;ہائبرڈ آركٹیکچر: ذمے داریوں کا انحصار&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

actor Utilisateur as user #LightBlue

package &quot;فرنتیند طبقہ&quot; {
  component &quot;استاتيک سائٹ JBake&quot; as frontend #SkyBlue
}

package &quot;ساده طبقہ (Supabase)&quot; #LightGreen {
  component &quot;تصدیق&quot; as auth
  component &quot;CRUD بنیادی&quot; as crud
  component &quot;فائل سٹوریج&quot; as storage
  component &quot;حقیقی وقت&quot; as realtime
}

package &quot;کاروباری طبقہ (Spring Boot)&quot; #Coral {
  component &quot;پیچیدہ منطق&quot; as logic
  component &quot;آرکیسٹریشن&quot; as orchestration
  component &quot;شڈول کردہ نوکریاں&quot; as jobs
  component &quot;انضمام&quot; as integrations
}

database &quot;PostgreSQL مشترک&quot; as db #LightGray

user --&amp;gt; frontend

frontend --&amp;gt; auth : OAuth2, JWT
frontend --&amp;gt; crud : Articles, Profils
frontend --&amp;gt; storage : Images, Fichiers
frontend --&amp;gt; realtime : Notifications

frontend --&amp;gt; logic : Calculs, Rapports
frontend --&amp;gt; orchestration : Workflows
logic --&amp;gt; integrations : Stripe, APIs
orchestration --&amp;gt; db
jobs --&amp;gt; db

crud --&amp;gt; db
auth --&amp;gt; db

note bottom of db
  **Une seule source de vérité**
  Partagée entre Supabase et Spring Boot
end note

note right of auth
  **Gratuit jusqu&#39;à 50k users**
  Configuration en quelques clics
  OAuth2 multi-providers
end note

note right of logic
  **Activé seulement si nécessaire**
  Kotlin + Coroutines
  Transactions complexes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہائبرڈ آرکیٹیکچر واضح طور پر عمل کی پیچیدگی اور فطرت کے مطابق ذمہ داریہیں الگ کر دیتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ڈیزائن_کے_اصول&quot;&gt;ڈیزائن کے اصول&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اصول_1_سادہ_سے_شروع_کریں_ہوشیاری_سے_ترقی_کریں&quot;&gt;اصول 1: سادہ سے شروع کریں، ہوشیاری سے ترقی کریں&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;**مرحلہ 1 : MVP**&quot; #LightGreen {
  component &quot;JBake + Supabase&quot; as mvp
  note right
    ✓ Développement en jours
    ✓ Coût : 0€
    ✓ Validation concept
  end note
}

rectangle &quot;**مرحلہ 2 : ترقی**&quot; #LightYellow {
  component &quot;JBake + Supabase\n+ Spring Boot (اختیاری)&quot; as growth
  note right
    ✓ Logique métier émerge
    ✓ Premiers jobs planifiés
    ✓ Intégrations tierces
  end note
}

rectangle &quot;**مرحلہ 3 : مقیاس**&quot; #LightCoral {
  component &quot;مکمل معماری&quot; as scale
  note right
    ✓ Orchestration complexe
    ✓ Performances optimisées
    ✓ Cache distribué
  end note
}

mvp -down-&amp;gt; growth : Quand la complexité\nle justifie
growth -down-&amp;gt; scale : Optimisation\ncontinue
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot مت بنائیں اگر آپ کو اس کی ضرورت نہیں ہے۔&lt;/strong&gt;Supabase کے ساتھ شروع کریں، جب پیچیدگی جائز ٹھہرے تو Spring Boot شامل کریں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اصول_2_عمل_کی_فطرت_پر_جدائی&quot;&gt;اصول 2 : عمل کی فطرت پر جدائی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Opérations\nApplicatives

left side

** Opérations Simples\n(Supabase)
***_ CRUD Standard
****_ Lecture
****_ Création
****_ Mise à jour
****_ Suppression
***_ Authentification
****_ Login/Logout
****_ OAuth2
****_ Gestion session
***_ Stockage
****_ Upload fichiers
****_ CDN automatique
***_ Temps Réel
****_ WebSocket
****_ Notifications

right side

** Opérations Complexes\n(Spring Boot)
***_ Logique Métier
****_ Calculs complexes
****_ Règles métier
****_ Validations avancées
***_ Orchestration
****_ Multi-services
****_ Transactions distribuées
****_ Saga patterns
***_ Tâches Planifiées
****_ Rapports périodiques
****_ Synchronisations
****_ Nettoyages
***_ Intégrations
****_ Paiements (Stripe)
****_ APIs tierces
****_ Services ML/AI

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_أصل_3_ایک_سچ_کا_منبع&quot;&gt;أصل 3 : ایک سچ کا منبع&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

database &quot;PostgreSQL&quot; as db #LightGray {
  package &quot;سکیما: auth (Supabase)&quot; #LightGreen {
    [users]
    [sessions]
    [identities]
  }

  package &quot;اسکیما: عام (شریک کردہ)&quot; #SkyBlue {
    [articles]
    [comments]
    [profiles]
  }

  package &quot;سکیما : کاروباری (Spring Boot)&quot; #Coral {
    [orders]
    [payments]
    [reports]
  }
}

component &quot;Supabase&quot; as supabase #LightGreen
component &quot;سپرنگ بٹ&quot; as spring #Coral

supabase -down-&amp;gt; users : Gère
supabase -down-&amp;gt; sessions : Gère
supabase -down-&amp;gt; articles : Accède
supabase -down-&amp;gt; comments : Accède
supabase -down-&amp;gt; profiles : Accède

spring -down-&amp;gt; articles : Accède
spring -down-&amp;gt; profiles : Accède
spring -down-&amp;gt; orders : Gère
spring -down-&amp;gt; payments : Gère
spring -down-&amp;gt; reports : Gère

note right of db
  **Avantages :**
  • Pas de synchronisation complexe
  • JOINs possibles entre tables
  • Cohérence garantie
  • Migrations unifiées
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک ہی PostgreSQL انسیٹنس شیئر کرتے ہوئے، Supabase اور Spring Boot ایک ہی ڈیٹا پر کام کرتے ہیں بina پیچیدہ ہم آہنگی کے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_فلوائز_کی_تنظیم&quot;&gt;فلوائز کی تنظیم&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فلکس_1_مرکزی_تصدیق&quot;&gt;فلکس 1 : مرکزی تصدیق&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;صارف&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Supabase Auth&quot; as auth
participant &quot;سپرینگ بوٹ&quot; as spring
database &quot;PostgreSQL&quot; as db

== Authentification ==
user -&amp;gt; jbake : Clique &quot;لاگ ان&quot;
jbake -&amp;gt; auth : Redirect OAuth2 (Google/GitHub)
auth -&amp;gt; user : Consent screen
user -&amp;gt; auth : Autorise
auth -&amp;gt; auth : Génère JWT
auth -&amp;gt; jbake : Retourne JWT + Refresh Token
jbake -&amp;gt; jbake : Stocke tokens (sessionStorage)

== Accès aux Ressources ==
group Opération Simple (CRUD)
  user -&amp;gt; jbake : Crée un article
  jbake -&amp;gt; db : POST avec JWT
  note right: Supabase Row Level Security\nvérifie le JWT automatiquement
  db -&amp;gt; jbake : Article créé
end

group Opération Complexe (Métier)
  user -&amp;gt; jbake : Génère un rapport
  jbake -&amp;gt; spring : POST /api/reports\navec JWT
  spring -&amp;gt; spring : Valide JWT Supabase
  spring -&amp;gt; spring : Extrait claims (user_id, roles)
  spring -&amp;gt; db : Requêtes complexes
  spring -&amp;gt; jbake : Rapport généré
end

note over auth, spring
  **Le JWT est universel**
  Valide par Supabase ET Spring Boot
  Pas de double authentification
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اہم نقطہ&lt;/strong&gt;: ایک ہی تصدیق کا عمل، ایک ہی JWT، ہر جگہ استعمال ہونے کے قابل۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فلو_2_پیچیدہ_کاروباری_پروسیس_کی_نظامبندی&quot;&gt;فلو 2: پیچیدہ کاروباری پروسیس کی نظامبندی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;کلائنٹ&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Spring Boot&quot; as spring
participant &quot;Supabase ڈی بی&quot; as supadb
participant &quot;Stripe API&quot; as stripe
participant &quot;انٹوری سروس&quot; as inventory
participant &quot;ایمیل سروس&quot; as email
database &quot;پوستگرس‌SQL&quot; as db

user -&amp;gt; jbake : Passe commande
jbake -&amp;gt; spring : POST /api/orders/create

== Orchestration Spring Boot ==
spring -&amp;gt; db : BEGIN TRANSACTION

par Vérifications Parallèles
  spring -&amp;gt; inventory : Vérifier stock
  inventory -&amp;gt; spring : Stock OK
else
  spring -&amp;gt; db : Vérifier profil client
  db -&amp;gt; spring : Client vérifié
end

spring -&amp;gt; stripe : Créer Payment Intent
stripe -&amp;gt; spring : Intent créé (ID: pi_xxx)

spring -&amp;gt; db : Créer Order (status: PENDING)
db -&amp;gt; spring : Order créé

spring -&amp;gt; stripe : Confirmer paiement
stripe -&amp;gt; spring : Paiement confirmé

spring -&amp;gt; db : Update Order (status: PAID)
spring -&amp;gt; inventory : Décrémenter stock
spring -&amp;gt; db : COMMIT TRANSACTION

par Notifications Asynchrones
  spring -&amp;gt; email : Email confirmation
else
  spring -&amp;gt; supadb : Insert notification
  note right: Notification temps réel\nvia Supabase Realtime
end

spring -&amp;gt; jbake : Order confirmé
jbake -&amp;gt; user : Affiche confirmation

note over spring
  **Responsabilités Spring Boot :**
  • Transaction ACID
  • Orchestration multi-services
  • Rollback automatique si erreur
  • Gestion des cas limites
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot کیا لاتا ہے&lt;/strong&gt;معتبر آرکاسٹریشن مختلف پیچیدہ پروسیس جو متعدد سسٹمز کو شامل کرتا ہے، ٹرانزیکشن کی ضمانت کے ساتھ&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_flux_3_منصوبہ_شدہ_کام_اور_ہم_آہنگی&quot;&gt;Flux 3: منصوبہ شدہ کام اور ہم آہنگی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

participant &quot;شڈولر
(سپرنگ بوٹ)&quot; as scheduler
participant &quot;رپورٹ سروس&quot; as report
participant &quot;PostgreSQL&quot; as db
participant &quot;باہری API&quot; as api
participant &quot;ای میل سروس&quot; as email
participant &quot;Supabase ذخیرہ&quot; as storage

== Job Quotidien : 2h00 ==
activate scheduler
scheduler -&amp;gt; report : Déclenche génération rapport

activate report
report -&amp;gt; db : Récupère données\ndes dernières 24h
db -&amp;gt; report : Dataset

report -&amp;gt; report : Calculs &amp;amp; Agrégations
report -&amp;gt; report : Génération PDF

report -&amp;gt; storage : Upload PDF
storage -&amp;gt; report : URL publique

report -&amp;gt; email : Envoie aux admins\navec lien PDF
deactivate report

== Job Hebdomadaire : Dimanche 3h00 ==
scheduler -&amp;gt; report : Synchronisation externe

activate report
report -&amp;gt; api : Fetch données externes
api -&amp;gt; report : Nouvelles données

report -&amp;gt; db : Mise à jour tables
report -&amp;gt; db : Nettoyage données obsolètes
deactivate report

== Job Mensuel : 1er du mois ==
scheduler -&amp;gt; report : Facturation

activate report
report -&amp;gt; db : Liste clients actifs
report -&amp;gt; report : Calcul montants
report -&amp;gt; api : Génération factures (Stripe)
report -&amp;gt; email : Envoi factures
deactivate report

deactivate scheduler

note right of scheduler
  **Impossible avec Supabase seul**
  Edge Functions non adaptées
  pour jobs longs et récurrents
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot کیا لاتا ہے&lt;/strong&gt;: معتبر مندرجہ ذیل کام، حالت کے انتظام کے ساتھ، خودکار ریٹری، اور ضمانتی تنفيذ۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_فیصلے_کی_میٹرکس&quot;&gt;فیصلے کی میٹرکس&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_supabase_kab_use_karna&quot;&gt;Supabase kab use karna?&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité à implémenter;

if (CRUD simple ?) then (oui)
  :✅ **Supabase**;
  stop
else (non)
  if (Authentification ?) then (oui)
    :✅ **Supabase Auth**;
    stop
  else (non)
    if (Upload fichiers ?) then (oui)
      :✅ **Supabase Storage**;
      stop
    else (non)
      if (Temps réel ?) then (oui)
        :✅ **Supabase Realtime**;
        stop
      else (non)
        if (Row Level Security\nsuffisante ?) then (oui)
          :✅ **Supabase + Policies**;
          stop
        else (non)
          :⚠️ **Considérer Spring Boot**;
          #Coral:Passer à l&#39;arbre\nde décision Spring Boot;
          stop
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_spring_boot_کو_کب_استعمال_کرنا_چاہیے&quot;&gt;Spring Boot کو کب استعمال کرنا چاہیے؟&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité complexe;

if (Orchestration\nmulti-services ?) then (oui)
  :✅ **Spring Boot**;
  stop
else (non)
  if (Transaction ACID\ncritique ?) then (oui)
    :✅ **Spring Boot**;
    stop
  else (non)
    if (Job planifié ?) then (oui)
      :✅ **Spring Boot Scheduler**;
      stop
    else (non)
      if (Intégration API\ntierce complexe ?) then (oui)
        :✅ **Spring Boot**;
        stop
      else (non)
        if (Calculs lourds\n&amp;gt; 10 secondes ?) then (oui)
          :✅ **Spring Boot**;
          stop
        else (non)
          if (Cache distribué\nnécessaire ?) then (oui)
            :✅ **Spring Boot + Redis**;
            stop
          else (non)
            :⚠️ **Probablement Supabase**;
            #LightGreen:Revenir à l&#39;arbre\nde décision Supabase;
            stop
          endif
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_پروجیکٹ_کے_قسم_کے_مطابق_معماری_کے_نمونے&quot;&gt;پروجیکٹ کے قسم کے مطابق معماری کے نمونے&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_بلاگ_پورٹ_فولیو&quot;&gt;بلاگ / پورٹ فولیو&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;شخصی بلاگ - 95% Supabase&quot; {
  component &quot;JBake&quot; as jbake #SkyBlue

  package &quot;Supabase (مفت)&quot; #LightGreen {
    [Auth: OAuth2 Google]
    [Articles (CRUD)]
    [Commentaires]
    [Images (Storage)]
    [Notifications Realtime]
  }

  package &quot;Spring Boot (اختیاری)&quot; #LightCoral {
    [Newsletter Mensuelle]
    note bottom: Job planifié uniquement
  }

  database &quot;PostgreSQL&quot; as db

  jbake --&amp;gt; [Auth: OAuth2 Google]
  jbake --&amp;gt; [Articles (CRUD)]
  jbake --&amp;gt; [Commentaires]
  jbake --&amp;gt; [Images (Storage)]
  jbake --&amp;gt; [Notifications Realtime]

  [Articles (CRUD)] --&amp;gt; db
  [Commentaires] --&amp;gt; db
  [Newsletter Mensuelle] --&amp;gt; db
}

note bottom of &quot;Spring Boot (اختیاری)&quot;
  **Spring Boot pas obligatoire**
  Newsletter peut être gérée
  par un service tiers (Mailchimp)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;فیصلہ&lt;/strong&gt;: 100% Supabase بہت کافی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_saas_ایپلیکیشن&quot;&gt;SaaS ایپلیکیشن&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;SaaS تطبيق - هیبرڈ معماری&quot; {
  component &quot;JBake / رییکٹ&quot; as frontend #SkyBlue

  package &quot;سوپابیس&quot; #LightGreen {
    [Auth Multi-tenant]
    [Profils Utilisateurs]
    [Données Simples]
    [Storage Documents]
  }

  package &quot;Spring Boot&quot; #Coral {
    [Facturation (Stripe)]
    [Analytics Avancées]
    [Rapports Mensuels]
    [Quotas &amp;amp; Limites]
    [Webhooks Stripe]
  }

  cloud &quot;خدمات خارجی&quot; {
    [Stripe API]
    [SendGrid Email]
  }

  database &quot;پوسٹگریSQL شریک&quot; as db

  frontend --&amp;gt; [Auth Multi-tenant]
  frontend --&amp;gt; [Profils Utilisateurs]
  frontend --&amp;gt; [Données Simples]
  frontend --&amp;gt; [Facturation (Stripe)]
  frontend --&amp;gt; [Analytics Avancées]

  [Auth Multi-tenant] --&amp;gt; db
  [Profils Utilisateurs] --&amp;gt; db
  [Données Simples] --&amp;gt; db

  [Facturation (Stripe)] --&amp;gt; db
  [Facturation (Stripe)] --&amp;gt; [Stripe API]
  [Analytics Avancées] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; [SendGrid Email]
  [Webhooks Stripe] ..&amp;gt; [Stripe API] : Écoute
}

note right of &quot;Spring Boot&quot;
  **Nécessaire pour :**
  • Gestion abonnements
  • Facturation récurrente
  • Quotas dynamiques
  • Analytics complexes
  • Webhooks fiables
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;فصلاہ&lt;/strong&gt;: لازمی ہائبرڈ معماری. Supabase اساس کے لیے, Spring Boot مهم حصہ (ادائیگی، بل).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_الکترونیک_تجارت&quot;&gt;الکترونیک تجارت&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;ای-کامرس - 70% Spring Boot&quot; {
  component &quot;ستورفرونٹ (JBake/React)&quot; as frontend #SkyBlue

  package &quot;سپابیس&quot; #LightGreen {
    [Auth Clients]
    [Catalogue Produits\n(lecture seule)]
    [Images Produits]
  }

  package &quot;سپرینگ بوٹ (اساسی کاروبار)&quot; #Coral {
    [Gestion Commandes]
    [Paiements Stripe]
    [Gestion Stock]
    [Calcul Frais Port]
    [Génération Factures]
    [Synchronisation ERP]
    [Emails Transactionnels]
  }

  cloud &quot;انٹیگریشن&quot; {
    [Stripe]
    [Transporteur API]
    [ERP Externe]
  }

  database &quot;PostgreSQL&quot; as db

  frontend --&amp;gt; [Auth Clients]
  frontend --&amp;gt; [Catalogue Produits\n(lecture seule)]
  frontend --&amp;gt; [Gestion Commandes]

  [Auth Clients] --&amp;gt; db
  [Catalogue Produits\n(lecture seule)] --&amp;gt; db

  [Gestion Commandes] --&amp;gt; db
  [Paiements Stripe] --&amp;gt; [Stripe]
  [Gestion Stock] --&amp;gt; db
  [Calcul Frais Port] --&amp;gt; [Transporteur API]
  [Génération Factures] --&amp;gt; db
  [Synchronisation ERP] --&amp;gt; [ERP Externe]
  [Synchronisation ERP] --&amp;gt; db
}

note right of &quot;سپرینگ بوٹ (اساسی کاروبار)&quot;
  **Spring Boot indispensable :**
  • Transactions critiques
  • Orchestration complexe
  • Intégrations multiples
  • Conformité légale
  • Jobs de synchronisation
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;فیصلہ&lt;/strong&gt;Spring Boot ضروری ہے۔ Supabase صرف احرازِ هویت اور کیتالاگ کے لیے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_تقدمی_مایگریشن_کی_حکمت_عملی&quot;&gt;تقدمی مایگریشن کی حکمت عملی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

|Semaine 1-2|
start
:Créer projet Supabase;
:Configurer Auth (Google, GitHub);
:Définir schéma PostgreSQL initial;
:Implémenter CRUD de base sur JBake;
:Déployer MVP sur GitHub Pages;
note right
  **Livrable :** Application fonctionnelle
  **Coût :** 0€
  **Temps :** 1-2 semaines
end note

|Semaine 3-4|
:Observer utilisation réelle;
:Identifier limitations;

|Décision|
if (Logique complexe\némerge ?) then (non)
  |Supabase|
  :Continuer avec Supabase seul;
  :Ajouter Edge Functions si besoin;
  stop
else (oui)
  |Spring Boot|
  :Créer projet Spring Boot;
  :Configurer validation JWT Supabase;
  :Migrer logique complexe vers Spring Boot;
  note right
    **Migration sélective**
    Seulement ce qui est complexe
  end note
endif

|Semaines suivantes|
:Déployer Spring Boot (Cloud Run, EC2);
:Connecter à PostgreSQL Supabase;
:Implémenter premiers jobs planifiés;
:Intégrer APIs tierces;

stop

note right
  **Architecture finale hybride**
  Supabase + Spring Boot
  en parfaite harmonie
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_کوسٹ_اور_عملیاتی_ملاحظات&quot;&gt;کوسٹ اور عملیاتی ملاحظات&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_خर्चوں_کی_ساخت&quot;&gt;خर्चوں کی ساخت&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;تقریبی ماہانہ خراجات&quot; {

  rectangle &quot;مرحلہ MVP
(0-1000 صارفین)&quot; #LightGreen {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot: N/A]
    note bottom: **Total: 0€/mois**
  }

  rectangle &quot;پھیز گروث
(1k-10kصارفین)&quot; #LightYellow {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot (Cloud Run): 20-50€]
    [PostgreSQL (si séparé): 0-30€]
    note bottom: **Total: 20-80€/mois**
  }

  rectangle &quot;مرحلہ سکیل
(10k-100k users)&quot; #LightCoral {
    [JBake (Netlify Pro): 19€]
    [Supabase Pro: 25€]
    [Spring Boot (instances multiples): 100-300€]
    [Redis Cache: 20-50€]
    [Monitoring: 20€]
    note bottom: **Total: 184-414€/mois**
  }
}

note right of &quot;مرحلہ سکیل
(10k-100k users)&quot;
  À ce stade, les revenus
  justifient largement les coûts
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_عملی_ذمائم&quot;&gt;عملی ذمائم&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;کون کون سے امور کا انتظام کرتا ہے؟&quot; {

  rectangle &quot;Supabase کے ذریعے (0 مشقت)&quot; #LightGreen {
    [Authentification]
    [Base de données]
    [Backups automatiques]
    [Scaling automatique]
    [Monitoring DB]
    [Sécurité DB]
  }

  rectangle &quot;GitHub کے زریے منظم(0 محنت)&quot; #SkyBlue {
    [Hébergement site statique]
    [HTTPS/SSL]
    [CDN global]
    [Déploiement automatique]
  }

  rectangle &quot;مینیج کرنا(Spring Boot)&quot; #LightCoral {
    [Déploiement application]
    [Monitoring APM]
    [Logs centralisés]
    [Scaling horizontal]
    [Mises à jour sécurité]
  }
}

note bottom of &quot;مینیج کرنا(Spring Boot)&quot;
  **Minimisable avec :**
  • Cloud Run (serverless)
  • Kubernetes (si nécessaire)
  • Services managés (RDS, etc.)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجہ_مکمل_توازن&quot;&gt;نتیجہ: مکمل توازن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سوبابیس + سپرینگ بوٹ کی ہائبرڈ آرکیٹیکچر تسوية نہیں ہے، یہ ایک&lt;strong&gt;سِینرجی&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_یاد_رکھنے_والے_اصول&quot;&gt;یاد رکھنے والے اصول&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Architecture\nHybride

** Commencer Simple
***_ MVP avec Supabase
***_ 0€ de coût initial
***_ Validation rapide

** Évoluer Intelligemment
***_ Ajouter Spring Boot\nsi nécessaire
***_ Migration progressive
***_ Pas de refonte totale

** Exploiter les Forces
***_ Supabase: Simplicité
***_ Spring Boot: Puissance
***_ PostgreSQL: Source unique

** Minimiser la Complexité
***_ Pas de synchronisation
***_ Pas de duplication
***_ Architecture claire

** Optimiser les Coûts
***_ Gratuit au départ
***_ Scaling progressif
***_ ROI évident

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کب_یہ_معمارى_چنی_چاہیے&quot;&gt;کب یہ معمارى چنی چاہیے؟&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ یہ معمار اچھی طرح مناسب ہے اگر :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;آپ جلد سے شروع کرنا چاہتے ہیں (MVP دنوں میں، ماہوں میں نہیں)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ کاروبار کی پیچیدگی میں اضافے کی امید رکھتے ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ ابتدائی لاگت کو کم کرنا چاہتے ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ کو PostgreSQL پسند ہے اور آپ ایک واحد سچائی کا ذریعہ چاہتے ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ Korlin اور Coroutines کو کاروباری کوڈ کے لیے پسند کرتے ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ پوری vendor lock-in سے بچنا چاہتے ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ یہ معمارتی مناسب نہیں ہے اگر :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;آپ کا پروجيکت سادہ ہے اور اسی طرح رہے گا (ذاتي بلیگ → 100% Supabase کافی ہے)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ کے پاس پہلے سے ایک مستقر بیک اینڈ اسٹیک موجود ہے جسے آپ قابو رکھتے ہیں۔&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ ایک رِسائی مونولیت پسند کرتے ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ کو .NET، Python، یا دیگر باکینڈ زبان کی ضرورت ہے۔&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_آخری_کلی_نظریہ&quot;&gt;آخری کلی نظریہ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;مکمل ہائبرڈ آرکیٹیکچر&quot; {

  actor &quot;صارفین&quot; as users

  rectangle &quot;فرینڈ ایند (ثابت)&quot; #SkyBlue {
    [JBake / GitHub Pages]
    note right: Gratuit, CDN global
  }

  rectangle &quot;بیک ایند سادہ (Supabase)&quot; #LightGreen {
    [Auth OAuth2]
    [CRUD APIs]
    [Storage]
    [Realtime]
    note right
      Gratuit jusqu&#39;à 50k users
      Zéro configuration serveur
    end note
  }

  rectangle &quot;Backend کاروبار (Spring Boot)&quot; #Coral {
    [Orchestration]
    [Jobs Planifiés]
    [Intégrations]
    [Transactions]
    note right
      Activé uniquement
      si nécessaire
    end note
  }

  database &quot;PostgreSQL\nمنفرد سچ کا وسائل&quot; as db #LightGray

  users --&amp;gt; [JBake / GitHub Pages]

  [JBake / GitHub Pages] --&amp;gt; [Auth OAuth2]
  [JBake / GitHub Pages] --&amp;gt; [CRUD APIs]
  [JBake / GitHub Pages] --&amp;gt; [Storage]
  [JBake / GitHub Pages] --&amp;gt; [Realtime]
  [JBake / GitHub Pages] --&amp;gt; [Orchestration]

  [Auth OAuth2] --&amp;gt; db
  [CRUD APIs] --&amp;gt; db
  [Orchestration] --&amp;gt; db
  [Jobs Planifiés] --&amp;gt; db
  [Intégrations] --&amp;gt; db
}

note bottom of db
  **Une seule base, deux consommateurs**
  • Supabase pour le simple
  • Spring Boot pour le complexe
  • Aucune synchronisation requise
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_دونوں_جہانوں_کا_سب_سے_بہتر&quot;&gt;دونوں جہانوں کا سب سے بہتر&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ معماری آپ کو دیتی ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🚀 Supabase کی رفتار&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;گھنٹوں میں شروع، ہفتوں میں نہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;OAuth2 کی تصدیق چند کلیکوں میں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;خودکار طور پر پیدا کردہ REST APIs&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;سرور کی صفر کنفیگریشن&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💪 سپرنگ باٹ کی طاقت&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Kotlin اور کروتائنز کے لیے اِسائنکرونوس خوبصورت کوڈ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;پیچیدہ کاروباری عملوں کی اورکیسٹریشن&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;قابل اعتماد منصوبہ شدہ کام&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ACID گارنٹی شدہ ترanzections&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;مکمل Spring ایکوسیسٹم&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💰 ترقیاتی اقتصاد&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;شروع کرنے اور تصدیق کرنے کے لیے 0€&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;نمو کے ساتھ چلتے والی لاگت&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;جلدی سے زیادہ انجنیرنگ نہیں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🎯 معمارتی لچک&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;تقدمی میگریشن بغیر دوبارہ بنائے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;صرف ضرورت ہونے پر Spring Boot شامل کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;کُل وینڈر لاک-إن نہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;تطوّر پذیر معمارتی&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مزید_آگے_جانے&quot;&gt;مزید آگے جانے&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تقنی_وسائل&quot;&gt;تقنی وسائل&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Supabase ڈاکیومینٹیشن :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/auth&quot;&gt;احراز هویت گائیڈ&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/database/postgres/row-level-security&quot;&gt;سطح سطر سیکیورٹی&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/api&quot;&gt;خود-تیار API&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot کی دستاویز :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/guides/tutorials/spring-boot-kotlin/&quot;&gt;Spring Boot کے ساتھ Kotlin&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/blog/2019/04/12/going-reactive-with-spring-coroutines-and-kotlin-flow&quot;&gt;Coroutines اور Spring&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.spring.io/spring-security/reference/servlet/oauth2/resource-server/jwt.html&quot;&gt;JWT منبع سرور&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اضافی مضامین :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;JWT کے ساتھ API کی سکیورٹی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;PostgreSQL کے کارکردگی کی بہتری&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;پروگرسیو ہجرت کے نمونے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;وزع معماریت میں خطاؤں کا انتظام&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_حقیقی_استعمال_کے_حالات&quot;&gt;حقیقی استعمال کے حالات&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ہائبرڈ آرکیٹیکٹ کامیابی سے استعمال کی جاتی ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;SaaS B2B&lt;/strong&gt;: احراز هویت Supabase، بیلینگ Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;بازاروں&lt;/strong&gt;: Supabase کیکٹالوج, Spring Boot کے ترانزیکشنز&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;محتوا کے پلیٹ فارمز&lt;/strong&gt;: Supabase مضامین، Spring Boot آنالیٹکس&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;اندرونی اوزار&lt;/strong&gt;CRUD Supabase, workflows Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ستارٹاپ_چیک_لسٹ&quot;&gt;ستارٹاپ چیک لسٹ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مرحلہ 1 - بنیادیں (ہفتہ 1)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Supabase اکاؤنٹ بنائیں - [ ] تنظیم پروژیکٹ PostgreSQL - [ ] Auth فعال کریں (Google، GitHub) - [ ] پہلا اسکیم مقرر کریں - [ ] Row Level Security سیٹ اپ کریں - [ ] JBake سے APIs کی ٹیسٹ کریں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Phase 2 - MVP (ہفتے 2-3)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; اسassini صفحات لاگونا - [ ] OAuth2 احراز شناخت شامل کریں - [ ] CRUD فارم بنائیں - [ ] فائلوں کے لیے Storage کو کنفیگر کریں - [ ] گیت ہب پیجز پر ڈپلوار کریں - [ ] واقعی شرائط میں ٹیسٹ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;فاز 3 - ترقی (ضرورت کے مطابق)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; پیچیدہ منطقی ضرورتوں کی شناخت کریں - [ ] در صورت ضرورت، Spring Boot پراجیکٹ بنائیں - [ ] Supabase JWT کی تصدیق کا تنظیم کریں - [ ] PostgreSQL Supabase سے کنکشن کریں - [ ] م پیچیدہ خصوصیات کو منتقل کریں - [ ] جوبز شیڈولڈ کو لاگو کریں - [ ] Spring Boot کو ڈپلוי کریں (Cloud Run، وغیرہ)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_بچنے_والے_انٹی_پیترن&quot;&gt;بچنے والے انٹی-پیترن&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ مت کرو :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Supabase اور Spring Boot کے درمیان ڈیٹا کی نقل کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;دو الگ PostgreSQL بنائیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;خود احراز هویت کو کڈ کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ساده CRUD کے لیے Spring Boot استعمال کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;سورس-آرچیکٹر کرنا ابتداء سے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Supabase کے Row Level Security کو نظرانداز کریں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ بہتر کریں :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;شیئر کریں ایک PostgreSQL ڈیٹا بیس&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Supabase کو احراز هویت کرنے دو&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Spring Boot صرف تعقید کے لیے استعمال کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;سادہ سے شروع کریں اور بالتدريج ترقی کرے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ہر ٹیکنالوجی کی طاقتوں کا فائدہ اٹھائیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ڈیٹابیس کی سطح پر RLS کے ساتھ سیکور کریں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ترقی_کے_امکانات&quot;&gt;ترقی کے امکانات&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_نئی_قابلیتوں_کی_شامل&quot;&gt;نئی قابلیتوں کی شامل&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;موجودہ معمارى&quot; #SkyBlue {
  [JBake]
  [Supabase]
  [Spring Boot]
}

rectangle &quot;ممکن ترقیات&quot; #LightYellow {

  package &quot;عملکردگی&quot; {
    [Redis Cache]
    [CDN pour Assets]
    [PostgreSQL Replicas]
  }

  package &quot;نظارت&quot; {
    [Grafana]
    [Prometheus]
    [Sentry]
  }

  package &quot;سی آئی/سی ڈی&quot; {
    [GitHub Actions]
    [Tests Automatisés]
    [Déploiement Continu]
  }

  package &quot;خصوصیات&quot; {
    [Search (ElasticSearch)]
    [Queue (RabbitMQ)]
    [Event Sourcing]
  }
}

[Spring Boot] .down.&amp;gt; [Redis Cache] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Queue (RabbitMQ)] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Search (ElasticSearch)] : Peut ajouter

[Supabase] .down.&amp;gt; [PostgreSQL Replicas] : Peut ajouter

note bottom
  **Architecture extensible**
  Chaque ajout est indépendant
  Pas de refonte globale nécessaire
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_افقی_سکیلنگ&quot;&gt;افقی سکیلنگ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جب آپ کی ایپلیکیشن بڑھتی ہے، ہائبرڈ معمارتی فطري طور پر سکیل:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;خودکار طور پر ملین عمل تک سکیل بڑھاتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Read replicas کے لیے پڑھنے کی کارکردگی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;امنیتی کے لیے وقت مخصوص کی بازپری&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;سپرینگ بوٹ :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;لوڈ بالینسر کے پیچھے متعدد انسٹنس&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Stateless design افقی scaling کو آسان بناتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kubernetes اورکستریشن کے لیے اگر ضرورت ہو&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;PostgreSQL :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;بڑے ٹیبلز کے لیے تقسیم&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;کانکشن پولنگ (PgBouncer)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sharding اگر بالکل لازمی (نادر)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_معماری_شہادتیں&quot;&gt;معماری شہادتیں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ستارٹ_اپ_saas_50k_استعمال_کرنے_والے&quot;&gt;ستارٹ اپ SaaS (50k استعمال کرنے والے)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ ہم نے 100% Supabase سے شروع کیا۔ 5k صارفین پر، ہم نے صرف Stripe بیلینگ اور ماہانہ رپورٹس کے لیے Spring Boot شامل کیا۔ ایک سال بعد، 80% ہماری آپریشنز اب بھی Supabase سے جاتی ہیں۔ Spring Boot صرف اہم حصے کو منیج کرتا ہے۔ یہ تقسیم ہمیں دوبارہ ڈیزائن کئے بغیر سکیل کرنے کی اجازت دیتی ہے۔ &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ای_لرーニング_پلیٹ_فارم_10k_استعمال_کرنے_والے&quot;&gt;ای-لرーニング پلیٹ فارم (10k استعمال کرنے والے)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Supabase کی OAuth2 تصدیق نے ہمارے 3 ہفتےdevelopment بچائے۔ خود-پیدار APIs ہمارے پوری کورس کٹالوج کو منظم کرتی ہیں۔ Spring Boot صرف PDF سرٹیفکیٹس اور ترقی کے ایمیلز کے لیے استعمال ہوتا ہے۔ ساده، قابل برقرار رکھنے، قابل توسيع۔ &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مارکیٹ_b2b_3k_صارفین&quot;&gt;مارکیٹ B2B (3k صارفین)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Spring Boot خریداری کرنے والوں اور بیچنے والوں کے درمیان ترanzیکشنز (اہم) کا انتظام کرتا ہے۔ Supabase باقی سب کا انتظام کرتا ہے: پروفائلز، حقیقی زمانے کی پیغام رسانی، دستاویزات۔ اس بات کے کونے ان کی یکساں PostgreSQL دیتابیس استعمال کرنے سے ہمیں پیچیدہ ہم آہنگی کرنے کی ضرورت نہیں رہتی۔ یہ ہماری سب سے بہترimar معماری انتخاب ہے جو ہم نے کیا ہے۔ &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ترکیب_ایک_معاصر_معمارستانی_پارادایگم&quot;&gt;ترکیب : ایک معاصر معمارستانی پارادایگم&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Supabase + Spring Boot کی ہائبرڈ آırکیٹیکچر نئی مثال پیش کرتا ہے:&lt;strong&gt;معماری تخصص&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;پرانا پیرادائم&quot; #LightCoral {
  card &quot;بیکینڈ میں سب کچھ&quot; {
    [Auth]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [Storage]
    [Realtime]
  }
  note bottom
    Complexité maximale
    dès le jour 1
  end note
}

rectangle &quot;نیا نمونہ&quot; #LightGreen {
  card &quot;Supabase
(سہولت)&quot; {
    [Auth]
    [CRUD Simple]
    [Storage]
    [Realtime]
  }

  card &quot;Spring Boot
(تفریق)&quot; {
    [Logique Métier]
    [Jobs]
    [Intégrations]
  }

  note bottom
    Complexité progressive
    ajoutée seulement si nécessaire
  end note
}

[Ancien Paradigme] -right-&amp;gt; [Nouveau Paradigme] : Évolution

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;بنیادی اصل :&lt;/strong&gt;پہلے سے موجود سروس کی شکل میں موجود چیز بناؤ نہیں۔ اپنی ایپلیکیشن کو منفرد بنانے والی چیز پر توجہ مرکوز کریں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_8020_کا_اصول&quot;&gt;80/20 کا اصول&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بہت سی ایپلیکیشنز میں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;80% آپریشنز&lt;/strong&gt;یہ معیاری CRUD ہیں → Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;20% عملیاتی&lt;/strong&gt;کاروباری منطق کی ضرورت → Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ فطری قانون ہائبرڈ آركیٹیکچر کی توجیح کرتا ہے&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;عملیات کی تقسیم&quot; {

  rectangle &quot;80% - معیاری اعمال&quot; #LightGreen {
    [Lecture de données]
    [Création d&#39;entités]
    [Mise à jour simple]
    [Suppression]
    [Upload fichiers]
    [Authentification]

    note bottom: **Géré par Supabase**
  }

  rectangle &quot;20% - کاروباری منطق&quot; #Coral {
    [Calculs complexes]
    [Workflows multi-étapes]
    [Transactions critiques]
    [Intégrations tierces]
    [Jobs planifiés]

    note bottom: **Géré par Spring Boot**
  }
}

note right
  **Focus optimal :**
  Votre temps de développement
  concentré sur les 20% qui
  différencient votre produit
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجہ_ختامی&quot;&gt;نتیجہ ختامی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہائبرڈ آركٹچر ایک ٹیکنیکی تسوية نہیں، یہ ایک&lt;strong&gt;استراتیک فیصلہ&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;آپ کو اجازت دیتا ہے:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✅ جلدی شروع کریں ایک کام کرنے والا MVP کے ساتھ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ بہت زیادہ سرمایہ کاری کے بغیر اپنی مارکیٹ کی تصدیق کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ بالتدریج ترقی کریں جب complexity کی ضرورت ہو&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اپنی لاگت کو ہر مرحلے پر منٹین کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ ہر ٹیکنالوجی کے بہترین فائدے کو استعمال کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ پیش از وقت اوور انجینئرنگ سے پرہیز کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ آئندہ کیلئے لچک برقرار رکھیں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;وہ ظاہر کرتی ہے :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;🎯&lt;strong&gt;پراگمٹیسم&lt;/strong&gt;ہر ٹیکنالوجی جہاں وہ اُٹلی ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🚀&lt;strong&gt;سُرعت&lt;/strong&gt;بازار تک کم وقت&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;💰&lt;strong&gt;اقتصاد&lt;/strong&gt;قیمت کے مطابق لاگت&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🔮&lt;strong&gt;قیاس پذیری&lt;/strong&gt;آرکیٹیک جو آپ کے ساتھ بڑھتی ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🛡️&lt;strong&gt;ضبطان&lt;/strong&gt;آزمائش شدہ اور قابل اعتماد خدمات&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_آپ_کا_اگلا_قدم&quot;&gt;آپ کا اگلا قدم&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر یہ معماریت آپ سے بات کرتی ہے، تو یہاں سے شروع کریں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Supabase کا اکاؤنٹ بنائیں&lt;/strong&gt;(مفت)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;اپنے کم سے کم ڈیٹا سکیما کی تعریف کریں&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;OAuth2 کی توثیق کو کنفیگر کریں&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;آپ کی پہلی &lt;code&gt;JBake&lt;/code&gt; صفحہ بنائèn جو &lt;code&gt;API&lt;/code&gt; کو استعمال کرتی ہے&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;GitHub Pages پر ڈپلائیں&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ کے پاس ایک کارکردہ MVP ہوگا میں&lt;strong&gt;کچ دن&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Spring Boot ضرورت ہونے پر خود بخود آئے گا۔ پہلے نہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;ہائبرڈ معمار، یہ درست چیزیں بنانے کی فن ہے، درست وقت پر۔&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;اچھی ترقی! 🚀&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر آپ سمجھتے ہیں کہ یہ مضمون دیگر ڈویلپرز کی مدد کر سکتا ہے معمارتی کے مناسب فیصلے کرنے میں تو اسے شیئر کریں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;preading time : 12 minutes&lt;/div&gt;
&lt;p&gt;Wait we used English incorrectly. Should be Urdu: &quot;.پڑھنے کا وقت : 12 minutes&quot;. Let&amp;#8217;s output that.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&amp;lt;/think&amp;gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;پڑھنے کا وقت : 12 minutes&lt;/div&gt;
&lt;p&gt;Supabase کی سادگی اور Spring Boot کی طاقت کے درمیان انتخاب کرنے کی بجائے، ان دونوں کو ملانے کیوں نہیں؟ ہر ٹیکنالوجی کی بہتر سے بہتر خصوصیات کو استعمال کرتے ہوئے ایک ہائبرڈ معمارے کی دریافت کریں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;ٹک&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_معماری_کی_جدید_جھوٹا_معضل&quot;&gt;معماری کی جدید جھوٹا معضل&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جب کوئی سٹاٹک فرانٹ اند کے ساتھ ایک مڈرن ایپلیکیشن بناتا ہے، تو اکثر اسے ایک بائنری انتخاب کا سامنا کرنا پڑتا ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Backend-as-a-Service حل پر سب چیز لگائیں&lt;/strong&gt;(Supabase, Firebase) - سادہ لیکن محدود&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;مکمل بیکینڈ بناؤ&lt;/strong&gt;(Spring Boot, Node.js) - طاقتور لیکن پیچیدہ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ انتخاب یک جھوٹی معضل ہے. ہائبرڈ آرتکٹچر ایک تیسرا راستہ پیش کرتی ہے: &lt;strong&gt;ہر ٹیکنالوجی کو استعمال کریں جہاں وہ سب سے بہتر ہو&lt;/strong&gt;۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_معمارى_نظریہ&quot;&gt;معمارى نظریہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تقليدی_معماریت_مونولیٹک&quot;&gt;تقليدی معماریت : مونولیٹک&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;تقلیدی عمارت&quot; {
  actor Utilisateur as user
  component &quot;فرینڈ&quot; as frontend #LightBlue
  component &quot;ایک پتھر بیکنڈ&quot; as backend #LightCoral {
    [Authentification]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [APIs Tierces]
  }
  database &quot;ڈیٹا بیس&quot; as db #LightGray

  user --&amp;gt; frontend
  frontend --&amp;gt; backend : Toutes les requêtes
  backend --&amp;gt; db
}

note right of backend
  Tout passe par le backend
  même les opérations simples

  ⚠️ Point de congestion unique
  ⚠️ Complexité dès le départ
  ⚠️ Couplage fort
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ رویے میں، سب سے سادہ اعمال (مکالمہ کا پڑھنا، ایک تبصرہ بنانا) آپ کے بیکینڈ سے گزرنا ضروری ہے۔ آپ پہلے دن سے ہی پیچیدگی کا خرچ ادا کرتے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_عمارى_baas_ہر_نمائندہ&quot;&gt;عمارى BaaS : ہر نمائندہ&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;خالص BaaS معماری&quot; {
  actor Utilisateur as user
  component &quot;فرونٹینڈ&quot; as frontend #LightBlue
  cloud &quot;Supabase / Firebase&quot; as baas #LightGreen {
    [Auth]
    [Database]
    [Storage]
    [Edge Functions]
  }

  user --&amp;gt; frontend
  frontend --&amp;gt; baas : Toutes les opérations
}

note right of baas
  Développement rapide
  Pas de serveur à gérer

  ⚠️ Limité pour logique complexe
  ⚠️ Vendor lock-in
  ⚠️ Edge Functions contraintes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;عکس، ایک BaaS میں سب چیزوں کی ڈیلیگریشن ابتدائی میں کشش لگتی ہے مگر جب کاروباری منطق پیچیدہ ہوتی ہے تو جلدی ہی اس کی حدود نظر آنا شروع ہو جاتی ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_معمارتی_ہائبرڈ_responsabilites_ki_algthali&quot;&gt;معمارتی ہائبرڈ : responsabilites ki algthali&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

actor Utilisateur as user #LightBlue

package &quot;فرونٹینڈ لیئر&quot; {
  component &quot;استاتیک سائٹ JBake&quot; as frontend #SkyBlue
}

package &quot;سادہ لئر (Supabase)&quot; #LightGreen {
  component &quot;تصدیق&quot; as auth
  component &quot;بنیادی CRUD&quot; as crud
  component &quot;فائلز اسٹوریج&quot; as storage
  component &quot;واقعی وقت&quot; as realtime
}

package &quot;کاروباری لاءیر (Spring Boot)&quot; #Coral {
  component &quot;مُعقَّد منطق&quot; as logic
  component &quot;آرکیسٹریشن&quot; as orchestration
  component &quot;شِڈول کردہ نوکریاں&quot; as jobs
  component &quot;انٹیگریشنز&quot; as integrations
}

database &quot;PostgreSQL مشترکہ&quot; as db #LightGray

user --&amp;gt; frontend

frontend --&amp;gt; auth : OAuth2, JWT
frontend --&amp;gt; crud : Articles, Profils
frontend --&amp;gt; storage : Images, Fichiers
frontend --&amp;gt; realtime : Notifications

frontend --&amp;gt; logic : Calculs, Rapports
frontend --&amp;gt; orchestration : Workflows
logic --&amp;gt; integrations : Stripe, APIs
orchestration --&amp;gt; db
jobs --&amp;gt; db

crud --&amp;gt; db
auth --&amp;gt; db

note bottom of db
  **Une seule source de vérité**
  Partagée entre Supabase et Spring Boot
end note

note right of auth
  **Gratuit jusqu&#39;à 50k users**
  Configuration en quelques clics
  OAuth2 multi-providers
end note

note right of logic
  **Activé seulement si nécessaire**
  Kotlin + Coroutines
  Transactions complexes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہائبرڈ أركيتشچر واضح طور پر operational complexity اور nature کے مطابق ذمےदारियों کو الگ کرتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ڈیزائن_کے_اصول&quot;&gt;ڈیزائن کے اصول&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اصول_1_سادہ_سے_شروع_کریں_سمارٹ_طریقے_سے_آگے_بڑھیں&quot;&gt;اصول 1: سادہ سے شروع کریں، سمارٹ طریقے سے آگے بڑھیں&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;مرحلہ 1 : MVP&quot; #LightGreen {
  component &quot;JBake + Supabase&quot; as mvp
  note right
    ✓ Développement en jours
    ✓ Coût : 0€
    ✓ Validation concept
  end note
}

rectangle &quot;**مرحلہ 2 : ترقی**&quot; #LightYellow {
  component &quot;JBake + Supabase
+ Spring Boot (اختیاری)&quot; as growth
  note right
    ✓ Logique métier émerge
    ✓ Premiers jobs planifiés
    ✓ Intégrations tierces
  end note
}

rectangle &quot;**مرстал 3 : Scale**&quot; #LightCoral {
  component &quot;مکمل معماری&quot; as scale
  note right
    ✓ Orchestration complexe
    ✓ Performances optimisées
    ✓ Cache distribué
  end note
}

mvp -down-&amp;gt; growth : Quand la complexité\nle justifie
growth -down-&amp;gt; scale : Optimisation\ncontinue
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اگر آپ کو Spring Boot درکار نہیں ہے تو اسے نہ بنائیں۔&lt;/strong&gt;Supabase کے ساتھ شروع کریں، جب جٹیلتہ اسے جائز ٹھہرائے تو Spring Boot شامل کریں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مبدأ_2_عمل_کی_فربت_کے_مطابق_جدائی&quot;&gt;مبدأ 2 : عمل کی فربت کے مطابق جدائی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Opérations\nApplicatives

left side

** Opérations Simples\n(Supabase)
***_ CRUD Standard
****_ Lecture
****_ Création
****_ Mise à jour
****_ Suppression
***_ Authentification
****_ Login/Logout
****_ OAuth2
****_ Gestion session
***_ Stockage
****_ Upload fichiers
****_ CDN automatique
***_ Temps Réel
****_ WebSocket
****_ Notifications

right side

** Opérations Complexes\n(Spring Boot)
***_ Logique Métier
****_ Calculs complexes
****_ Règles métier
****_ Validations avancées
***_ Orchestration
****_ Multi-services
****_ Transactions distribuées
****_ Saga patterns
***_ Tâches Planifiées
****_ Rapports périodiques
****_ Synchronisations
****_ Nettoyages
***_ Intégrations
****_ Paiements (Stripe)
****_ APIs tierces
****_ Services ML/AI

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اصول_3_ایک_ہی_سچائی_کا_منبع&quot;&gt;اصول 3 : ایک ہی سچائی کا منبع&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

database &quot;PostgreSQL&quot; as db #LightGray {
  package &quot;سکیما: auth (Supabase)&quot; #LightGreen {
    [users]
    [sessions]
    [identities]
  }

  package &quot;اسکیما: عام (مشترک)&quot; #SkyBlue {
    [articles]
    [comments]
    [profiles]
  }

  package &quot;سکیما: کاروبار (Spring Boot)&quot; #Coral {
    [orders]
    [payments]
    [reports]
  }
}

component &quot;سوپابیس&quot; as supabase #LightGreen
component &quot;سپرنگ بوٹ&quot; as spring #Coral

supabase -down-&amp;gt; users : Gère
supabase -down-&amp;gt; sessions : Gère
supabase -down-&amp;gt; articles : Accède
supabase -down-&amp;gt; comments : Accède
supabase -down-&amp;gt; profiles : Accède

spring -down-&amp;gt; articles : Accède
spring -down-&amp;gt; profiles : Accède
spring -down-&amp;gt; orders : Gère
spring -down-&amp;gt; payments : Gère
spring -down-&amp;gt; reports : Gère

note right of db
  **Avantages :**
  • Pas de synchronisation complexe
  • JOINs possibles entre tables
  • Cohérence garantie
  • Migrations unifiées
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک ہی PostgreSQL انسٹنس کو شیئر کرتے ہوئے، Supabase اور Spring Boot ایک ہی ڈیٹا پر کام کرتے ہیں، جس میں پیچیدہ ہمراہی کی ضرورت نہیں ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_فلوؤں_کی_تنظیم&quot;&gt;فلوؤں کی تنظیم&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فلکس_1_مرکزی_تصدیق&quot;&gt;فلکس 1 : مرکزی تصدیق&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;استعمال کننده&quot; as user
participant &quot;جےبیک&quot; as jbake
participant &quot;Supabase احرازِ هویت&quot; as auth
participant &quot;سپرنگ بوٹ&quot; as spring
database &quot;PostgreSQL&quot; as db

== Authentification ==
user -&amp;gt; jbake : Clique &quot;لاگ ان&quot;
jbake -&amp;gt; auth : Redirect OAuth2 (Google/GitHub)
auth -&amp;gt; user : Consent screen
user -&amp;gt; auth : Autorise
auth -&amp;gt; auth : Génère JWT
auth -&amp;gt; jbake : Retourne JWT + Refresh Token
jbake -&amp;gt; jbake : Stocke tokens (sessionStorage)

== Accès aux Ressources ==
group Opération Simple (CRUD)
  user -&amp;gt; jbake : Crée un article
  jbake -&amp;gt; db : POST avec JWT
  note right: Supabase Row Level Security\nvérifie le JWT automatiquement
  db -&amp;gt; jbake : Article créé
end

group Opération Complexe (Métier)
  user -&amp;gt; jbake : Génère un rapport
  jbake -&amp;gt; spring : POST /api/reports\navec JWT
  spring -&amp;gt; spring : Valide JWT Supabase
  spring -&amp;gt; spring : Extrait claims (user_id, roles)
  spring -&amp;gt; db : Requêtes complexes
  spring -&amp;gt; jbake : Rapport généré
end

note over auth, spring
  **Le JWT est universel**
  Valide par Supabase ET Spring Boot
  Pas de double authentification
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اہم نقطہ&lt;/strong&gt;صرف ایک تصدیق کرنے کا عمل، صرف ایک JWT، ہر جگہ استعمال کے قابل۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فلکس_2_ایک_پیچیدہ_کاروباری_عمل_کی_اورکیستریشن&quot;&gt;فلکس 2 : ایک پیچیدہ کاروباری عمل کی اورکیستریشن&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;کلائنٹ&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;سپرینگ بوٹ&quot; as spring
participant &quot;Supabase ڈی بی&quot; as supadb
participant &quot;ستراپی API&quot; as stripe
participant &quot;انبار سروس&quot; as inventory
participant &quot;ای میل سروس&quot; as email
database &quot;PostgreSQL&quot; as db

user -&amp;gt; jbake : Passe commande
jbake -&amp;gt; spring : POST /api/orders/create

== Orchestration Spring Boot ==
spring -&amp;gt; db : BEGIN TRANSACTION

par Vérifications Parallèles
  spring -&amp;gt; inventory : Vérifier stock
  inventory -&amp;gt; spring : Stock OK
else
  spring -&amp;gt; db : Vérifier profil client
  db -&amp;gt; spring : Client vérifié
end

spring -&amp;gt; stripe : Créer Payment Intent
stripe -&amp;gt; spring : Intent créé (ID: pi_xxx)

spring -&amp;gt; db : Créer Order (status: PENDING)
db -&amp;gt; spring : Order créé

spring -&amp;gt; stripe : Confirmer paiement
stripe -&amp;gt; spring : Paiement confirmé

spring -&amp;gt; db : Update Order (status: PAID)
spring -&amp;gt; inventory : Décrémenter stock
spring -&amp;gt; db : COMMIT TRANSACTION

par Notifications Asynchrones
  spring -&amp;gt; email : Email confirmation
else
  spring -&amp;gt; supadb : Insert notification
  note right: Notification temps réel\nvia Supabase Realtime
end

spring -&amp;gt; jbake : Order confirmé
jbake -&amp;gt; user : Affiche confirmation

note over spring
  **Responsabilités Spring Boot :**
  • Transaction ACID
  • Orchestration multi-services
  • Rollback automatique si erreur
  • Gestion des cas limites
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;سپرنگ بوٹ کیا لاتا ہے&lt;/strong&gt;قابل اعتماد اورکستریشن پیچیدہ عملوں کی جس میں متعدد نظامات شامل ہیں اور ٹرانزیکشنل گارنٹی کے ساتھ۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فلکس_3_تختیب_شدہ_کام_اور_ہم_آہنگی&quot;&gt;فلکس 3: تختیب شدہ کام اور ہم آہنگی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

participant &quot;شڈولر\n(Spring Boot)&quot; as scheduler
participant &quot;رپورٹ سروس&quot; as report
participant &quot;PostgreSQL&quot; as db
participant &quot;باہری API&quot; as api
participant &quot;ای میل سروس&quot; as email
participant &quot;Supabase اسٹوریج&quot; as storage

== Job Quotidien : 2h00 ==
activate scheduler
scheduler -&amp;gt; report : Déclenche génération rapport

activate report
report -&amp;gt; db : Récupère données\ndes dernières 24h
db -&amp;gt; report : Dataset

report -&amp;gt; report : Calculs &amp;amp; Agrégations
report -&amp;gt; report : Génération PDF

report -&amp;gt; storage : Upload PDF
storage -&amp;gt; report : URL publique

report -&amp;gt; email : Envoie aux admins\navec lien PDF
deactivate report

== Job Hebdomadaire : Dimanche 3h00 ==
scheduler -&amp;gt; report : Synchronisation externe

activate report
report -&amp;gt; api : Fetch données externes
api -&amp;gt; report : Nouvelles données

report -&amp;gt; db : Mise à jour tables
report -&amp;gt; db : Nettoyage données obsolètes
deactivate report

== Job Mensuel : 1er du mois ==
scheduler -&amp;gt; report : Facturation

activate report
report -&amp;gt; db : Liste clients actifs
report -&amp;gt; report : Calcul montants
report -&amp;gt; api : Génération factures (Stripe)
report -&amp;gt; email : Envoi factures
deactivate report

deactivate scheduler

note right of scheduler
  **Impossible avec Supabase seul**
  Edge Functions non adaptées
  pour jobs longs et récurrents
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot kya lata hai&lt;/strong&gt;: الاعتمادی منسوب شدہ کاروں کے ساتھ حالت کا انتظام، خودکار ریٹری، اور ضمانت شدہ اجرا۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_فیصلہ_سازی_کی_ماترکس&quot;&gt;فیصلہ سازی کی ماترکس&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_supabase_کب_استعمال_کرنا_چاہیے&quot;&gt;Supabase کب استعمال کرنا چاہیے ؟&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité à implémenter;

if (CRUD simple ?) then (oui)
  :✅ **Supabase**;
  stop
else (non)
  if (Authentification ?) then (oui)
    :✅ **Supabase Auth**;
    stop
  else (non)
    if (Upload fichiers ?) then (oui)
      :✅ **Supabase Storage**;
      stop
    else (non)
      if (Temps réel ?) then (oui)
        :✅ **Supabase Realtime**;
        stop
      else (non)
        if (Row Level Security\nsuffisante ?) then (oui)
          :✅ **Supabase + Policies**;
          stop
        else (non)
          :⚠️ **Considérer Spring Boot**;
          #Coral:Passer à l&#39;arbre\nde décision Spring Boot;
          stop
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_spring_boot_کو_استعمال_کب_کرنا_چاہیے&quot;&gt;Spring Boot کو استعمال کب کرنا چاہیے؟&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité complexe;

if (Orchestration\nmulti-services ?) then (oui)
  :✅ **Spring Boot**;
  stop
else (non)
  if (Transaction ACID\ncritique ?) then (oui)
    :✅ **Spring Boot**;
    stop
  else (non)
    if (Job planifié ?) then (oui)
      :✅ **Spring Boot Scheduler**;
      stop
    else (non)
      if (Intégration API\ntierce complexe ?) then (oui)
        :✅ **Spring Boot**;
        stop
      else (non)
        if (Calculs lourds\n&amp;gt; 10 secondes ?) then (oui)
          :✅ **Spring Boot**;
          stop
        else (non)
          if (Cache distribué\nnécessaire ?) then (oui)
            :✅ **Spring Boot + Redis**;
            stop
          else (non)
            :⚠️ **Probablement Supabase**;
            #LightGreen:Revenir à l&#39;arbre\nde décision Supabase;
            stop
          endif
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_پروجیکٹ_کی_قسم_کے_مطابق_معماری_کے_نمونہ&quot;&gt;پروجیکٹ کی قسم کے مطابق معماری کے نمونہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_بلاگ_پورٹ_فورلو&quot;&gt;بلاگ / پورٹ فورلو&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;شخصی بلاگ - 95% Supabase&quot; {
  component &quot;JBake&quot; as jbake #SkyBlue

  package &quot;Supabase (مفت)&quot; #LightGreen {
    [Auth: OAuth2 Google]
    [Articles (CRUD)]
    [Commentaires]
    [Images (Storage)]
    [Notifications Realtime]
  }

  package &quot;Spring Boot (اختیاری)&quot; #LightCoral {
    [Newsletter Mensuelle]
    note bottom: Job planifié uniquement
  }

  database &quot;پاسگری سی کوئل&quot; as db

  jbake --&amp;gt; [Auth: OAuth2 Google]
  jbake --&amp;gt; [Articles (CRUD)]
  jbake --&amp;gt; [Commentaires]
  jbake --&amp;gt; [Images (Storage)]
  jbake --&amp;gt; [Notifications Realtime]

  [Articles (CRUD)] --&amp;gt; db
  [Commentaires] --&amp;gt; db
  [Newsletter Mensuelle] --&amp;gt; db
}

note bottom of &quot;Spring Boot (اختیاری)&quot;
  **Spring Boot pas obligatoire**
  Newsletter peut être gérée
  par un service tiers (Mailchimp)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;فیصلہ&lt;/strong&gt;: 100% Supabase بہت کافی ہے.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_saas_ایپلیکیشن&quot;&gt;SaaS ایپلیکیشن&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;ایپلیکیشن SaaS - ہائبرڈ معماریت&quot; {
  component &quot;JBake / React&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Multi-tenant]
    [Profils Utilisateurs]
    [Données Simples]
    [Storage Documents]
  }

  package &quot;Spring Boot&quot; #Coral {
    [Facturation (Stripe)]
    [Analytics Avancées]
    [Rapports Mensuels]
    [Quotas &amp;amp; Limites]
    [Webhooks Stripe]
  }

  cloud &quot;خارجی خدمات&quot; {
    [Stripe API]
    [SendGrid Email]
  }

  database &quot;PostgreSQL مُشترکہ&quot; as db

  frontend --&amp;gt; [Auth Multi-tenant]
  frontend --&amp;gt; [Profils Utilisateurs]
  frontend --&amp;gt; [Données Simples]
  frontend --&amp;gt; [Facturation (Stripe)]
  frontend --&amp;gt; [Analytics Avancées]

  [Auth Multi-tenant] --&amp;gt; db
  [Profils Utilisateurs] --&amp;gt; db
  [Données Simples] --&amp;gt; db

  [Facturation (Stripe)] --&amp;gt; db
  [Facturation (Stripe)] --&amp;gt; [Stripe API]
  [Analytics Avancées] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; [SendGrid Email]
  [Webhooks Stripe] ..&amp;gt; [Stripe API] : Écoute
}

note right of &quot;Spring Boot&quot;
  **Nécessaire pour :**
  • Gestion abonnements
  • Facturation récurrente
  • Quotas dynamiques
  • Analytics complexes
  • Webhooks fiables
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;فیصلہ&lt;/strong&gt;لازمی ہائبرڈ معماری۔ Supabase بنیادی امور کے لیے، Spring Boot اہم حصے (ادائیگی، بلنگ) کے لیے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ای_کامرس&quot;&gt;ای-کامرس&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;ای-کامرس - 70% Spring Boot&quot; {
  component &quot;فروشگاہ (JBake/React)&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Clients]
    [Catalogue Produits\n(lecture seule)]
    [Images Produits]
  }

  package &quot;Spring Boot (اہم کاروبار)&quot; #Coral {
    [Gestion Commandes]
    [Paiements Stripe]
    [Gestion Stock]
    [Calcul Frais Port]
    [Génération Factures]
    [Synchronisation ERP]
    [Emails Transactionnels]
  }

  cloud &quot;انٹیگریشنز&quot; {
    [Stripe]
    [Transporteur API]
    [ERP Externe]
  }

  database &quot;PostgreSQL&quot; as db

  frontend --&amp;gt; [Auth Clients]
  frontend --&amp;gt; [Catalogue Produits\n(lecture seule)]
  frontend --&amp;gt; [Gestion Commandes]

  [Auth Clients] --&amp;gt; db
  [Catalogue Produits\n(lecture seule)] --&amp;gt; db

  [Gestion Commandes] --&amp;gt; db
  [Paiements Stripe] --&amp;gt; [Stripe]
  [Gestion Stock] --&amp;gt; db
  [Calcul Frais Port] --&amp;gt; [Transporteur API]
  [Génération Factures] --&amp;gt; db
  [Synchronisation ERP] --&amp;gt; [ERP Externe]
  [Synchronisation ERP] --&amp;gt; db
}

note right of &quot;Spring Boot (اہم کاروبار)&quot;
  **Spring Boot indispensable :**
  • Transactions critiques
  • Orchestration complexe
  • Intégrations multiples
  • Conformité légale
  • Jobs de synchronisation
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;فیصلہ&lt;/strong&gt;Spring Boot ضروری ہے۔ Supabase صرف احراز هویت اور catalogue کے لیے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_پروگرسیو_مایگریشن_کی_حکمت_عملی&quot;&gt;پروگرسیو مایگریشن کی حکمت عملی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

|Semaine 1-2|
start
:Créer projet Supabase;
:Configurer Auth (Google, GitHub);
:Définir schéma PostgreSQL initial;
:Implémenter CRUD de base sur JBake;
:Déployer MVP sur GitHub Pages;
note right
  **Livrable :** Application fonctionnelle
  **Coût :** 0€
  **Temps :** 1-2 semaines
end note

|Semaine 3-4|
:Observer utilisation réelle;
:Identifier limitations;

|Décision|
if (Logique complexe\némerge ?) then (non)
  |Supabase|
  :Continuer avec Supabase seul;
  :Ajouter Edge Functions si besoin;
  stop
else (oui)
  |Spring Boot|
  :Créer projet Spring Boot;
  :Configurer validation JWT Supabase;
  :Migrer logique complexe vers Spring Boot;
  note right
    **Migration sélective**
    Seulement ce qui est complexe
  end note
endif

|Semaines suivantes|
:Déployer Spring Boot (Cloud Run, EC2);
:Connecter à PostgreSQL Supabase;
:Implémenter premiers jobs planifiés;
:Intégrer APIs tierces;

stop

note right
  **Architecture finale hybride**
  Supabase + Spring Boot
  en parfaite harmonie
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_خرجی_اور_ملاحظات_عملاتی&quot;&gt;خرجی اور ملاحظات عملاتی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کست_سٹرچر&quot;&gt;کست سٹرچر&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;تخمینہ ماہانہ لاگت&quot; {

  rectangle &quot;مرحلہ MVP
(0-1000 صارفین)&quot; #LightGreen {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot: N/A]
    note bottom: **Total: 0€/mois**
  }

  rectangle &quot;پھیزِ ترقی
(1k-10k صارفین)&quot; #LightYellow {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot (Cloud Run): 20-50€]
    [PostgreSQL (si séparé): 0-30€]
    note bottom: **Total: 20-80€/mois**
  }

  rectangle &quot;مرحلہ سکیل
(10k-100k صارفین)&quot; #LightCoral {
    [JBake (Netlify Pro): 19€]
    [Supabase Pro: 25€]
    [Spring Boot (instances multiples): 100-300€]
    [Redis Cache: 20-50€]
    [Monitoring: 20€]
    note bottom: **Total: 184-414€/mois**
  }
}

note right of &quot;مرحلہ سکیل
(10k-100k صارفین)&quot;
  À ce stade, les revenus
  justifient largement les coûts
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_آperiشنل_ذمے_داری&quot;&gt;آperiشنل ذمے داری&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;کون کیا منیج کرتا ہے ؟&quot; {

  rectangle &quot;Supabase کے ذریعے منظم (0 محنت)&quot; #LightGreen {
    [Authentification]
    [Base de données]
    [Backups automatiques]
    [Scaling automatique]
    [Monitoring DB]
    [Sécurité DB]
  }

  rectangle &quot;گیٹ هب کے ذریعے منظم (کوئی کوشش نہیں)&quot; #SkyBlue {
    [Hébergement site statique]
    [HTTPS/SSL]
    [CDN global]
    [Déploiement automatique]
  }

  rectangle &quot;منجر (Spring Boot)&quot; #LightCoral {
    [Déploiement application]
    [Monitoring APM]
    [Logs centralisés]
    [Scaling horizontal]
    [Mises à jour sécurité]
  }
}

note bottom of &quot;منجر (Spring Boot)&quot;
  **Minimisable avec :**
  • Cloud Run (serverless)
  • Kubernetes (si nécessaire)
  • Services managés (RDS, etc.)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجہ_مکمل_توازن&quot;&gt;نتیجہ : مکمل توازن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Supabase + Spring Boot کی ہائبرڈ معماریت ایک تساهل نہیں، یہ ایک&lt;strong&gt;تآزر&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_یاد_رکھنے_والے_اصول&quot;&gt;یاد رکھنے والے اصول&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Architecture\nHybride

** Commencer Simple
***_ MVP avec Supabase
***_ 0€ de coût initial
***_ Validation rapide

** Évoluer Intelligemment
***_ Ajouter Spring Boot\nsi nécessaire
***_ Migration progressive
***_ Pas de refonte totale

** Exploiter les Forces
***_ Supabase: Simplicité
***_ Spring Boot: Puissance
***_ PostgreSQL: Source unique

** Minimiser la Complexité
***_ Pas de synchronisation
***_ Pas de duplication
***_ Architecture claire

** Optimiser les Coûts
***_ Gratuit au départ
***_ Scaling progressif
***_ ROI évident

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اس_معماریت_کو_کس_وقت_منتخب_کرنا_چاہیے&quot;&gt;اس معماریت کو کس وقت منتخب کرنا چاہیے؟&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ یہ معماریت اس کے لیے مثالی ہے اگر :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;آپ جلد سے شروع کرنا چاہتے ہیں (MVP کے لیے دنوں میں، ماهیں نہیں)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ کاروبار کی پیچیدگی میں اضافے کی امید رکھتے ہیں۔&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ ابتدائی لاگت کو کم کرنا چاہتے ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ PostgreSQL کو محبت کرتے ہیں اور سچائی کا ایکلا مصدر چاہتے ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ کو Kotlin اور Coroutines پسند ہیںكاروباري کوڈ کے لیے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ مکمل وینڈر لاک-این سے بچنا چاہتے ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ یہ معماری مناسب نہیں ہے اگر:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;آپ کا پروجیکٹ سادہ ہے اور یہ اسی طرح رہے گا (شخصی بلاگ → 100% Supabase کافی ہے)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ کے پاس پہلے سے قائم بیکن ایڈ اسٹک ہے جسے آپ maîtrisez&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ ایک روایتی مونو لیٹھ پسند کرتے ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آپ کو .NET، Python یا کوئی بھی بیکینڈ زبان درکار ہے&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_آخری_مجموعی_نظر&quot;&gt;آخری مجموعی نظر&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;مکمل ہائبرڈ آرکیٹیکچر&quot; {

  actor &quot;صارفین&quot; as users

  rectangle &quot;فرونٹینڈ (Static)&quot; #SkyBlue {
    [JBake / GitHub Pages]
    note right: Gratuit, CDN global
  }

  rectangle &quot;Backend Simple (Supabase)&quot; #LightGreen {
    [Auth OAuth2]
    [CRUD APIs]
    [Storage]
    [Realtime]
    note right
      Gratuit jusqu&#39;à 50k users
      Zéro configuration serveur
    end note
  }

  rectangle &quot;کاروباری بیکنڈ (Spring Boot)&quot; #Coral {
    [Orchestration]
    [Jobs Planifiés]
    [Intégrations]
    [Transactions]
    note right
      Activé uniquement
      si nécessaire
    end note
  }

  database &quot;PostgreSQL
منفرد سچائی کا س्रोٹ&quot; as db #LightGray

  users --&amp;gt; [JBake / GitHub Pages]

  [JBake / GitHub Pages] --&amp;gt; [Auth OAuth2]
  [JBake / GitHub Pages] --&amp;gt; [CRUD APIs]
  [JBake / GitHub Pages] --&amp;gt; [Storage]
  [JBake / GitHub Pages] --&amp;gt; [Realtime]
  [JBake / GitHub Pages] --&amp;gt; [Orchestration]

  [Auth OAuth2] --&amp;gt; db
  [CRUD APIs] --&amp;gt; db
  [Orchestration] --&amp;gt; db
  [Jobs Planifiés] --&amp;gt; db
  [Intégrations] --&amp;gt; db
}

note bottom of db
  **Une seule base, deux consommateurs**
  • Supabase pour le simple
  • Spring Boot pour le complexe
  • Aucune synchronisation requise
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_دونوں_جہانوں_کا_سب_سے_بہتر&quot;&gt;دونوں جہانوں کا سب سے بہتر&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ معماری آپ کو دیتا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🚀 Supabase ki raftār&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;گھنٹوں میں شروع، ہفتوں میں نہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;OAuth2 توثیق کچ کلکس میں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;خودکارانہ طور پر پیدا کردہ REST APIs&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;صفر-کونفیگریشن سرور&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💪 Spring Boot کی طاقت&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Kotlin اور Coroutines کے لیے غیر ہم آہنگ کوڈ عصری&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;پیچیدہ کاروباری عملوں کی اورکیسٹریشن&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;کام شڈول کردہ موثوق&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ضمان شدہ ACID تراکنشات&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;کامل سپرنگ ایکوسیسٹم&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💰 ترقیاتی&amp;#8217;économie&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;0€ کے لیے شروع کرنے اور تصدیق کرنے کے لئے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;لگتیں jo trqee ke saath barhti hain&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;قبلвременہ زيادہ انجينئرنگ نہیں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🎯 معماری لچک&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;تدريجي ميگرشن بدون بازنویسی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Spring Boot صرف ضرورت ہونے پر شامل کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;کوئی مکمل ویینڈر لاک-ان نہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ترقی پذیر معماری&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_もっと遠くへ&quot;&gt;もっと遠くへ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تکنیکی_وسائل&quot;&gt;تکنیکی وسائل&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Supabase دستاویزات :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/auth&quot;&gt;تصدیق گائیڈ&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/database/postgres/row-level-security&quot;&gt;رو ليول سيكيورٹی&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/api&quot;&gt;خود-پیدا کردہ APIs&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اسپرنگ بوٹ دستاویزات :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/guides/tutorials/spring-boot-kotlin/&quot;&gt;Spring Boot کے ساتھ Kotlin&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/blog/2019/04/12/going-reactive-with-spring-coroutines-and-kotlin-flow&quot;&gt;Coroutines اور Spring&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.spring.io/spring-security/reference/servlet/oauth2/resource-server/jwt.html&quot;&gt;JWT وسائل سرور&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مزید مضامین :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;JWT کے ساتھ APIS کی سیکیورٹی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;PostgreSQL کی کارکردگی بہتر سازی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;پروگرسیو میگریشن کے نمونے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;وزعتِ معماری میں غلطیوں کا انتظام&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_حقیقی_استعمال_کے_مثالات&quot;&gt;حقیقی استعمال کے مثالات&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ہائبرڈ معماری کامیابیت سے استعمال کی جاتی ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;SaaS B2B&lt;/strong&gt;: Supabase توثیق، Spring Boot بِلنگ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;بازاروں&lt;/strong&gt;: کٹیلاگ Supabase، معاملات Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;محتوا پلیٹ فارمز&lt;/strong&gt;: مقالات Supabase, تحليلات Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;اندرونی ٹولز&lt;/strong&gt;: CRUD Supabase, workflows Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_شروع_کرنے_کی_چیک_لسٹ&quot;&gt;شروع کرنے کی چیک لسٹ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مرحلہ 1 - بنیادیں (ہفتہ 1)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; ساپربیس اکاؤنٹ بنائیں - [ ] پوسٹگری سیکوئل پروجيکٹ کنفیگر کریں - [ ] Auth فعال کریں (Google, GitHub) - [ ] ابتدائی اسکیما تعریف کرنا - [ ] رو لیول سکیورٹی کانفیگر کریں - [ ] JBake سے APIs ٹیسٹ کریں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مرحلہ 2 - MVP (ہفتہ 2-3)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; اصلی صفحات لاپلیمنٹ کریں - [ ] OAuth2 تصدیق کو شامل کریں - [ ] CRUD فورمز بنائیں - [ ] فائلوں کے لیے سٹوریج کو کنفیگر کریں - [ ] گٹ ہب پیج پر ڈپلائیں - [ ] حقیقی احوال میں ٹیسٹ&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مرحلہ 3 - ترقی (ضرورت کے مطابق)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; م پیچیدگی لوجیک کے ضروریات - [ ] ضرورت پڑنے پر Spring Boot بروجیکٹ بنائیں - [ ] Supabase کے JWT تصدیق کو سیٹ اپ کریں - [ ] PostgreSQL Supabase سے منسلک کریں - [ ] مائگریٹ پیچیدہ خصوصیات - [ ] لاگو کریں مفروضہ jobs - [ ] Spring Boot ڈپل کریں (Cloud Run, وغیرہ)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_انٹی_پيٹرنز_سے_بچنا&quot;&gt;انٹی پيٹرنز سے بچنا&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ نہ کریں :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Supabase اور Spring Boot کے درمیان ڈیٹا کو دوبل کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;دو جداگانه PostgreSQL بنائیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;احرازِ هویت کو خود کوڈ کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;سادی CRUD کے لیے Spring Boot استعمال کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شروع سے اضافی ڈیزائن کرنا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Supabase کی Row Level Security کو نادیده کریں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ بلکہ کریں:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;ایک پوسٹگری سکیل ڈیٹا بیس تقسیم کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Supabase کو احرازِ identities کا انتظام کرنے دو&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Spring Boot صرف پیچیدگی کے لیے استعمال کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;سادہ سے شروع کریں، بهتدریج آگے بڑھیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ہر ٹیکنالوجی کی طاقتوں کا استعمال کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ڈیٹابیس کے سطح پر RLS کے ساتھ محفوظ بنائیں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ترقی_کے_امکانات&quot;&gt;ترقی کے امکانات&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_نیے_صلاحیتیں_شامل&quot;&gt;نیے صلاحیتیں شامل&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;معماریت موجودہ&quot; #SkyBlue {
  [JBake]
  [Supabase]
  [Spring Boot]
}

rectangle &quot;ممکن ترقیات&quot; #LightYellow {

  package &quot;عملکردگی&quot; {
    [Redis Cache]
    [CDN pour Assets]
    [PostgreSQL Replicas]
  }

  package &quot;نگرانی&quot; {
    [Grafana]
    [Prometheus]
    [Sentry]
  }

  package &quot;CI/CD&quot; {
    [GitHub Actions]
    [Tests Automatisés]
    [Déploiement Continu]
  }

  package &quot;خصوصیات&quot; {
    [Search (ElasticSearch)]
    [Queue (RabbitMQ)]
    [Event Sourcing]
  }
}

[Spring Boot] .down.&amp;gt; [Redis Cache] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Queue (RabbitMQ)] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Search (ElasticSearch)] : Peut ajouter

[Supabase] .down.&amp;gt; [PostgreSQL Replicas] : Peut ajouter

note bottom
  **Architecture extensible**
  Chaque ajout est indépendant
  Pas de refonte globale nécessaire
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_افقی_سکیلنگ&quot;&gt;افقی سکیلنگ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جب آپ کی ایپلیکیشن بڑھتی ہے، ہائبرڈ آركيٹکچر خود بخود سکیل ہوتی ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;خودکار طور پر ملائنوں عمل تک سکیل&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Read replicas کے لیے کارکردگی پڑھنا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;نقطہ-و-وقت کی ریکاوری سکیورٹی کے لیے&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;سپرنگ بوٹ :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;لوڈ بالینسر کے پیچھے متعدد انستنس&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ستیتلس ڈیزائن ہریزنٹل اسکیلنگ کو آسان بناتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;کبرنیٹس، orchestration کے لئے ضرورت پڑنے پر&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;PostgreSQL :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;بڑے ٹیبلز کے لیے پارٹیشننگ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;کانکشن پولنگ (PgBouncer)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شاردنگ اگر واقعاً ضروری ہے (نادر)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_معماری_شاہدات&quot;&gt;معماری شاہدات&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_saas_اسٹارٹاپ_50k_کاربران&quot;&gt;SaaS اسٹارٹاپ (50k کاربران)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ ہم نے 100% Supabase سے شروع کیا۔ 5k استعمال کرنے والے پر، ہم نے صرف Stripe بلوگنگ اور ماہانہ رپورٹس کے لیے Spring Boot شامل کیا۔ ایک سال بعد، ہماری 80% آپریشنز ابھی بھی Supabase سے گزر رہی ہیں۔ Spring Boot صرف اہم حصے کو منیج کرتا ہے۔ یہ جدائی نے ہمیں دوبارہ بنائے بغیر بڑھنے کی اجازت دی۔ &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ای_لرنینگ_پلےٹ_فارم_10k_صارفین&quot;&gt;ای-لرنینگ پلےٹ فارم (10k صارفین)&lt;/h3&gt;

&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_marketplace_b2b_3k_صارفین&quot;&gt;Marketplace B2B (3k صارفین)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Spring Boot خریداری کنندگان اور فروشندگان کے درمیان ترanzactions کو منظم کرتا ہے (اہم). Supabase سب کچھ سے نپٹا ہے: پروفائل، ریل‑ٹائم میسेजنگ، دستاویزات۔ وہ یہ کہ وہ ایک ہی PostgreSQL ڈیٹابیس شیئر کر رہے ہیں سے ہمیں پیچیدہ synchronization سے بچتی ہے۔ یہ ہمارا سب سے بہتر معماری انتخاب ہے جو ہم نے کیا ہے۔ &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_synthesis_ایک_جدید_معمارتی_نمونہ&quot;&gt;Synthesis: ایک جدید معمارتی نمونہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Supabase + Spring Boot کی ہائبرڈ آرکیٹچر ایک نئی مثال کی نمائندگی کرتی ہے:&lt;strong&gt;معماری کی تخصص&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;پرانا پارادایگم&quot; #LightCoral {
  card &quot;Backend میں تمام چیزیں&quot; {
    [Auth]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [Storage]
    [Realtime]
  }
  note bottom
    Complexité maximale
    dès le jour 1
  end note
}

rectangle &quot;نئی مثال&quot; #LightGreen {
  card &quot;Supabase\n(سہولت)&quot; {
    [Auth]
    [CRUD Simple]
    [Storage]
    [Realtime]
  }

  card &quot;Spring Boot
(تفریق)&quot; {
    [Logique Métier]
    [Jobs]
    [Intégrations]
  }

  note bottom
    Complexité progressive
    ajoutée seulement si nécessaire
  end note
}

[Ancien Paradigme] -right-&amp;gt; [Nouveau Paradigme] : Évolution

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;بنیادی اصل :&lt;/strong&gt;پہلے سے موجود سروس بنائیں نہیں۔ اپنی ایپلیکیشن کو مختلف کرنے والی چیز پر توجہ مرکّز کریں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_8020_کا_قاعدہ&quot;&gt;80/20 کا قاعدہ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;زیادہ تر ایپلیکیشنز میں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;80% عملاقات&lt;/strong&gt;CRUD معیاری ہیں → Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;20% کے عمل&lt;/strong&gt;کاروباری منطق کی ضرورت ہے → Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ فطری قانون ہائبرڈ معماری کی توجہی کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;عملیات کی تقسیم&quot; {

  rectangle &quot;80% - معیاری عملات&quot; #LightGreen {
    [Lecture de données]
    [Création d&#39;entités]
    [Mise à jour simple]
    [Suppression]
    [Upload fichiers]
    [Authentification]

    note bottom: **Géré par Supabase**
  }

  rectangle &quot;20% - کاروباری منطق&quot; #Coral {
    [Calculs complexes]
    [Workflows multi-étapes]
    [Transactions critiques]
    [Intégrations tierces]
    [Jobs planifiés]

    note bottom: **Géré par Spring Boot**
  }
}

note right
  **Focus optimal :**
  Votre temps de développement
  concentré sur les 20% qui
  différencient votre produit
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجہ_اختتامی&quot;&gt;نتیجہ اختتامی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہائبرڈ معمار ایک تکنیکی سمرझؤتا نہیں، یہ ایک&lt;strong&gt;استراتژیک فیصلہ&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;یہ آپ کو اجازت دیتا ہے :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✅ جلدی سے ایک فعال MVP کے ساتھ شروع کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ بہت زیادہ سرمایہ کار کے بغیراپنے مارکیٹ کی تصدیق کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;درجہ دار طور پر ترقی کرنا جب تعقید کی ضرورت ہو&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ہر مرحلے پر اپنی لاگتوں کو کنٹرول کرنا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ ہر ٹیکنالوجی کا بہترین استعمال کرنا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ پیش از وقت اضافی انجینیرنگ سے بچیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ مستقبل کے لیے انعطاف برقرار رکھیں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;یہ نمائندہ ہے :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;🎯&lt;strong&gt;عاملیت&lt;/strong&gt;ہر ٹیکنالوجی جہاں وہ اچھی ہوتی ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🚀&lt;strong&gt;رفتار&lt;/strong&gt;: وقت-بازار کم&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;💰&lt;strong&gt;معیشت&lt;/strong&gt;قیمت کے ساتھ مطابقت رکھنے والے اخراجات&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🔮&lt;strong&gt;قابل توسیع&lt;/strong&gt;: آرکیکچر جو آپ کے ساتھ بڑھتی ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🛡️&lt;strong&gt;ضبَط&lt;/strong&gt;: منظور شدہ اور قابل اعتماد خدمات&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_آپ_کا_اگلا_قدم&quot;&gt;آپ کا اگلا قدم&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر یہ معماریت آپ سے بات کرتی ہے، تو یہاں سے شروع کریں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ایک Supabase اکاؤنٹ بنائیں&lt;/strong&gt;(مفت)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;**اپنا کم سے کم ڈیٹا اسکیما définissez? Wait we need to not include French. So final: &quot;اپنا کم سے کم ڈیٹا اسکیما تعریف کریں&quot;. Ensure no extra punctuation not present. Original had no period. So output without period.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Thus: &quot;اپنا کم سے کم ڈیٹا اسکیما تعریف کریں&quot;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&amp;lt;/think&amp;gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اپنا کم سے کم ڈیٹا اسکیما تعریف کریں**&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;OAuth2 کی تصدیق کو سیٹ اپ کریں&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;اپنی پہلی JBake صفحہ بنائیں جو API استعمال کرتی ہے&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;GitHub Pages پر ڈپلائ کریں&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ کے پاس ایک کام کرنے والا MVP ہوگا میں&lt;strong&gt;چند دن&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Spring Boot ضرورت پڑنے پر خود بخود آئے گا۔ پہلے نہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;ہائبرڈ معمارتی بالضبطانضرورتی چیزوں بنانے کی فن ہے، جس وقت ضرورت ہو.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;اچھی ترقی ! 🚀&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;if آپ سمجھتے ہیں کہ یہ مضمون دیگر ڈویلپرز کے لیے مناسب معمارانہ فیصلے کرنے میں مدد کر سکتا ہے، تو اسے شیئر کریں۔&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table des matières&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_خلاصہ&quot;&gt;خلاصہ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مسئلہ_یہ_لعنتی_ٹھیم_کا_جھلمکاؤ&quot;&gt;مسئلہ: یہ لعنتی ٹھیم کا جھلمکاؤ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_صارف_کے_تجربے_کے_لیے_ایک_بُرا_خواب&quot;&gt;صارف کے تجربے کے لیے ایک بُرا خواب&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_fouc_ایک_پرانا_ویب_مسئلے&quot;&gt;FOUC : ایک پرانا ویب مسئلے&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_معیاریت_کی_ادراک_پر_اثر&quot;&gt;معیاریت کی ادراک پر اثر&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مسئلہ_کی_تکنیکی_تجزیہ&quot;&gt;مسئلہ کی تکنیکی تجزیہ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_کلاسیک_اسکرپٹ_کیوں_کافی_نہیں_ہے&quot;&gt;کلاسیک اسکرپٹ کیوں کافی نہیں ہے؟&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_حدسی_رویہ_لیکن_غیر_مؤثر&quot;&gt;حدسی رویہ لیکن غیر مؤثر&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_domcontentloaded_ایونٹ_کو_سمجھیں&quot;&gt;DOMContentLoaded ایونٹ کو سمجھیں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_render_blocking_کا_مسئلہ&quot;&gt;Render Blocking کا مسئلہ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مشکل_کی_ویژوالائزیشن&quot;&gt;مشکل کی ویژوالائزیشن&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_غیر_مؤثر_حل_کرنے_کی_کوششیں&quot;&gt;غیر مؤثر حل کرنے کی کوششیں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_حقیقی_حل_جلدی_عمل_کریں&quot;&gt;حقیقی حل : جلدی عمل کریں&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_حل_پہلے_بارگزاری_early_loading&quot;&gt;حل: پہلے بارگزاری (Early Loading)&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_اساسی_اصول&quot;&gt;اساسی اصول&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_کیوں_head_مثالی_جگہ_ہے&quot;&gt;کیوں &lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt; مثالی جگہ ہے&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_텐_couche_حل_کی_معماریت&quot;&gt;텐 couche حل کی معماریت&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحلہ_1_استعمال_کرنے_والے_کا_انتخاب_محفوظ_کریں&quot;&gt;مرحلہ 1: استعمال کرنے والے کا انتخاب محفوظ کریں&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_localstorage_آپ_کی_مستمر_यादاشت&quot;&gt;localStorage : آپ کی مستمر यादاشت&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ٹھیم_بیکاپ_کی_تنفيد&quot;&gt;ٹھیم بیکاپ کی تنفيد&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_خطا_کی_حالات_کا_انتظام&quot;&gt;خطا کی حالات کا انتظام&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ترقی_یافتہ_پائیداری_کی_استراتیجیاں&quot;&gt;ترقی یافتہ پائیداری کی استراتیجیاں&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحلہ_2_head_میں_پری_لوڈ_سکرپت&quot;&gt;مرحلہ 2: &lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt; میں پری-لوڈ سکرپت&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_حل_کا_دل&quot;&gt;حل کا دل&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_اسکریپٹ_کی_تشریح_ہر_لکنی_لائن_گنتی_ہوتی_ہے&quot;&gt;اسکریپٹ کی تشریح: ہر لکنی لائن گنتی ہوتی ہے&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_نظام_ترجیح_کی_تشخیص_ایجائز&quot;&gt;نظام ترجیح کی تشخیص (ایجائز)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_عملکردگی_یہ_اسکرپت_تیز_کیوں_ہے&quot;&gt;عملکردگی : یہ اسکرپت تیز کیوں ہے؟&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_بہترین_ترتیب_head_میں&quot;&gt;بہترین ترتیب &lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt; میں&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحلہ_3_css_کے_صفی_محدودات_کی_طاقت&quot;&gt;مرحلہ 3: CSS کے صفی محدودات کی طاقت&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_بوٹسٹرپ_5_ٹیما_سسٹم&quot;&gt;بوٹسٹرپ 5 ٹیما سسٹم&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_css_کی_ساخت_ایک_ٹیم_سسٹم_کے_لیے&quot;&gt;CSS کی ساخت ایک ٹیم سسٹم کے لیے&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_خلاصہ&quot;&gt;خلاصہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ تفصیلی تکنیکی مضافہ میں ہم دیکھتے ہیں کہ ธیم (light/dark) سیلیٹر کیسے ملٹی کریں، بے ضروری جھلمکاؤ کے بغیر جو صفحے کی لوڈ کے دوران پیش آتا ہے۔ ہم براؤزر کے رینڈر سائکل کا تفصیلی تجزیہ کرتے ہیں، FOUC (Flash of Unstyled Content) کے عمیق اسباب کا تجزیہ کرتے ہیں، اور ہم سائنکروس pre‑load پر مبنی مضبوط حل پیش کرتے ہیں میں۔&lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt;۔ یہ تکنیک ایک سموثر اور پیشہ ورانہ صارف تجربہ فراہم کرتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مسئلہ_یہ_لعنتی_ٹھیم_کا_جھلمکاؤ&quot;&gt;مسئلہ: یہ لعنتی ٹھیم کا جھلمکاؤ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_صارف_کے_تجربے_کے_لیے_ایک_بُرا_خواب&quot;&gt;صارف کے تجربے کے لیے ایک بُرا خواب&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;منظر Tasveer لیں: آپ نے اپنی ویب ایپلیکیشن کے لیے ایک خوبصورت دارك थीم ڈیزائن کرنے کے لئے گھنٹے گزار دیے۔ رنگوں مکمل طور پر متوازن ہیں، 대비 کے سطح پر بہترین ہے، اور آپ کے صارفین اس اختیار سے محبت کرتے ہیں۔ ليکن ایک شرmandeہ کن مسئلہ ہے: ہر بار صفحہ ریلوڈ ہونے پر، ایک جزوی سیکنڈ کے لیے، ڈیفالٹ ہلکا theme ظاہر ہوتا ہے، قبل کہ دارك theme اس کی جگہ لے لیتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ بصری &#39;فлэش&#39;، اگرچہ مختصر ( گاهی 100ms سے کم )، انسانی آنکھ کے لیے فوراً محسوس ہوتا ہے اور ایک ناہم تجربہ بناتا ہے۔ ڈارک تھیم یا بصری آرام یا رسائی کے لیے چنے گئے استعمال کرنے والوں کے لیے، یہ جھلمل دردناک بھی ہو سکتا ہے، خاص طور پر کم روشنی والے ماحول میں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_fouc_ایک_پرانا_ویب_مسئلے&quot;&gt;FOUC : ایک پرانا ویب مسئلے&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ phenomenon ایک قسم ہے جسے &quot;`Flash of Unstyled Content` (FOUC)&quot; کہا جاتا ہے، ویب ڈویلپمنٹ کی ایک کلاسیکی مسئلے جو CSS کے ابتدائی اوقات سے متصالح ہے۔ FOUC اس وقت پیش آتا ہے جب براؤزر temporarily HTML کے محتوى کو CSS کے اسٹائلز لاگ किए बिना دکھاتا ہے، جس سے غیر اسٹائلڈ مواد کا فلیش پیدا ہوتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہمارے مخصوص صورت حال میں، ہم پوری طرح غیر‑استائل شدہ محتوا کے بارے میں بات نہیں کر رہے ہیں، بلکہ ایک کے بارے میں&lt;strong&gt;غلط تھیم کی چمک&lt;/strong&gt;(FOWT) - مواد اسٹائل کی گئی ہے، لیکن غلط थीم کے ساتھ۔ یہ خاص طور پر ناگوار ہے کیونکہ یہ دکھاتا ہے کہ ہماری ایپلیکیشن &quot;oublie&quot; استعمال کرنے والی کی ترجیح کو ہر صفحے کے لوڈ پر۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_معیاریت_کی_ادراک_پر_اثر&quot;&gt;معیاریت کی ادراک پر اثر&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ مسئلا، اگرچہ ٹیکنیکل ہے، آپ کے ایپلیکیشن کی کیفیت کے ادراک پر اہم اثرات ڈالتا ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;صقیلگی کی کمی&lt;/strong&gt;جھلملاہٹ سے محسوس ہوتا ہے کہ ایپلیکیشن مکمل نہیں یا بهتر طرح سے optimize نہیں کی گئی۔ صارف اکثر اس چھوٹی بصری نقصانات کو عام نقصان پیشہ ورانگی سے جوڑتے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اتساق میں انقطاع&lt;/strong&gt;: لاگ لگے &#39;بھول&#39; جاتی ہے استعمال کرنے والے کی ترجحات، جس سے انٹرفیس اور امیدوں کے درمیان بے synchronization کا احساس پیدا ہوتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;بصری تھکاوٹ&lt;/strong&gt;روشَنائی کے حساس استعمال کرنے والوں یا میگرن سے جھپٹے والے افراد کے لیے، یہ چمکدار فлэش صرف ایک سادہ زیبائی‑مرتبط بے‑اراحتی سے زیادہ ہو سکتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;محسوس کردگی&lt;/strong&gt;آئرانیک، اگرچہ آپ کی ویب سائیٹ جلد سے لوڈ ہوتی ہے، یہ جھلملاٹ سست یا کم متجاوب application جیسا محسوس دلایا سکتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مسئلہ_کی_تکنیکی_تجزیہ&quot;&gt;مسئلہ کی تکنیکی تجزیہ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آئسے مسئلے کو حل کرنے کا طریقہ سمجھنے کے لیے، پہلے اس کا سبب سمجھنا ضروری ہے۔ جھلملات تین اہم واقعات کے درمیان وقت کی انحراف کی وجہ سے ویب پیج کے زندگی چکر میں پیش آتی ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;HTML کا ابتدائی پارسنگ&lt;/strong&gt;براؤزر آپ کے پیج کی ساخت پڑھتا اور تجزیہ کرتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;CSS اسٹائلز کا استعمال&lt;/strong&gt;براؤزر CSS کے قاعدے لاگو کرتا ہے اور بصری rendar کا حساب لگاتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;JavaScript کی نفيذ&lt;/strong&gt;: آپ کا کوڈ جو theme بدلتا ہے چلتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مشکل یہ پیش آتی ہے جب واقعہ نمبر 3 (JavaScript کی execution) اس وقت آتا ہے جب براؤزر پہلے سے ہی واقعہ نمبر 2 (style کی application) کا شروع یا اختتام کر چکا ہوتا ہے۔ اس موقع پر براؤزر نے پہلے سے ہی فیصلہ کر لیوتا ہے کہ کون سا تمہ دکھانا ہے اور آپ کا کوڈ پہلا رینڈر ہونے سے پہلے اس پر اثرانداز ہونے کے لیے Bohut دیر سے پہنچتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_کلاسیک_اسکرپٹ_کیوں_کافی_نہیں_ہے&quot;&gt;کلاسیک اسکرپٹ کیوں کافی نہیں ہے؟&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_حدسی_رویہ_لیکن_غیر_مؤثر&quot;&gt;حدسی رویہ لیکن غیر مؤثر&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک ڈویلپر کے لیے سب سے طبیعی انحصار یہ ہوگا کہ وہ ہمارے&amp;#8230;&amp;#8203; کے آخر میں ایک سکرپٹ رکھے۔`&amp;lt;body&amp;gt;`جو استعمال کرنے والے کے محفوظ تمہ کی جانچ کرتا ہے اور اسے لاگو کرتا ہے۔ یہ رویہ ویب کی riwajati behteen maSLaaqon ka pAltaa hai jo script ko safah ke akhir mein load karne ki sifaarish karte hain taake render block na ho.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;// À la fin de &amp;lt;body&amp;gt; - L&#39;APPROCHE INSUFFISANTE
document.addEventListener(&#39;DOMContentLoaded&#39;, () =&amp;gt; {
  const theme = localStorage.getItem(&#39;preferred-theme&#39;);
  if (theme === &#39;dark&#39;) {
    document.documentElement.setAttribute(&#39;data-bs-theme&#39;, &#39;dark&#39;);
  }
});&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ طریق کار پہلے نظر میں منطقی لگتی ہے۔ ہم DOM کے تیار ہونے کا انتظار کرتے ہیں، پھر ہم ธีม لاگو کرتے ہیں۔ سادہ، نہیں؟ متاسفانه، یہ سادگی بنیادی خرابی کو چھپاتی ہے جو براؤزر کے رینڈرنگ سائیکل کے ٹائمنگ سے متعلق ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_domcontentloaded_ایونٹ_کو_سمجھیں&quot;&gt;DOMContentLoaded ایونٹ کو سمجھیں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;واقعہ`DOMContentLoaded`یہ جب HTML کا ابتدائی ڈॉकومینٹ مکمل طور پر لوڈ ہو کر براؤزر سے تجزیہ کر لیا جاتا ہے،&lt;strong&gt;فورا&lt;/strong&gt;اسٹائل شیٹس، تصاویر، اور سب فریمز کے لوڈ ہونے کا ختم ہونا۔ یہ ایک اہم نقطہ ہے جسے سمجھنا ضروری ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ واقعات کی نمادینی تسلسل ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;براؤزر HTML ڈاؤنلوڈ کرنے شروع کر دیتا ہے۔&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;یہ HTML کا تجزہ کرتا ہے جیسے اسے دریافت کیا جاتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;وہ ٹیgzكشف کرتا ہے`&amp;lt;link&amp;gt;`CSS کے لیے اور انہیں ڈاؤنلوڈ کرنا شروع کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;وہ ٹیگس کا دریافت کرتا ہے`&amp;lt;script&amp;gt;`اور ان کو 실행 کرتا ہے (ان کے نوع اور خصوصیات کے مطابق)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;وہ DOM (Document Object Model) بناتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;موقع &lt;code&gt;DOMContentLoaded&lt;/code&gt; واقع ہوتا ہے&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;وہ اسٹائلز لاگو کرنے اور لايآؤٹ بنانے کا کام جاری رکھتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;پہلا paint (نمائش) پیش آتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;واقعہ`load`یہ تمام وسائل لوڈ ہونے پر چالہ ہوتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مسئلہ؟ سٹاپ 6 (DOMContentLoaded) اور سٹاپ 8 (پہلا پینٹ) کے درمیان، براؤزر پہلے سے ہی فیصلہ کر چکا ہے کہ صفحہ کیسے ڈسپلے کرنا ہے۔ اگر آپ کا ٹیم چینج سکرپٹ سٹاپ 6 پر چلتا ہے، تو پہلے سے ہی پہلے دکھاوے سے بچنے کے لیے ڈیفالٹ اسٹائلز کے ساتھ زیادہ دیر ہو چکی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_render_blocking_کا_مسئلہ&quot;&gt;Render Blocking کا مسئلہ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;واقعیت میں، ٹائمزنگ مزید پیچیدہ ہے۔ موجودہ براؤزر perceived performance کو بہتر بنانے کے لیے متقاعد اور پیچیدہ optimisation تکنیکیں استعمال کرتے ہیں۔ وہ پہلے پینٹ (First Contentful Paint) کو ممکنہ سب سے جلد کرنے کی کوشش کرتے ہیں تاکہ صارف اسکرین پر کچھ دیکھ سکے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;CSS &quot;render-blocking&quot; بصورت افتراضي، جس کا مطلب ہے کہ براؤزر پہلے پیینٹ کرنے سے قبل اسٹائل شیٹس ڈاؤنلوڈ اور پرس کرنے کا انتظار کرتا ہے۔ یہ معقول ہے: ہم غیر سٹائل شدہ مواد دکھانا نہیں چاہتے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہاں پھنسا یہ ہے: جب براؤزر پہلی بار یہ سی ایس ایس اسٹائلز لاگو کرتا ہے، تو وہ موجودہ ڈوم کی حالت کے مطابق عمل کرتا ہے۔ اگر صفت`data-bs-theme`ابھی تک ٹاگ پر مُعَرَّف نہیں ہے`&amp;lt;html&amp;gt;`, براؤزر ڈیفالٹ اسٹائلز لاگو کرے گا (عام طور پر ہلکا ธีม).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پھر، جب آپ کا سکرپٹ چلتا ہے اور یہ خصوصیت تبدیل کرتا ہے، براؤزر کو :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;اس تبدیلی سے متاثرے اسٹائلز کا dubara حساب لگائیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ضرورت پڑنے پر لیٹ دوبارہ بنائیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;متاثر ہونے والے عناصر کو دوبارہ رنگیں&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ری کیلکول اور رے پینٹنگ کا عمل ہے جو مرئی جھلملاہٹ پیدا کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مشکل_کی_ویژوالائزیشن&quot;&gt;مشکل کی ویژوالائزیشن&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہمشکل تسلسل کو سمجھنے کے لیے، ایک تفصیلی تسلسل ڈائگرام کا جائزہ لیں:&lt;/p&gt;
&lt;/div&gt;
&lt;div id=&quot;diag-flux-incorrect&quot; class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Utilisateur
participant Navigateur
participant &quot;پارسَر HTML&quot; as Parser
participant &quot;CSSOM&quot; as CSS
participant &quot;اسکرپت.js (body کے آخر)&quot; as Script
participant &quot;رینڈر انجن&quot; as Render

Utilisateur -&amp;gt; Navigateur: Demande la page
activate Navigateur

Navigateur -&amp;gt; Parser: Parse le HTML
activate Parser
Parser -&amp;gt; CSS: Découvre et charge les CSS
activate CSS
Parser -&amp;gt; Parser: Construit le DOM
Parser -&amp;gt; Navigateur: DOM Ready (DOMContentLoaded)
deactivate Parser

CSS -&amp;gt; CSS: Parse les feuilles de style
CSS -&amp;gt; Render: CSSOM Ready
deactivate CSS

activate Render
Render -&amp;gt; Render: Calcule les styles avec data-bs-theme=&quot;&quot;note right: موضوع پیش فرض (light)
Render -&amp;gt; Navigateur: پہلا پینٹ (موضوع روشن)
note right: صارف موضوع روشن کو دیکھتا ہے
deactivate Render

Navigateur -&amp;gt; Script: اسکرپٹ چلاتا ہے
activate Script
Script -&amp;gt; Script: localStorage پڑھتا ہے
Script -&amp;gt; Navigateur: setAttribute(&#39;data-bs-theme&#39;, &#39;dark&#39;)
deactivate Script

activate Render
Render -&amp;gt; Render: CSS کے استائلیں کا حساب لگاتا ہے data-bs-theme=&quot;dark&quot;
note right: Thème sombre
Render -&amp;gt; Navigateur: Repaint (Thème Sombre)
note right: Clignotement visible
deactivate Render

deactivate Navigateur
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ڈائرگرام مسئلے کو واضح طور پر دکھاتا ہے: پہلا پینٹ اس وقت ہوتا ہے جب ہمارا اسکرپٹ مناسب تھیيم سیٹ کرنے کا موقع نہیں ملتی۔ بعد میں ہونے والا رپینٹ مرئی جھلملاتی پیدا کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_غیر_مؤثر_حل_کرنے_کی_کوششیں&quot;&gt;غیر مؤثر حل کرنے کی کوششیں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;چند طریقوں کو اس مسئلے کو حل کرنے کی کوشش کی گئی، لیکن اکثر کے اپنے‑اپنے نقصانات ہیں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Approach 1: لود ہونے تک مواد کو چھپا کریں&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;body {
  opacity: 0;
  transition: opacity 0.3s;
}

body.loaded {
  opacity: 1;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ طریقہ JavaScript کے صحیح ٹھی밂 کو سیٹ کرنے تک تمام مواد کو چھپا رکھتا ہے۔ masalah؟ یہ مصنوعی طور پر مواد کی دکھائی کو دیرانداز کرتا ہے، جس سے سایت زیادہ سست لگنے کا احساس ہوتا ہے۔ علاوہً، اگر JavaScript غیر فعال کر دیا جائے، تو صارف کو کچھ بھی نہیں دikhái دےتا!&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;طریقہ 2: لوڈر/اسپنر استعمال کریں&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Approach 1 کی طرح، لیکن بار‑لوڈر سپنر کے ساتھ۔ یہ مسئلے کو ڈھپکت ہے لیکن اصل عمل بہتری نہیں کرتی اور بے ضروری محسوس ہونے والی دیر شامل کرتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;طریقہ 3: پیش فرض ڈارک تھییم&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کسی ڈویلپر ڈارک ثیم کو CSS میں ڈیفالٹ کے طور پر معین کرتے ہیں۔ یہ ڈارک ثیم کے صارفین کے لیے جھمکنا روک دیتا ہے، لیکن روشن ثیم کے صارفین کے لیے برعکس مسئلہ پیدا کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ تمام اندراجات مناسب نہیں ہیں کیونکہ وہ بیماری کے علامت پر توجہ مرکوز کرتی ہیں، بنیادی سبب پر نہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_حقیقی_حل_جلدی_عمل_کریں&quot;&gt;حقیقی حل : جلدی عمل کریں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اس مسئلے کو حل کرنے کی کلید یہ ہے کہ ہم کو یہ جاننا ہے کہ ہم کو اس خصوصیت کو تعریف کرنا ہوگا۔&lt;code&gt;data-bs-theme&lt;/code&gt; &lt;strong&gt;پہلے&lt;/strong&gt;کہ براؤزر CSS اسٹائلز لاگو کرنے شروع نہیں کرتا۔ اس کا مطلب یہ ہے کہ ہمارا سکرپت پیج کے زندگی цикیل میں پہلے اجرا ہونا چاہیے، اور یہی وہ چیز ہے جو ہم اگلے حصے میں جانچیں گے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_حل_پہلے_بارگزاری_early_loading&quot;&gt;حل: پہلے بارگزاری (Early Loading)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اساسی_اصول&quot;&gt;اساسی اصول&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہماری جھلملاوٹ کا خوبصورت حل ایک سادہ لیکن طاقتور اصول پر مبنی ہے :&lt;strong&gt;ایپلیکیشن کی حالت کو براؤزر کے رینڈرنگ پروسیس کے ساتھ ہم آہنگ کرنا&lt;/strong&gt;صفحے کے لوڈ ہونے کے بعد themes کو سیٹ کرنے کا انتظار کرنے کی بجائے، ہمیں فوراً themes کو سیٹ کرنا ہوگا۔&lt;strong&gt;دوران&lt;/strong&gt;بار لوڈ، حتی سے پہلے CSS کے اسٹائل لاگو نہیں کیے گئے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہApproach &#39;Early Loading&#39; یا &#39;Synchronous Preloading&#39; keh kahī jātī hai web development ke istilahāt mein۔ Idea yeh hai ke hum apni theme detection logic ko page ke life cycle mein sab se pehle mumkin had tak execute karte hain, ideally tag ke andar۔&lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt;, حتی براؤزر سے پہلے CSS فائلز ڈاؤنلوڈ کرنے سے پہلے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کیوں_head_مثالی_جگہ_ہے&quot;&gt;کیوں &lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt; مثالی جگہ ہے&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Le `&amp;lt;head&amp;gt;`ایک HTML دستاویز براؤزر کے ذریعے سِیکوئینسی طور پر، اوپر سے نیچے تک محروس کیا جاتا ہے۔ ہر عنصر اس کے ظہور کے مطابق ترتیب میں محروس کیا جاتا ہے۔ یہ خصوصیت ہماری حل کے لیے ضروری ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جیسے براؤزر ایک ٹیگ سے ملتا ہے`&amp;lt;script&amp;gt;`کے اندر`&amp;lt;head&amp;gt;`خصائص کے بغیر`async` ou &lt;code&gt;defer&lt;/code&gt;, il :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;HTML کے پارسنگ کو رک دیں&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;اسکرپٹ ڈاؤنلوڈ کریں&lt;/strong&gt;(اگر externe) یا بستر (اگر ان لائن)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;اسکریپت فوراً چلائیں&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;HTML کا parsing دوبارہ شروع کریں&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ رویہ، اکثر کارکردگی کے مسئلے کے طور پر سمجھا جاتا ہے (جس کی وجہ سے سکرپٹس کو صفحے کے آخر میں رکھنے کی مشورہ ملتی ہے)، اس مخصوص صورت میں ہمارا حليف بن جاتا ہے۔ ہماری ٹیم ڈٹیکشن سکرپٹ کو صفحے کے آغاز پر رکھ کر`&amp;lt;head&amp;gt;`, ہم یہ ضمانت دیتے ہیں کہ یہ براؤزر کے ٹیگز سے ملاقات کرنے سے پہلے نفذ ہوتا ہے`&amp;lt;link&amp;gt;`ہمارے اسٹائل شیٹ.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_텐_couche_حل_کی_معماریت&quot;&gt;텐 couche حل کی معماریت&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;همारा مكمل حل تین متبادل جدولخ سے بناؤا ہے, ہر ایک مخصوص rôle ادا کر رہا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Layer 1 : Persistence (localStorage)&lt;/strong&gt; یہ لیئر سشنز کے درمیان صارف کے انتخاب کو محفوظ کرنے اور دوبارہ لانے کا ذمہ دار ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;طبقہ 2 : جلدی ہم آہنگی (&lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt; میں این لائن اسکرپت)&lt;/strong&gt; یہ لیئر ایپلیکیشن کے وضع کو DOM کے ساتھ ابتدائی رینڈر سے پہلے ہم آہنگ کرتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;طبقہ 3 : ریاکٹِیو اسٹائلز (CSS میں ایٹریبیوٹ سلیکٹرز)&lt;/strong&gt; یہ لیر ویجول سٹائلز تعین کرتی ہے جو لیر 2 کے ذریعے معین کردہ حالت پر مبنی ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ابھی ہر لایر کی تفصیل سے استكشاف کریں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مرحلہ_1_استعمال_کرنے_والے_کا_انتخاب_محفوظ_کریں&quot;&gt;مرحلہ 1: استعمال کرنے والے کا انتخاب محفوظ کریں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_localstorage_آپ_کی_مستمر_यादاشت&quot;&gt;localStorage : آپ کی مستمر यादاشت&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Le &lt;code&gt;localStorage`یہ Web Storage API ہے جو key-value pairs (کلی‑قدر) کو براؤزر میں مستقل طور پر محفوظ کرنے کی اجازت دیتا ہے۔ کوکیز کے برعکس، ڈیٹا کا`localStorage&lt;/code&gt;:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;انہیں سرور پر خودکار طور پر کبھی بھی نہیں بھیجا جاتا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ان کی ذخیرہ کرنے کی صلاحیت زیادہ ہوتی ہے (عام طور پر 5-10 MB)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ان کی کوئی ختم ہونے کی تاریخ نہیں ہوتی (واضح حذف تک قائم رہتے ہیں)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;انہیں پروٹوکول اور ڈومین تک محدود کیا جاتا ہے (Same-Origin Policy)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہمارا استعمال کا مثال، ال`localStorage`ہے مکمل کیونکہ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;ہم سرور کے ساتھ یہ معلومات کا اشتراک کرنے کی ضرورت نہیں ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ہم چاہتے ہیں کہ ترجیح permanent طور پر برقرار رہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;مطلوب شدہ ذخیرہ کرنے کا سائز بہت کم ہے (چند بائٹ)&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ٹھیم_بیکاپ_کی_تنفيد&quot;&gt;ٹھیم بیکاپ کی تنفيد&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ہے کہ ہم صارف کا انتخاب محفوظ کرتے ہیں جب وہ theme تبدیل کرتا ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;// Fonction complète pour changer le thème
function setTheme(newTheme) {
  // Validation de l&#39;entrée
  if (![&#39;light&#39;, &#39;dark&#39;, &#39;auto&#39;].includes(newTheme)) {
    console.error(&#39;Thème invalide:&#39;, newTheme);
    return;
  }

  try {
    // Sauvegarde dans localStorage
    localStorage.setItem(&#39;preferred-theme&#39;, newTheme);

    // Application immédiate dans le DOM
    document.documentElement.setAttribute(&#39;data-bs-theme&#39;, newTheme);

    // Dispatch d&#39;un événement personnalisé pour notifier d&#39;autres composants
    window.dispatchEvent(new CustomEvent(&#39;theme-changed&#39;, {
      detail: { theme: newTheme }
    }));

    console.log(&#39;Thème changé:&#39;, newTheme);
  } catch (error) {
    console.error(&#39;Erreur lors de la sauvegarde du thème:&#39;, error);
    // Fallback : on applique quand même le thème visuellement
    document.documentElement.setAttribute(&#39;data-bs-theme&#39;, newTheme);
  }
}

// Exemple d&#39;utilisation avec un bouton
document.getElementById(&#39;theme-toggle&#39;).addEventListener(&#39;click&#39;, () =&amp;gt; {
  const currentTheme = document.documentElement.getAttribute(&#39;data-bs-theme&#39;) || &#39;light&#39;;
  const newTheme = currentTheme === &#39;light&#39; ? &#39;dark&#39; : &#39;light&#39;;
  setTheme(newTheme);
});&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_خطا_کی_حالات_کا_انتظام&quot;&gt;خطا کی حالات کا انتظام&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ضروری ہے کہ وہ حالات جہاں`localStorage`یہ دستیاب یا رسائی پذیر نہیں ہے۔ کئی مواقف us tak pohunch rok sakte hain`localStorage` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;سخت خفیہ نیویگیشن&lt;/strong&gt;سافاری برائیوزنگ کے خفیہ موڈ میں ایک استثنا اٹھاتی ہے`QuotaExceededError`کے اندر لکھنے کی कोशिशوں کے دوران`localStorage`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;خفیہ تنظیمات&lt;/strong&gt;کچھ براؤزروں یا رازداری کے اضافے پہنچ کو بلوک کر سکتے ہیں`localStorage`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;دومین کی حدودیتیں&lt;/strong&gt; : Le `localStorage`پروتوكول پر وصول نہیں`file://`کچھ براؤزرز میں.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اسٹوریج جگہ پر بھرپور&lt;/strong&gt;: اگرچہ نادر، اسٹوریج کی جگہ پوری طرح بھری جا سکتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لہذا ہمارا کوڈ ایک بلاک استعمال کرتا ہے`try&amp;#8230;&amp;#8203;catch`ان حالات کو خوشگوار انداز سے منظم کرنے کے لیے، موضوع تبدیلی کی سہولت جاری رکھتے ہوئے، جبکہ پوسٹنسنس دستیاب نہ ہو۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ترقی_یافتہ_پائیداری_کی_استراتیجیاں&quot;&gt;ترقی یافتہ پائیداری کی استراتیجیاں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;زیادہ پیچیدہ طلبوں کے لیے، آپ اضافی حکمت عملیوں پر غور کر سکتے ہیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;سروئر ہم آہنگی (اختیاری)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;async function setTheme(newTheme) {
  // Sauvegarde locale immédiate
  localStorage.setItem(&#39;preferred-theme&#39;, newTheme);
  document.documentElement.setAttribute(&#39;data-bs-theme&#39;, newTheme);

  // Synchronisation serveur en arrière-plan (si l&#39;utilisateur est connecté)
  if (userIsAuthenticated()) {
    try {
      await fetch(&#39;/api/user/preferences&#39;, {
        method: &#39;POST&#39;,
        headers: { &#39;Content-Type&#39;: &#39;application/json&#39; },
        body: JSON.stringify({ theme: newTheme })
      });
    } catch (error) {
      console.warn(&#39;Échec de la synchronisation serveur:&#39;, error);
      // L&#39;échec n&#39;est pas critique car la préférence est déjà sauvegardée localement
    }
  }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہapproach ربط شدہ استعمال کرنے والوں کے لیے ڈیوائسوں کے درمیان ترجیحوں کو ہم آہنگ کرنے کی اجازت دیتا ہے، اور مقامی فوری جواب دینے کی قابلیت کو محفوظ رکھتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مرحلہ_2_head_میں_پری_لوڈ_سکرپت&quot;&gt;مرحلہ 2: &lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt; میں پری-لوڈ سکرپت&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_حل_کا_دل&quot;&gt;حل کا دل&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہاں جادو سچمچ سے کام کرتی ہے۔ ہم ایک چھوٹا اسکریپٹ رکھیں گے۔&lt;strong&gt;ان لاين&lt;/strong&gt;ہماری میں مستقیماً`&amp;lt;head&amp;gt;`, hamari sabhi tags se pehle`&amp;lt;link&amp;gt;`یہ اسکرپٹ ارادی طور پر مینیمل، خود مختار، اور ممکنہ حد تک جلد chalنے کے لیے بنایا گیا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html lang=&quot;fr&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;meta charset=&quot;UTF-8&quot;&amp;gt;
    &amp;lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&amp;gt;
    &amp;lt;title&amp;gt;Mon Site Incroyable&amp;lt;/title&amp;gt;

    &amp;lt;!-- ==========================================
         NOTRE SCRIPT MAGIQUE DE PRÉ-CHARGEMENT
         Ce script DOIT être le premier élément
         dans le &amp;lt;head&amp;gt; après les meta tags
         ========================================== --&amp;gt;
    &amp;lt;script&amp;gt;
      // IIFE pour ne pas polluer le scope global
      (function() {
        &#39;use strict&#39;;

        try {
          // Lecture de la préférence sauvegardée
          const savedTheme = localStorage.getItem(&#39;preferred-theme&#39;);

          // Si une préférence existe, on l&#39;applique immédiatement
          if (savedTheme) {
            document.documentElement.setAttribute(&#39;data-bs-theme&#39;, savedTheme);
          }
          // Optionnel : Détecter la préférence système si aucune sauvegarde
          else if (window.matchMedia &amp;amp;&amp;amp; window.matchMedia(&#39;(prefers-color-scheme: dark)&#39;).matches) {
            document.documentElement.setAttribute(&#39;data-bs-theme&#39;, &#39;dark&#39;);
          }
          // Sinon, le thème par défaut du CSS sera utilisé (généralement &#39;light&#39;)

        } catch (error) {
          // En cas d&#39;erreur (localStorage bloqué, etc.), on log discrètement
          // et on laisse le thème par défaut s&#39;appliquer
          console.warn(&#39;Impossible de charger la préférence de thème:&#39;, error);
        }
      })();
    &amp;lt;/script&amp;gt;
    &amp;lt;!-- FIN DU SCRIPT MAGIQUE --&amp;gt;

    &amp;lt;!-- Les feuilles de style sont chargées APRÈS le script --&amp;gt;
    &amp;lt;link rel=&quot;stylesheet&quot; href=&quot;css/bootstrap.min.css&quot;&amp;gt;
    &amp;lt;link rel=&quot;stylesheet&quot; href=&quot;css/styles.css&quot;&amp;gt;

    &amp;lt;!-- Autres ressources du head --&amp;gt;
    &amp;lt;link rel=&quot;icon&quot; href=&quot;favicon.ico&quot;&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;!-- Contenu de la page --&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اسکریپٹ_کی_تشریح_ہر_لکنی_لائن_گنتی_ہوتی_ہے&quot;&gt;اسکریپٹ کی تشریح: ہر لکنی لائن گنتی ہوتی ہے&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;چلیے اس سکرپٹ کو لائن بای لائن تجزیہ کرتے ہیں۔ ہر ڈیزائن فیصلہ کو سمجھنے کے لیے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;IIFE (فوری طور پر بپレス ہونے والی فانکشن ایکسپرشن)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;(function() {
  // ...
})();&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ڈھانچہ ایک فنکشن بناتی ہے جو فوری طور پر چلتا ہے۔ کیوں؟ تاکہ ہم اپنی متغیرات کو لوکل سkope میں علیحدہ کر سکیں اور عالمی سkope کو آلودہ ہونے سے بچ سکیں۔ اگرچہ ہم صرف`const`(جس کا بلاک سkoپ ہے), IIFE ایک اچھی عمل ہے جو ہماری نیتوں واضح بناتا ہے اور اسموں کے ممکن تصادم سے حفاظت کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;سٹریکٹ مود&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;&#39;use strict&#39;;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ہدایت JavaScript کے سٹرکٹ موڈ کو فعال کرتی ہے، جو: - غیر تصریح شدہ متغیرات کے استعمال پر پابندی - خطرناک آپریشنز کے لیے غلطی بناتا ہے - بعضی جاوا اسکرپٹ انجنوں میں کارکردگی کو بہتر بناتا ہے&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایسا حساس سکرپٹ جیسا یہ، ہم سب سے زیادہ سکیورٹی چاہتے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;try&amp;#8230;&amp;#8203;catch بلوک&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;try {
  // Code principal
} catch (error) {
  console.warn(&#39;Impossible de charger la préférence de thème:&#39;, error);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ بلک بالکل اہم ہے۔ یہ یقینی بناتا ہے کہ اگر کوئی چیز غلط ہو جائے (localStorage مسدود، ناممکن سینٹکس خرابی وغیرہ) تو ہمارا سکرپٹ پوری صفحے کا لوڈ روک نہیںے گا۔ استعمال کرنا`console.warn`بلکہ`console.error`یہ بتاتا ہے کہ یہ ایک غیرحرجی مسئلہ ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;localsStorage کی پڑھائی&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;const savedTheme = localStorage.getItem(&#39;preferred-theme&#39;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ لائن کچھ مخصوص سیاقات (سفاری کی سخت خفیہ ریموتنگ) میں ایک استثنا پراہنی ہو سکتی ہے۔ اس لیے اسے try&amp;#8230;&amp;#8203;catch بلوک میں رکھا گیا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;شرطی ایپلیکیشن&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;if (savedTheme) {
  document.documentElement.setAttribute(&#39;data-bs-theme&#39;, savedTheme);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم theme کو صرف تو لاگو کرتے ہیں جب ہم نے اسے محفوظ شدہ پایا ہو؛ ورنہ، ہم CSS کو اپنی ڈیفالٹ theme استعمال کرنے دیتے ہیں۔ یہ اندراز JavaScript میں ہارڈ کوڈ شدہ ڈیفالٹ قيمة سے زیادہ مضبوط ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_نظام_ترجیح_کی_تشخیص_ایجائز&quot;&gt;نظام ترجیح کی تشخیص (ایجائز)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک اختیاراتی لیکن خوبصورت بہتری یہ ہے کہ آپ کے ایپلیکیشن میں، صارف کے عمل ہونے والے سسٹم کی تھیم ترجیح کا پتہ لگایا جائے، اگر وہ اب تک اپنی ایپلیکیشن میں واضح اختیار نہیں کیا :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;else if (window.matchMedia &amp;amp;&amp;amp; window.matchMedia(&#39;(prefers-color-scheme: dark)&#39;).matches) {
  document.documentElement.setAttribute(&#39;data-bs-theme&#39;, &#39;dark&#39;);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ فیچر Media Query استعمال کرتا ہے`prefers-color-scheme`system کو پوچھنے کے لئے. macOS, Windows 10+, iOS, اور آندروید کے جدید نسخے پر، یہ کوئری صارف کے نظام کی ترجیح واپس کرتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;مفائد :&lt;/strong&gt; - پہلا بازدید سے شخصیاتی تجربہ - مستعمل کے نظام کے ماحول سے مطابقت - پہلی ویزٹ کے لیے کوئی اسٹوریج ضروری نہیں&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;ملاحظات :&lt;/strong&gt; - تمام براؤزرز اس فیچر کو سپورٹ نہیں کرتے (مگر 2020 سے اس کا سپورٹ شاندار ہے) - تصدیق`window.matchMedia`مطابقت کو یقینی بناتا ہے - صارف ہمیشه یہ اختیار اوورلوڈ کر سکتا ہے&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_عملکردگی_یہ_اسکرپت_تیز_کیوں_ہے&quot;&gt;عملکردگی : یہ اسکرپت تیز کیوں ہے؟&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہمارا پیش‑لوڈنگ سکرپت بے مثالی رفتار کرنے کے لیے بنایا گیا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;حدّ کم ازمائی سائز&lt;/strong&gt;: تقریباً 300 بائٹ غیر مینوفائیڈ، 200 بائٹ مینوفائیڈ۔ یہ کسی بھی تصویر یا جاوا اسکرپٹ لائبریری کی نسبت معذورات سے زیادہ نہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Inline&lt;/strong&gt;ایضافی HTTP درخواست نہیں۔ اسکرپٹ HTML میں ہے، اس لیے فوری دستیاب ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;سادہ ہمמן اعمال&lt;/strong&gt;کلید کی پڑھنا localStorage میں (بہت tez عمل) اور DOM کی صفت کی ترمیم (براؤزر کی داخلی عمل).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;کسی انحصار نہیں&lt;/strong&gt;کوئ فریم ورک نہیں، کوئی لائبریری نہیں، صرف سادہ جاوا اسکریپت۔ شروع ہونے کا وقت نہیں، انحصارات کا پارسنگ نہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;ایک بار تنفیذ&lt;/strong&gt;اس اسکرپٹ ایک بار لُوڈ ہونے پر چلتا ہے۔ أيےٹ لیسنر نہیں، لُوپ نہیں، پیچیدہ حساب نہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;عملی طور پر، حَدِيث ہارڈور پر، یہ سکرپٹ 1 ملِسی سیونڈ سے کم وقت میں چلتا ہے، ایک غیر محسوس وقت جو صفحے کے لوڈ کی کارکردگی پر کوئی اثر نہیںانداز کرتا۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_بہترین_ترتیب_head_میں&quot;&gt;بہترین ترتیب &lt;code&gt;&amp;lt;head&amp;gt;&lt;/code&gt; میں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;عناصر کیordre میں`&amp;lt;head&amp;gt;`مهم ہے۔ یہ تجویز شدہ ترتیب :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;head&amp;gt;
    &amp;lt;!-- 1. Métadonnées critiques --&amp;gt;
    &amp;lt;meta charset=&quot;UTF-8&quot;&amp;gt;
    &amp;lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&amp;gt;

    &amp;lt;!-- 2. Notre script de pré-chargement (IMMÉDIATEMENT après les meta) --&amp;gt;
    &amp;lt;script&amp;gt;
      (function() { /* notre code */ })();
    &amp;lt;/script&amp;gt;

    &amp;lt;!-- 3. Titre de la page --&amp;gt;
    &amp;lt;title&amp;gt;Mon Site&amp;lt;/title&amp;gt;

    &amp;lt;!-- 4. Feuilles de style --&amp;gt;
    &amp;lt;link rel=&quot;stylesheet&quot; href=&quot;styles.css&quot;&amp;gt;

    &amp;lt;!-- 5. Autres ressources (fonts, favicons, etc.) --&amp;gt;
    &amp;lt;link rel=&quot;preconnect&quot; href=&quot;https://fonts.googleapis.com&quot;&amp;gt;
    &amp;lt;link rel=&quot;icon&quot; href=&quot;favicon.ico&quot;&amp;gt;

    &amp;lt;!-- 6. Autres scripts avec defer ou async --&amp;gt;
    &amp;lt;script src=&quot;app.js&quot; defer&amp;gt;&amp;lt;/script&amp;gt;
&amp;lt;/head&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ حکم یقینی بناتا ہے کہ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;چarset متنی عمل سے پہلے تعین کردہ ہوتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ہمارا سکرپٹ CSS کے لوڈ سے پہلے چلتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;CSS بعد میں لوڈ کیے جاتے ہیں اور وہ مستقیم مناسب موضوع لاگو کرتے ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;غیر حتمی وسائل آخر میں لوڈ کئے جاتے ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مرحلہ_3_css_کے_صفی_محدودات_کی_طاقت&quot;&gt;مرحلہ 3: CSS کے صفی محدودات کی طاقت&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_بوٹسٹرپ_5_ٹیما_سسٹم&quot;&gt;بوٹسٹرپ 5 ٹیما سسٹم&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bootstrap 5 نے CSS custom properties (CSS variables) اور ایٹریبیٹ سلكتورز پر مبنی themes کے gérer کا ایک شاندار نظام پیش کیا۔ یہ نظام اس ایٹریبیٹ کو استعمال کرتا ہے۔&lt;code&gt;data-bs-theme`العنصر پر&lt;/code&gt;&amp;lt;html&amp;gt;`رنگ کے متغیرات کی کون سی مجموعہ لاگو کرنے کے لیے.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نظام کی خوبصورتی اس کی سادگی میں ہے : ہزاروں عناصر پر مختلف CSS فائلوں لوڈ کرنے یا کلاسوں کو ٹوگِل کرنے کے بجائے، ہم صرف ایک عنصر پر ایک صفت کو سادہ طریقے سے تبدیل کرتے ہیں، اور CSS کاسکیڈ کی مدد سے بقیہ خود کار کر دیتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_css_کی_ساخت_ایک_ٹیم_سسٹم_کے_لیے&quot;&gt;CSS کی ساخت ایک ٹیم سسٹم کے لیے&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ایک مکمل CSS ساخت ہے جس کا استعمال مضبوط تھیم سسٹم کو لاگو کرنے کے لیے کیا جاتا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;/**
 * SYSTÈME DE THÈME COMPLET
 * Utilise les Custom Properties CSS pour une maintenance facile
 */

/* ============================================
   THÈME PAR DÉFAUT (LIGHT)
   Défini sur :root pour être le fallback
   ============================================ */
:root {
  /* Couleurs de base */
  --color-primary: #0d6efd;
  --color-secondary: #6c757d;
  --color-success: #198754;
  --color-danger: #dc3545;
  --color-warning: #ffc107;
  --color-info: #0dcaf0;

  /* Couleurs de fond */
  --bg-primary: #ffffff;
  --bg-secondary: #f8f9fa;
  --bg-tertiary: #e9ecef;

  /* Couleurs de texte */
  --text-primary: #212529;
  --text-secondary: #6c757d;
  --text-tertiary: #adb5bd;

  /* Couleurs de bordure */
  --border-color: #dee2e6;
  --border-color-subtle: #e9ecef;

  /* Couleurs d&#39;ombre */
  --shadow-sm: rgba(0, 0, 0, 0.075);
  --shadow-md: rgba(0, 0, 0, 0.15);
  --shadow-lg: rgba(0, 0, 0, 0.25&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

