&lt;li&gt;&lt;a href=&quot;#_logback_ترتیب&quot;&gt;Logback ترتیب&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_کامل_ٹیسٹ_کلاس&quot;&gt;کامل ٹیسٹ کلاس&lt;/a&gt;&lt;/li&gt;
