&lt;li&gt;&lt;a href=&quot;#_مثال_واقعی_موضوعات_کی_دستاویز&quot;&gt;مثال واقعی: موضوعات کی دستاویز&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_نتیجہ&quot;&gt;نتیجہ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_منابع&quot;&gt;منابع&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_تعارف&quot;&gt;تعارف&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;فنّی دستاویزات کی ترتیب کرتے وقت، خاص طور پر اسٹائل گائیڈز یا یوزر انٹرфейس کی سبسفیKS کے لیے، رنگوں کی پالیٹ دکھانا عام طور پر ضروری ہوتا ہے۔ AsciiDoc، گرچہ دستاویزات کے لیے بہت طاقتور ہے، لیکن رنگوں کے نمونے دکھانے کے لیے نیٹیو سینٹکس فراہم نہیں کرتا۔ یہ مضمون مسئلے کی تفتیش کرتا ہے اور HTML انجیکشن پر مبنی یک خوشگوار حل پیش کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مسئلہ&quot;&gt;مسئلہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_استعمال_کا_سیاق&quot;&gt;استعمال کا سیاق&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;تصور کریں کہ آپ ویب ایپلیکیشن کے تھیم کی CSS متغیرات کی دستاویزات تیار کر رہے ہیں۔ آپ کو درکار ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;ہیکسیڈسیمل رنگ کے کوڈز فہرست بنائیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ہر رنگ کا بصری پیشنمائش دکھائیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;دستاویز کی پڑھنے کی آسانی برقرار رکھیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;استاتیک سائٹ جنریٹرز JBake جیسے کی مطابقت کو یقینی بنانا&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
skinparam packageStyle rectangle

actor &quot;ٹیکنیکل رائٹر&quot; as writer
actor &quot;قارئ&quot; as reader

rectangle &quot;توضیحات اسکی ڈॉक&quot; {
  usecase &quot;رنگوں की پلیٹ کو डキュमेंट کریں&quot; as UC1
  usecase &quot;ہیکساڈسیمال کوڈ دکھائیں&quot; as UC2
  usecase &quot;رنگ دکھائیں&quot; as UC3
  usecase &quot;اسٹیٹک سائٹ بنائیں&quot; as UC4
  usecase &quot;دستاویزات دیکھیں&quot; as UC5
}

writer --&amp;gt; UC1
UC1 ..&amp;gt; UC2 : include
UC1 ..&amp;gt; UC3 : include
UC1 --&amp;gt; UC4
UC4 --&amp;gt; UC5
UC5 &amp;lt;-- reader
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ممکن_طریقے&quot;&gt;ممکن طریقے&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک AsciiDoc دستاویز میں رنگ دکھانے کے لیے کئی حلوں پر غور کیا جا سکتا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam componentStyle rectangle

package &quot;ممکن حلول&quot; {
  component &quot;يونيكوڈ حروف&quot; as unicode
  component &quot;باہری تصاویر&quot; as images
  component &quot;CSS کی مخصوص رو̄ل&quot; as css
  component &quot;انجیکشن HTML&quot; as html
}

package &quot;قیمت کرنے کے معیار&quot; {
  component &quot;سادگی&quot; as simple
  component &quot;پورتبل&quot; as portable
  component &quot;شخصیتی&quot; as custom
  component &quot;رکھاؤٹ&quot; as maintain
}

unicode -down-&amp;gt; simple : ✓
unicode -down-&amp;gt; portable : ✓
unicode -down-&amp;gt; custom : ✗

images -down-&amp;gt; simple : ✗
images -down-&amp;gt; portable : ✗
images -down-&amp;gt; custom : ✓

css -down-&amp;gt; simple : ~
css -down-&amp;gt; portable : ✗
css -down-&amp;gt; custom : ✓

html -down-&amp;gt; simple : ✓
html -down-&amp;gt; portable : ✓
html -down-&amp;gt; custom : ✓✓
html -down-&amp;gt; maintain : ✓

note right of html
  Solution recommandée
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_اختیار_1_کاراکٹرز_یونیکوڈ&quot;&gt;اختیار 1 : کاراکٹرز یونیکوڈ&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یونیکوڈ حروف استعمال کرنے کی طرح`&amp;#9632;`(■) سادہ ہے لیکن محدود :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* ■ --accent-color: #7952b3 (violet Bootstrap)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Limitations&lt;/strong&gt; : رنگ پر کوئی کنٹرول نہیں، سسٹم فونت پر مشتمل ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_اختيار_2_باہری_تصاویر&quot;&gt;اختيار 2: باہری تصاویر&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہر رنگ کے لیے PNG یا SVG تصاویر بنائیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* image:colors/violet.svg[width=16] --accent-color: #7952b3&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;حدود&lt;/strong&gt; : ثقيلة الصيانة، تكاثر الملفات، لا مزامنة تلقائية&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_اختیار_3_وظائف_css_مخصص&quot;&gt;اختیار 3 : وظائف CSS مخصص&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;CSS کلاسوں کو تعریف کریں اور انہیں AsciiDoc کے رولز کے ذریعے استعمال کریں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* [.color-violet]##■## --accent-color: #7952b3&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Limitations&lt;/strong&gt; : باہر کا اسٹائل شیٹ ضروری ہے، تمام ممکن رنگوں کی پہلے سے تعریف.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_اختیار_4_انجیکشن_html_منتخب_شدہ_حل&quot;&gt;اختیار 4 : انجیکشن HTML (منتخب شدہ حل)&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;میکرو استعمال کریں``HTML کو ان لائن اسٹائل کے ساتھ انزیکٹ کرنے کے لیے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;
background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;]
--accent-color: #7952b3 (violet Bootstrap)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_حل_html_انجیکشن_کے_ساتھ&quot;&gt;حل: HTML انجیکشن  کے ساتھ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کام_کرنے_کا_اصول&quot;&gt;کام کرنے کا اصول&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ماکرو``d&amp;#8217;AsciiDoc خام مواد داخل کرنے کی اجازت دیتا ہے جو AsciiDoc پروسيسر tarafından تفسیر نہیں کیا جائے گا. یہ ہم HTML کو inline CSS styles کے ساتھ سیدھی طرح inject کرنے کی اجازت دیتا ہے.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
participant &quot;دستاویز
AsciiDoc&quot; as doc
participant &quot;پروسيسر
AsciiDoc&quot; as processor
participant &quot;پاس:[] ماکرو&quot; as pass
participant &quot;HTML
آخری&quot; as html

doc -&amp;gt; processor : Analyse document
processor -&amp;gt; pass : Détecte pass:[]
pass -&amp;gt; processor : Retourne HTML brut
processor -&amp;gt; html : Insère sans transformation
html -&amp;gt; html : Navigateur applique styles
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_تنفیذ&quot;&gt;تنفیذ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ HTML انجیکٹ کرنے والی ساخت ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;span style=&quot;display:inline-block;
             width:1em;
             height:1em;
             background:#7952b3;
             vertical-align:middle;
             margin-right:0.5em&quot;&amp;gt;
&amp;lt;/span&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_css_کے_خواص_کی_وضاحت&quot;&gt;CSS کے خواص کی وضاحت&lt;/h4&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 25%;&quot;&gt;
&lt;col style=&quot;width: 75%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;ملکیت&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;عمل&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;display:inline-block&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;width/height ki tareef karne ki ijazat deta hai, inline flow mein rehke&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;width:1em; height:1em&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;مربے کا سائز فوانٹ کے سائز کے منسوب میں (responsive)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;background:#7952b3&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;دکھانے والا رنگ (آپ کی ضرورت کے متغیر)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;vertical-align:middle&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;مربع کو مجاور متن کے ساتھ منظم کریں&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;margin-right:0.5em&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;چوکور اور متن کے درمیان فاصلہ&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مثال_کامل&quot;&gt;مثال کامل&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ایک مثال ہے جو موضوع کی پالیٹ کو ڈاکیومنٹ کرتی ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;== Thème Clair

* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#f8f9fa;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --bg-primary: `#f8f9fa` (blanc cassé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#212529;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --text-primary: `#212529` (noir très foncé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-color: `#7952b3` (violet Bootstrap)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#61428f;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-hover: `#61428f` (violet plus foncé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --card-bg: `#ffffff` (blanc)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کون درج ذیل رینڈر بناتا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;موضوع روشی&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em:background:#f8f9fa;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --bg-primary:`#f8f9fa`(سفید مائل)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#212529;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --text-primary:`#212529`(بہت گہرا سیاہ)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --accent-color:`#7952b3`(بنفشی Bootstrap)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#61428f;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --accent-hover:`#61428f`(گہرے بنفشی)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&gt;&lt;/span&gt; --card-bg:`#ffffff`(سفید)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_بهتر_بنانے_کے_طریقے_اور_اچھی_رویć&quot;&gt;بهتر بنانے کے طریقے اور اچھی رویć&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ہلکی_رنگات_کو_منیج_کریں&quot;&gt;ہلکی رنگات کو منیج کریں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بہت ہلکا رنگوں (سفید, بہت ہلکا سرمئی) کے لیے، ان کو سفید پس منظر پر مرئی بنانے کے لیے ایک کنارہ شامل کریں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;
background:#ffffff;border:1px solid #ccc;
vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سرمئی سرحد (&lt;code&gt;border:1px solid #ccc&lt;/code&gt;) سفید مربع کو سفید پس‌منظر پر محدود کرنے کی اجازت دیتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_چورhay_کا_سائز_ملائیں&quot;&gt;چورhay کا سائز ملائیں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ مربعوں کے سائز کو اپنی ضرورت کے مطابق بدل سکتے ہیں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span style=&quot;display:inline-block;width:1.5em;height:1.5em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] Grand carré
* pass:[&amp;lt;span style=&quot;display:inline-block;width:0.8em;height:0.8em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] Petit carré&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایکائی کا استعمال`em`یہ یقین دلاتا ہے کہ مربع فونٹ کے سائز کے ساتھ ایڈجسٹ ہوتے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_محتوا_بنائیں&quot;&gt;محتوا بنائیں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;خاص ضرورت کے لیے، آپ مختلف شکلیں بنا سکتے ہیں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_رنگین_دائرہ&quot;&gt;رنگین دائرہ&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;border-radius:50%;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] Cercle violet&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_رنگدار_حد_والا_مربع&quot;&gt;رنگدار حد والا مربع&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:3px solid #7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] Bordure violette&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_حل_کی_معماری&quot;&gt;حل کی معماری&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
package &quot;دキュمنٹیشن workflow&quot; {
  [Document AsciiDoc\navec pass macro] as asciidoc
  [Processeur JBake] as jbake
  [Site HTML statique] as html
  [Navigateur Web] as browser
}

asciidoc --&amp;gt; jbake : 1. Compilation
jbake --&amp;gt; html : 2. Génération
html --&amp;gt; browser : 3. Affichage
browser --&amp;gt; browser : 4. Rendu CSS

note right of asciidoc
  Contient les balises
  pass:[] avec HTML inline
end note

note right of jbake
  Préserve le HTML
  dans pass:[]
end note

note right of browser
  Applique les styles
  inline CSS
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_فوائد_اور_محدودیتیں&quot;&gt;فوائد اور محدودیتیں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فوائد&quot;&gt;فوائد&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✓ &lt;strong&gt;Autonomie&lt;/strong&gt; : باہر کے فائلز پر کوئی انحصار نہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✓ &lt;strong&gt;Portabilité&lt;/strong&gt; : AsciiDoc کے تمام پروسیسرز کے ساتھ کام کرتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✓ &lt;strong&gt;ہم آہنگی&lt;/strong&gt; : رنگ کا کوڈ HTML میں مستقیماً موجود ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✓ &lt;strong&gt;Flexibilité&lt;/strong&gt; : اسلوب کی مکمل شخصیتی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✓ &lt;strong&gt;مرمت&lt;/strong&gt; : سادہ Hexadecimal کوڈ میں ترمیم&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✓ &lt;strong&gt;جبییک کی سازگاری&lt;/strong&gt; : مکمل طور پر سٹیٹیک سائٹ جنریٹرز کے ساتھ کام کرتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_محدودیت&quot;&gt;محدودیت&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✗ &lt;strong&gt;لفاظی&lt;/strong&gt; : HTML کوڈ تکراری AsciiDoc کے源 میں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✗ &lt;strong&gt;Source ki parhnay ki aasani&lt;/strong&gt; : Source document ziyādah saaf nahi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✗ &lt;strong&gt;قابل رسائی&lt;/strong&gt; : کوئی فطری متبادل متن نہیں (Manual طور پر شامل کرنا)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_امکان_پذیری_میں_بہتری&quot;&gt;امکان پذیری میں بہتری&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اسکرین ریڈرز کے لیے مربع کو رسائی پذیر بنانے کے لیے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;* pass:[&amp;lt;span role=&quot;img&quot; aria-label=&quot;Couleur violet Bootstrap&quot;
style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;
vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;]
--accent-color: `#7952b3` (violet Bootstrap)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;خصوصیات`role=&quot;img&quot;` et `aria-label`مدد کرنے والی ٹیکنالوجیز بصری مواد کو سمجھنا اور تصویر بنانا ممکن بناتی ہیں.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مثال_واقعی_موضوعات_کی_دستاویز&quot;&gt;مثال واقعی: موضوعات کی دستاویز&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ایک مکمل مثال ہے جو کئی موضوعات کی وضاحت کرتی ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Guide des couleurs de l&#39;application

== Thème Clair (`:root`)

* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#f8f9fa;border:1px solid #ccc;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --bg-primary: `#f8f9fa` (blanc cassé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#212529;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --text-primary: `#212529` (noir très foncé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#7952b3;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-color: `#7952b3` (violet Bootstrap)

== Thème Sombre (`[data-bs-theme=&quot;dark&quot;]`)

* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#212529;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --bg-primary: `#212529` (noir très foncé)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:1px solid #999;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --text-primary: `#ffffff` (blanc)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#0d6efd;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-color: `#0d6efd` (bleu Bootstrap)

== Thème Contraste Élevé (`[data-bs-theme=&quot;high-contrast&quot;]`)

* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#000000;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --bg-primary: `#000000` (noir)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#ffffff;border:1px solid #000;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --text-primary: `#ffffff` (blanc)
* pass:[&amp;lt;span style=&quot;display:inline-block;width:1em;height:1em;background:#00ff00;vertical-align:middle;margin-right:0.5em&quot;&amp;gt;&amp;lt;/span&amp;gt;] --accent-color: `#00ff00` (vert vif)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجہ&quot;&gt;نتیجہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;HTML انjekشن ماکرو کے ذریعے``AsciiDoc ٹیکنیکی دسکاری میں رنگ کے نمونے دکھانے کے لیے ایک شاندار اور عملی حل فراہم کرتا ہے۔ اگرچہ تھوڑا سیاپی ہے، یہ طریقہ حداکثر قابلحمل اور سادہ مرمت فراہم کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ تکنیک کسی بیرونی تنظیم کی ضرورت نہیں ہے، کوئی اضافی ستائل شیٹ نہیں، اور JBake اور تمام معيار AsciiDoc پروسيسرز کے ساتھ فوراً کام کرتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جب آپ اپنی پہلی رنگین مربع بنا لیتے ہیں، تو صرف HTML کوڈ کاپی پیسٹ کریں اور ہیکسیڈسیمل کوڈ تبدیل کر کے جلدی سے مکمل پیلٹ بنائیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ تکنیک کسی بھی کاسٹوم وائسوال رینڈرنگ کی ضرورت ہونے والی دیگر استعمال کے مواقع پر کشادی گئی جا سکتی ہے: آئیکن، بیج، سادے چارٹس، یا کوئی بھی وائسوال جس میں سٹائل پر واضح کنٹرول کی ضرورت ہو۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_منابع&quot;&gt;منابع&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.asciidoctor.org/asciidoc/latest/pass/pass-macro/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;دستاویز AsciiDoc : پاس ماکرو&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://jbake.org/docs/2.6.7/&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;JBake دوسキュمينٹیشن&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://developer.mozilla.org/fr/docs/Web/CSS/color_value&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;MDN : CSS کے رنگی قيمتیں&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;منتشر شدہ مضمون 2025-11-01 کو&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_مقدمہ&quot;&gt;مقدمہ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_یوز_کیس_ڈائگرام_استعمال_کا_مورد&quot;&gt;یوز کیس ڈائگرام (استعمال کا مورد)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_بین_الاقوامی_سازی_کی_معماری&quot;&gt;بین الاقوامی سازی کی معماری&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_سٹرکچر_ڈائگرام_فائلوں_کی_تنظیم&quot;&gt;سٹرکچر ڈائگرام (فائلوں کی تنظیم)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_یہ_طریقہ_کیوں&quot;&gt;یہ طریقہ کیوں؟&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_کمپوننٹ_ڈائیگرام&quot;&gt;کمپوننٹ ڈائیگرام&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_thymeleaf_کے_ساتھ_ٹیمپلیٹنگ_کا_i18n&quot;&gt;Thymeleaf کے ساتھ ٹیمپلیٹنگ کا I18n&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_پیام_فائلوں_کا_ڈھانچہ&quot;&gt;پیام فائلوں کا ڈھانچہ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_پیغام_فائلوں_کا_محتوا&quot;&gt;پیغام فائلوں کا محتوا&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ٹیپلیٹس_میں_استعمال&quot;&gt;ٹیپلیٹس میں استعمال&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_سیکوئنس_ڈائگرام_i18n_کا_حل&quot;&gt;سیکوئنس ڈائگرام - i18n کا حل&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_jbake_میں_مقامی_ماحول_کی_تنظیم&quot;&gt;JBake میں مقامی ماحول کی تنظیم&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مقالات_کی_بین_الاقوامی_تنظیم_فوڈرز_کے_ذریعے_ترتیب&quot;&gt;مقالات کی بین الاقوامی تنظیم: فوڈرز کے ذریعے ترتیب&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_فلوڈائگرام_flow_پیدائش&quot;&gt;فلوڈائگرام (Flow) - پیدائش&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_فولڈرز_کی_ساخت&quot;&gt;فولڈرز کی ساخت&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_اسapproach_کے_فوائد&quot;&gt;اسApproach کے فوائد&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مضامین_کے_میٹا_ڈیٹا&quot;&gt;مضامین کے میٹا ڈیٹا&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_urls_کی_ترتیب&quot;&gt;URLs کی ترتیب&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مُلتانی_زبانوں_کی_دکھائی_کے_لیے_ٹیمپلیٹس&quot;&gt;مُلتانی زبانوں کی دکھائی کے لیے ٹیمپلیٹس&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_مقالہ_ٹیملپلیٹ_زبان_سلیکٹر_کے_ساتھ&quot;&gt;مقالہ ٹیملپلیٹ زبان سلیکٹر کے ساتھ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_زبان_کے_مطابق_فیلٹرڈ_انڈیکس&quot;&gt;زبان کے مطابق فیلٹرڈ انڈیکس&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_لغات_کے_درمیان_ناویگیشن&quot;&gt;لغات کے درمیان ناویگیشن&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_غلوبل_زبان_سلیکٹر&quot;&gt;غلوبل زبان سلیکٹر&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_فلو_ڈائگرام_صارف_کی_پڑھائی&quot;&gt;فلو ڈائگرام - صارف کی پڑھائی&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_سیلیکٹر_کے_لیے_css_کا_اسٹائل&quot;&gt;سیلیکٹر کے لیے CSS کا اسٹائل&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_زبان_کے_حسب_rss_فِیڈ&quot;&gt;زبان کے حسب RSS فِیڈ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_اچھی_طریقے_کار_اور_ٹپس&quot;&gt;اچھی طریقے کار اور ٹپس&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_1_مقالے_کے_شناختی_کوڈ_کی_اتحاد&quot;&gt;1. مقالے کے شناختی کوڈ کی اتحاد&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_متوافق_تاریخیں&quot;&gt;2. متوافق تاریخیں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_متعدد_زبانوں_کے_ٹیگز&quot;&gt;3. متعدد زبانوں کے ٹیگز&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_غیر_ترجمہ_شدہ_مضامین_کی_انتظام&quot;&gt;4. غیر ترجمہ شدہ مضامین کی انتظام&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_متعدد_زبانوں_کا_سائیٹ_میپ&quot;&gt;5. متعدد زبانوں کا سائیٹ میپ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_نتیجہ&quot;&gt;نتیجہ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_ڈیپلویمنٹ_ڈائگرام&quot;&gt;ڈیپلویمنٹ ڈائگرام&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مقدمہ&quot;&gt;مقدمہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سٹیٹیک ویب سائیٹ کا انٹرنیشنلائزیشن (i18n) پہلی نظر میں دیکھنے پر پیچیدہ نظر آ سکتا ہے، لیکن JBake Thymeleaf کے ساتھ مل کر اس کی ایلیگیٹ حل multilingual ویب سائیٹ بنانے کے لیے فراہم کرتا ہے۔ اس مضامین میں، میں دکھاوٴ گا/گی کہ میں اپنے بلاگ پر i18n کی کیسے ترتیب دی ہے، ٹیمپلیٹنگ اور متعدد زبانی مقالات کے منیجمنت دونوں کو cover کر کے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_یوز_کیس_ڈائگرام_استعمال_کا_مورد&quot;&gt;یوز کیس ڈائگرام (استعمال کا مورد)&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
skinparam packageStyle rectangle

actor &quot;مؤلف&quot; as author
actor &quot;قارئ FR&quot; as reader_fr
actor &quot;قارئ EN&quot; as reader_en

rectangle &quot;JBake متعدد زبانوں کی سائٹ&quot; {
  usecase &quot;فرنسی مقالہ لکھنا&quot; as UC1
  usecase &quot;مقالہ لکھیں EN&quot; as UC2
  usecase &quot;i18n پیغامات کو کنفیگر کریں&quot; as UC3
  usecase &quot;سائٹ بنائیں&quot; as UC4
  usecase &quot;مضمون پڑھیں FR&quot; as UC5
  usecase &quot;مضمون EN پڑھیں&quot; as UC6
  usecase &quot;زبان تبدیل کریں&quot; as UC7
  usecase &quot;موجود ترجمات دیکھیں&quot; as UC8
}

author --&amp;gt; UC1
author --&amp;gt; UC2
author --&amp;gt; UC3
author --&amp;gt; UC4

reader_fr --&amp;gt; UC5
reader_fr --&amp;gt; UC7
reader_fr --&amp;gt; UC8

reader_en --&amp;gt; UC6
reader_en --&amp;gt; UC7
reader_en --&amp;gt; UC8

UC1 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC2 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC3 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC5 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
UC6 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_بین_الاقوامی_سازی_کی_معماری&quot;&gt;بین الاقوامی سازی کی معماری&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہماری 접근 دو ستونوں پر مبنی ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ٹیمپلنٹنگ کا i18n&lt;/strong&gt;: Thymeleaf پیغام فائلوں کا استعمال انٹرفیس کے عناصر کے لیے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;محتوا کا i18n&lt;/strong&gt;: زبان کے مطابق مضامین کی تنظیم ایک مخصوص فولڈر ساخت میں&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_سٹرکچر_ڈائگرام_فائلوں_کی_تنظیم&quot;&gt;سٹرکچر ڈائگرام (فائلوں کی تنظیم)&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
@startsalt
{
{T
+ projet-jbake
++ content
+++ blog
++++ 2024
+++++ fr
++++++ article1.adoc
++++++ article2.adoc
+++++ en
++++++ article1.adoc
++++++ article2.adoc
++++ 2025
+++++ fr
++++++ guide-i18n.adoc
+++++ en
++++++ i18n-guide.adoc
++ templates
+++ post.html
+++ index.html
+++ index_en.html
+++ messages.properties
+++ messages_fr.properties
+++ messages_en.properties
++ assets
+++ css
+++ js
+++ img
++ jbake.properties
++ output
+++ fr
++++ blog
+++++ 2025
++++++ guide-i18n.html
+++ en
++++ blog
+++++ 2025
++++++ i18n-guide.html
}
}
@endsalt
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_یہ_طریقہ_کیوں&quot;&gt;یہ طریقہ کیوں؟&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ الگ کرنے کی اجازت دیتا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;انٹرーフیس میں ہموار برقرار رکھیں، کسی بھی زبان ہو&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;محتوا اور مضامین کی ترجمات کو مستقل طور پر منظم کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;نئی زبانوں شامل کرنے کو آسان بنائیں بغیر بڑے ریفакٹرنگ کے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اجازت دینے مضامین صرف چند زبانیں میں只直اب&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کمپوننٹ_ڈائیگرام&quot;&gt;کمپوننٹ ڈائیگرام&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam componentStyle rectangle

package &quot;منابع&quot; {
  folder &quot;محتوا/بلاگ/2025/&quot; {
    folder &quot;fr/&quot; as content_fr {
      [article1.adoc]
      [article2.adoc]
    }
    folder &quot;میں/&quot; as content_en {
      [article1.adoc] as article1_en
      [article2.adoc] as article2_en
    }
  }

  folder &quot;templates/&quot; {
    [post.html]
    [index.html]
    [index_en.html]
  }

  folder &quot;پیاموں/&quot; {
    [messages_fr.properties]
    [messages_en.properties]
  }

  [jbake.properties]
}

package &quot;JBake انجن&quot; {
  [Parser AsciiDoc] as parser
  [Template Engine\nThymeleaf] as thymeleaf
  [Generator] as generator
  [I18n Resolver] as i18n
}

package &quot;پیدا کردہ سائٹ&quot; {
  folder &quot;fr/&quot; {
    folder &quot;بلاگ/2025/&quot; as blog_fr {
      [article1.html]
      [article2.html]
    }
  }

  folder &quot;میں/&quot; {
    folder &quot;بلاگ/2025/&quot; as blog_en {
      [article1.html] as article1_html_en
      [article2.html] as article2_html_en
    }
  }
}

content_fr --&amp;gt; parser
content_en --&amp;gt; parser
parser --&amp;gt; generator

templates --&amp;gt; thymeleaf
messages --&amp;gt; i18n
i18n --&amp;gt; thymeleaf
thymeleaf --&amp;gt; generator
jbake.properties --&amp;gt; generator

generator --&amp;gt; blog_fr
generator --&amp;gt; blog_en
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_thymeleaf_کے_ساتھ_ٹیمپلیٹنگ_کا_i18n&quot;&gt;Thymeleaf کے ساتھ ٹیمپلیٹنگ کا I18n&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_پیام_فائلوں_کا_ڈھانچہ&quot;&gt;پیام فائلوں کا ڈھانچہ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پہلا قدم یہ ہے کہ ہر سپورٹ کردہ زبان کے لئے پراپرٹی فائل بنائیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;src/jbake/templates/
├── messages.properties        # Fallback par défaut
├── messages_fr.properties     # Français
├── messages_en.properties     # Anglais
└── messages_de.properties     # Allemand&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_پیغام_فائلوں_کا_محتوا&quot;&gt;پیغام فائلوں کا محتوا&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ایک فائل کا مثال ہے`messages_fr.properties`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Accueil
nav.blog=Blog
nav.about=À propos
nav.contact=Contact

# Articles
article.readmore=Lire la suite
article.published=Publié le
article.tags=Étiquettes
article.also.available=Également disponible en

# Interface
site.title=Mon Blog Technique
site.description=Partage de connaissances et expériences
footer.copyright=© 2025 Tous droits réservés
search.placeholder=Rechercher un article...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اور اس کا انگریزی معادل`messages_en.properties`(No output, as the input text is empty)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Home
nav.blog=Blog
nav.about=About
nav.contact=Contact

# Articles
article.readmore=Read more
article.published=Published on
article.tags=Tags
article.also.available=Also available in

# Interface
site.title=My Tech Blog
site.description=Sharing knowledge and experiences
footer.copyright=© 2025 All rights reserved
search.placeholder=Search articles...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ٹیپلیٹس_میں_استعمال&quot;&gt;ٹیپلیٹس میں استعمال&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ کے Thymeleaf ٹیمپلیٹس میں، سینٹکس استعمال کریں`#{}`پیغامات تک رسائی حاصل کرنے کے لیے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
    &amp;lt;meta name=&quot;description&quot; th:content=&quot;#{site.description}&quot; /&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;nav&amp;gt;
        &amp;lt;a th:href=&quot;@{/}&quot; th:text=&quot;#{nav.home}&quot;&amp;gt;Accueil&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/blog/}&quot; th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/about.html}&quot; th:text=&quot;#{nav.about}&quot;&amp;gt;À propos&amp;lt;/a&amp;gt;
    &amp;lt;/nav&amp;gt;

    &amp;lt;footer&amp;gt;
        &amp;lt;p th:text=&quot;#{footer.copyright}&quot;&amp;gt;Copyright&amp;lt;/p&amp;gt;
    &amp;lt;/footer&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_سیکوئنس_ڈائگرام_i18n_کا_حل&quot;&gt;سیکوئنس ڈائگرام - i18n کا حل&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Auteur
participant JBake
participant &quot;AsciiDoc
Parser&quot; as parser
participant &quot;Thymeleaf
انجين&quot; as thymeleaf
participant &quot;I18n
Resolver&quot; as i18n
database &quot;پیاموں_*.properties&quot; as messages

Auteur -&amp;gt; JBake: jbake -b
activate JBake

JBake -&amp;gt; parser: Lire article.fr.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=fr, article-id=xyz)
deactivate parser

JBake -&amp;gt; parser: Lire article.en.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=en, article-id=xyz)
deactivate parser

JBake -&amp;gt; thymeleaf: Générer page FR
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_fr.properties
messages --&amp;gt; i18n: &quot;خوش آمدید&quot;
i18n --&amp;gt; thymeleaf: &quot;خوش آمدید&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=fr)
JBake --&amp;gt; thymeleaf: article.en.html trouvé

thymeleaf --&amp;gt; JBake: /fr/blog/article.html
deactivate thymeleaf

JBake -&amp;gt; thymeleaf: Générer page EN
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_en.properties
messages --&amp;gt; i18n: &quot;ہوم&quot;
i18n --&amp;gt; thymeleaf: &quot;ہوم&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=en)
JBake --&amp;gt; thymeleaf: article.fr.html trouvé

thymeleaf --&amp;gt; JBake: /en/blog/article.html
deactivate thymeleaf

JBake --&amp;gt; Auteur: Site généré
deactivate JBake
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_jbake_میں_مقامی_ماحول_کی_تنظیم&quot;&gt;JBake میں مقامی ماحول کی تنظیم&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ کی فائل میں`jbake.properties`، ڈیفالٹ لوکیل سیٹ کریں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Locale par défaut
thymeleaf.locale=fr

# Encodage
template.encoding=UTF-8&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مقالات_کی_بین_الاقوامی_تنظیم_فوڈرز_کے_ذریعے_ترتیب&quot;&gt;مقالات کی بین الاقوامی تنظیم: فوڈرز کے ذریعے ترتیب&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فلوڈائگرام_flow_پیدائش&quot;&gt;فلوڈائگرام (Flow) - پیدائش&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Lire jbake.properties;
:Charger configuration i18n;

partition &quot;ہر AsciiDoc فائل کے لیے&quot; {
  :Lire métadonnées\n(:jbake-lang:, :jbake-article-id:);
  :Parser contenu AsciiDoc;
  :Stocker en mémoire avec langue;
}

partition &quot;ہر ٹیمپلیٹ کے لیے&quot; {
  :Charger template Thymeleaf;
  :Identifier langue cible;
  :Charger messages_{lang}.properties;

  partition &quot;محتوی کی فیلٹرنگ&quot; {
    :Filtrer articles par langue;
    :Grouper traductions\npar article-id;
  }

  :Appliquer template avec i18n;
  :Générer HTML dans /{lang}/;
}

:Copier assets statiques;
:Générer sitemap multilingue;
:Générer flux RSS par langue;

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فولڈرز_کی_ساخت&quot;&gt;فولڈرز کی ساخت&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نام فائلوں میں Sufix استعمال کرنے کے بجائے، میں ڈائرکٹری (folder) organization اختیار کی ہے جو زیادہ وضوح اور برقرار رکھنے کی صلاحیت فراہم کرتی ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;content/blog/
├── 2024/
│   ├── fr/
│   │   ├── introduction-jbake.adoc
│   │   ├── guide-thymeleaf.adoc
│   │   └── astuces-asciidoc.adoc
│   └── en/
│       ├── introduction-jbake.adoc
│       ├── thymeleaf-guide.adoc
│       └── asciidoc-tips.adoc
└── 2025/
    ├── fr/
    │   └── internationalisation-jbake.adoc
    └── en/
        └── jbake-internationalization.adoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اسapproach_کے_فوائد&quot;&gt;اسApproach کے فوائد&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ڈھانچہ کئی فائدے پیش کرتا ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;واضح تفریق&lt;/strong&gt;: ہر زبان کا اپنا جگہ ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;لچکدار نام‌گذاری&lt;/strong&gt;: فائلوں کے نام زبان کے مطابق مختلف ہو سکتے ہیں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;قابلِ توسیع&lt;/strong&gt;: نئی زبان شامل کرنا آسان ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;طبیعی تنظیم&lt;/strong&gt;: JBake کیemporal logic کا پیروی کرتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مضامین_کے_میٹا_ڈیٹا&quot;&gt;مضامین کے میٹا ڈیٹا&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہر مضامین میں meta ڈیٹا شامل ہونا چاہیے تاکہ ترجمات کے درمیان رابطہ بنایا جا سکے۔ یہ ایک مثال ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;فرانسیسی ورژن&lt;/strong&gt; (&lt;code&gt;2025/fr/internationalisation-jbake.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalisation d&#39;un site statique JBake
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: fr
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide pour mettre en place l&#39;i18n avec JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;انگریزی ورژن&lt;/strong&gt; (&lt;code&gt;2025/en/jbake-internationalization.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalizing a JBake Static Site
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: en
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide to implement i18n with JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;نوٹ: خاصیت`:jbake-article-id:`ضروری ہے : یہ ایک ہی مضمون کی مختلف ترجمعات کو جورنی کی اجازت دےتا ہے&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_urls_کی_ترتیب&quot;&gt;URLs کی ترتیب&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;میں`jbake.properties`, URL پٹرن کو زبان شامل کرنے کے لیے سیٹ اپ کریں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Pattern d&#39;URL avec langue
post.permalink.pattern=:lang/blog/:year/:name.html

# Langue par défaut
site.default.lang=fr&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ اس قسم کے URL بنائے گا :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/fr/blog/2025/internationalisation-jbake.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/en/blog/2025/jbake-internationalization.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مُلتانی_زبانوں_کی_دکھائی_کے_لیے_ٹیمپلیٹس&quot;&gt;مُلتانی زبانوں کی دکھائی کے لیے ٹیمپلیٹس&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مقالہ_ٹیملپلیٹ_زبان_سلیکٹر_کے_ساتھ&quot;&gt;مقالہ ٹیملپلیٹ زبان سلیکٹر کے ساتھ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک ٹیمپلیٹ بنائیں`post.html`جس سے دستیاب ترجمات دکھائی جاتی ہیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;${content.title}&quot;&amp;gt;Article&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;article&amp;gt;
        &amp;lt;header&amp;gt;
            &amp;lt;h1 th:text=&quot;${content.title}&quot;&amp;gt;Titre&amp;lt;/h1&amp;gt;

            &amp;lt;div class=&quot;article-meta&quot;&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(content.date, &#39;dd MMMM yyyy&#39;)}&quot;
                      th:attr=&quot;datetime=${#dates.format(content.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;

                &amp;lt;!-- Sélecteur de traductions --&amp;gt;
                &amp;lt;div class=&quot;translations&quot; th:if=&quot;${content[&#39;article-id&#39;]}&quot;&amp;gt;
                    &amp;lt;span th:text=&quot;#{article.also.available}&quot;&amp;gt;Aussi disponible en :&amp;lt;/span&amp;gt;
                    &amp;lt;ul class=&quot;language-list&quot;&amp;gt;
                        &amp;lt;li th:each=&quot;post : ${published_posts}&quot;
                            th:if=&quot;${post[&#39;article-id&#39;] == content[&#39;article-id&#39;] and post.lang != content.lang}&quot;&amp;gt;
                            &amp;lt;a th:href=&quot;${post.uri}&quot;
                               th:text=&quot;${post.lang.toUpperCase()}&quot;&amp;gt;
                                LANG
                            &amp;lt;/a&amp;gt;
                        &amp;lt;/li&amp;gt;
                    &amp;lt;/ul&amp;gt;
                &amp;lt;/div&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/header&amp;gt;

        &amp;lt;div class=&quot;content&quot; th:utext=&quot;${content.body}&quot;&amp;gt;
            Contenu de l&#39;article
        &amp;lt;/div&amp;gt;

        &amp;lt;footer class=&quot;article-footer&quot;&amp;gt;
            &amp;lt;div class=&quot;tags&quot; th:if=&quot;${content.tags}&quot;&amp;gt;
                &amp;lt;span th:text=&quot;#{article.tags}&quot;&amp;gt;Étiquettes :&amp;lt;/span&amp;gt;
                &amp;lt;span th:each=&quot;tag : ${content.tags}&quot;&amp;gt;
                    &amp;lt;a th:href=&quot;@{/tags/{tag}.html(tag=${tag})}&quot;
                       th:text=&quot;${tag}&quot;&amp;gt;tag&amp;lt;/a&amp;gt;
                &amp;lt;/span&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/footer&amp;gt;
    &amp;lt;/article&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_زبان_کے_مطابق_فیلٹرڈ_انڈیکس&quot;&gt;زبان کے مطابق فیلٹرڈ انڈیکس&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہر زبان کے لیے ان ڈیکس کے ٹیMPLेट بنائیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index.html&lt;/strong&gt;(فرانسیسی انڈیکس) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Lire la suite
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index_en.html&lt;/strong&gt;(انگریزی انڈیکس) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;My Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;en&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Title&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Read more
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_لغات_کے_درمیان_ناویگیشن&quot;&gt;لغات کے درمیان ناویگیشن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_غلوبل_زبان_سلیکٹر&quot;&gt;غلوبل زبان سلیکٹر&lt;/h3&gt;

&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فلو_ڈائگرام_صارف_کی_پڑھائی&quot;&gt;فلو ڈائگرام - صارف کی پڑھائی&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Utilisateur accède au site;

if (Langue préférée ?) then (FR)
  :Afficher /index.html;
  :Lister articles FR;
else (EN)
  :Afficher /en/index.html;
  :Lister articles EN;
endif

:Utilisateur clique sur article;

:Afficher article\navec métadonnées;

if (Traductions disponibles ?) then (oui)
  :Afficher sélecteur\nde traductions;

  if (Changement de langue ?) then (oui)
    :Rediriger vers\ntraduction;
    :Afficher article\ndans nouvelle langue;
  else (non)
    :Continuer lecture;
  endif
else (non)
  :Continuer lecture;
endif

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اپنے اصلی ٹیمپلیت میں زبان کا سلیکٹر شامل کریں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;nav class=&quot;language-switcher&quot;&amp;gt;
    &amp;lt;a href=&quot;/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;fr&#39;} ? &#39;active&#39;&quot;
       title=&quot;Français&quot;&amp;gt;
        🇫🇷 FR
    &amp;lt;/a&amp;gt;
    &amp;lt;a href=&quot;/en/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;en&#39;} ? &#39;active&#39;&quot;
       title=&quot;English&quot;&amp;gt;
        🇬🇧 EN
    &amp;lt;/a&amp;gt;
&amp;lt;/nav&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_سیلیکٹر_کے_لیے_css_کا_اسٹائل&quot;&gt;سیلیکٹر کے لیے CSS کا اسٹائل&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.language-switcher {
    display: flex;
    gap: 1rem;
    padding: 0.5rem;
    background: #f5f5f5;
    border-radius: 4px;
}

.language-switcher a {
    padding: 0.5rem 1rem;
    text-decoration: none;
    color: #333;
    border-radius: 4px;
    transition: background 0.2s;
}

.language-switcher a:hover {
    background: #e0e0e0;
}

.language-switcher a.active {
    background: #007bff;
    color: white;
}

.translations {
    margin: 1rem 0;
    padding: 1rem;
    background: #f8f9fa;
    border-left: 4px solid #007bff;
}

.language-list {
    display: inline-flex;
    gap: 0.5rem;
    list-style: none;
    padding: 0;
    margin: 0;
}

.language-list li::after {
    content: &quot;•&quot;;
    margin-left: 0.5rem;
}

.language-list li:last-child::after {
    content: &quot;&quot;;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_زبان_کے_حسب_rss_فِیڈ&quot;&gt;زبان کے حسب RSS فِیڈ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;زبان کے طور پر الگ‑الگ RSS فیڈز حاصل کرنے کے لئے، الگ ٹیمپلیٹ بنائیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;feed.xml&lt;/strong&gt;(فلکس فرانسیسی) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;rss version=&quot;2.0&quot; xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;channel&amp;gt;
        &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
        &amp;lt;link th:text=&quot;${config.site_host}&quot;&amp;gt;http://example.com&amp;lt;/link&amp;gt;
        &amp;lt;description th:text=&quot;#{site.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;language&amp;gt;fr&amp;lt;/language&amp;gt;

        &amp;lt;item th:each=&quot;post : ${published_posts}&quot;
              th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
            &amp;lt;title th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/title&amp;gt;
            &amp;lt;link th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;Lien&amp;lt;/link&amp;gt;
            &amp;lt;pubDate th:text=&quot;${#dates.format(post.date, &#39;EEE, dd MMM yyyy HH:mm:ss Z&#39;)}&quot;&amp;gt;
                Date
            &amp;lt;/pubDate&amp;gt;
            &amp;lt;description th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;/item&amp;gt;
    &amp;lt;/channel&amp;gt;
&amp;lt;/rss&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_اچھی_طریقے_کار_اور_ٹپس&quot;&gt;اچھی طریقے کار اور ٹپس&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_1_مقالے_کے_شناختی_کوڈ_کی_اتحاد&quot;&gt;1. مقالے کے شناختی کوڈ کی اتحاد&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یقین دلائیں کہ`:jbake-article-id:`ایک ہی مضامین کی تمام ترجموں میں ایک جیسا ہے۔ یکساں فارم استعمال کریں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;انگریزی شناختیں ترجیح دیں، عالمیت کے لیے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;الفاظ کو الگ کرنے کے لیے ہائفن استعمال کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;خصوصی حروف بچیں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_متوافق_تاریخیں&quot;&gt;2. متوافق تاریخیں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک مضامین کی تمام ترجمات کی ایک ہی تاریخ اشاعت ہو چاہیے`:jbake-date:`). یہ ترتیب دینے اور زمانے کے مطابق دکھانے میں آسان بناتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_متعدد_زبانوں_کے_ٹیگز&quot;&gt;3. متعدد زبانوں کے ٹیگز&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tags کے لیے، آپ کے دو انتخاب ہیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اختیار 1 : عام ٹیگز انگریزی میں&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;اختیار 2 : ٹیگز مپنگ کے ساتھ ترجمہ شدہ&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;# Version française
:jbake-tags: java, spring-boot, microservices

# Version anglaise
:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_غیر_ترجمہ_شدہ_مضامین_کی_انتظام&quot;&gt;4. غیر ترجمہ شدہ مضامین کی انتظام&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہر مضمون کو ترجمہ کرنا لازمی نہیں۔ اگر ایک مضمون صرف ایک زبان میں موجود ہو، تو وہ دوسری زبان کی فہرست میں صرف نہیں دکھائی دے گا۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_5_متعدد_زبانوں_کا_سائیٹ_میپ&quot;&gt;5. متعدد زبانوں کا سائیٹ میپ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک سائٹ میپ بنائیں جو تمام زبانوں کو شامل کرے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;urlset xmlns=&quot;http://www.sitemaps.org/schemas/sitemap/0.9&quot;
        xmlns:xhtml=&quot;http://www.w3.org/1999/xhtml&quot;
        xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;url th:each=&quot;post : ${published_posts}&quot;&amp;gt;
        &amp;lt;loc th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;URL&amp;lt;/loc&amp;gt;
        &amp;lt;lastmod th:text=&quot;${#dates.format(post.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;Date&amp;lt;/lastmod&amp;gt;

        &amp;lt;!-- Liens alternatifs pour les traductions --&amp;gt;
        &amp;lt;xhtml:link th:each=&quot;translation : ${published_posts}&quot;
                    th:if=&quot;${translation[&#39;article-id&#39;] == post[&#39;article-id&#39;] and translation.lang != post.lang}&quot;
                    rel=&quot;alternate&quot;
                    th:attr=&quot;hreflang=${translation.lang},href=${config.site_host + translation.uri}&quot; /&amp;gt;
    &amp;lt;/url&amp;gt;
&amp;lt;/urlset&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجہ&quot;&gt;نتیجہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBake سایت کے ساتھ Thymeleaf ka انٹرنیشنلائزین یک مضبوط اور قابلِ حفظطریقہ ہے۔پیغام کے فائل کے ذریعے ٹیمپلیٹنگ سے i18n ko alg karke aur فلڈر انظام کے ذریعے مضمون سے i18n ko alg karke، آپ ایک لچکدار نظام hasil karte hain jo آسانی سے发展 کر سکتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مہتاوی نکات :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Thymeleaf پیغام فائلیں&lt;/strong&gt;صارف انٹر فیس کے لیے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;فوولڈرز پر تنظیم&lt;/strong&gt;(سال/زبان) کے لیے مضامین&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;مضمون کے شناختی نمبر&lt;/strong&gt;ترجمہ جات کو ربط کرنے کے لیے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;مخصوص ٹیمپلیٹس&lt;/strong&gt;ہر زبان کے لیے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;واضح URLs&lt;/strong&gt;زبان کا کوڈ شامل&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ڈیپلویمنٹ_ڈائگرام&quot;&gt;ڈیپلویمنٹ ڈائگرام&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
node &quot;مشین ترقی&quot; {
  artifact &quot;مصادر&quot; {
    folder &quot;رضا منڈ/&quot;
    folder &quot;ٹیمپلیٹس/&quot;
    folder &quot;assets/&quot;
  }

  component &quot;JBake CLI&quot; as jbake

  Sources --&amp;gt; jbake : jbake -b
}

node &quot;بنائلڈ سرور
(CI/CD)&quot; {
  component &quot;GitHub Actions\nیا GitLab CI&quot; as ci

  jbake --&amp;gt; ci : push
}

cloud &quot;CDN / میزبانی&quot; {
  node &quot;سٹیٹک وِب سرور&quot; {
    artifact &quot;پیدا شدہ سائٹ&quot; {
      folder &quot;/blog/&quot;
      folder &quot;/en/blog/&quot;
      folder &quot;/assets/&quot;
    }
  }
}

ci --&amp;gt; &quot;پیدا شدہ سائٹ&quot; : déploiement

actor &quot;قارئین&quot; as users

users --&amp;gt; &quot;سٹیٹک وِب سرور&quot; : HTTPS
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ معماری آپ کو صرف دو زبانیں لے کر آسانی سے شروع کرنے اور مزید زبانوں شامل کرنے کی اجازت دیتی ہے، جس کے لیے کبھی بھی بڑے ریفакториنگ کی ضرورت نہیں پڑتی۔ سب کچھ کامل طور پر Static اور کارآمد رہتا ہے، JBake کی فلسفے کی پابندی کرتے ہوئے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;خوش آمدید، متعدد زبانوں کی ترقی! 🌍&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_تعارف&quot;&gt;تعارف&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tor_اور_اس_کی_سائنچر_ڈاؤنلوڈ&quot;&gt;Tor اور اس کی سائنچر ڈاؤنلوڈ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_دستخط_کی_خفیفی_تصدیق&quot;&gt;دستخط کی خفیفی تصدیق&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_1_tor_project_کی_عمومی_کلید_امپورٹ_کریں&quot;&gt;1. Tor Project کی عمومی کلید امپورٹ کریں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_دستخط_کی_جانچ_کریں&quot;&gt;2. دستخط کی جانچ کریں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_عملی_مثال_درست_دستخط_لیکن_غیر_مصدق_کلید&quot;&gt;عملی مثال : درست دستخط لیکن غیر مصدق کلید&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ہسائن_کی_تصدیق_کرنے_کیوں&quot;&gt;ہسائن کی تصدیق کرنے کیوں؟&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ٹر_براؤزر_کی_اخذ_اور_شروع&quot;&gt;ٹر براؤزر کی اخذ اور شروع&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_اوبونٹو_ڈیسک_پر_انٹیگریشن&quot;&gt;اوبونٹو ڈیسک پر انٹیگریشن&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tor_کے_ساتھ_تعلیمی_وسائل_کا_ایکسپلور_کریں&quot;&gt;Tor کے ساتھ تعلیمی وسائل کا ایکسپلور کریں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ٹور_براؤزر_کی_اپ_ڈیٹ&quot;&gt;ٹور براؤزر کی اپ ڈیٹ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_نتیجہ&quot;&gt;نتیجہ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_حوالہ_جات&quot;&gt;حوالہ جات&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_تعارف&quot;&gt;تعارف&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک ایسی دنیا میں جہاں ڈيجٹل خفیگی مزید مزید خطرناک ہو رہی ہے، &lt;strong&gt;Tor Browser&lt;/strong&gt; ایک ضروری وسیلہ ہے اپنی خفیگی اور معلومات کی آزادی کو محفوظ رکھتا ہے۔ تاہم، ایک ڈاؤنلوڈ شدہ سافٹ ویئر کو کبھی بھی چلانے سے پہلے ضروری ہے&lt;strong&gt;اس کی اصالت کی تصدیق&lt;/strong&gt;. یہ مضمون ایک مکمل طریقہ پیش کرتا ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Tor Browser&lt;/strong&gt; ڈاؤن لوڈ کریں اور اس کا دستخط`.asc`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ڈاؤنلوڈ شدہ فائل کی درستگی کا تجزیہ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اوونتو پر &lt;strong&gt;Tor Browser&lt;/strong&gt; کو انسٹال اور چلانے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اس کو ڈیسکاپ کے مینو میں روزانہ استعمال کے لیے شامل کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ٹور کے ذریعے تعلیمی وسائل اور اخلاقی OSINT کی تلاش کریں&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tor_اور_اس_کی_سائنچر_ڈاؤنلوڈ&quot;&gt;Tor اور اس کی سائنچر ڈاؤنلوڈ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک مخصوص فولڈر Tor براؤزر کے لیے بناؤ:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;mkdir -p ~/workspace/tipiak/tor
cd ~/workspace/tipiak/tor&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سپس، تور براؤزر کا آرکائیو اور اس کی سائن ڈاؤنلوڈ کریں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz
wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz.asc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_دستخط_کی_خفیفی_تصدیق&quot;&gt;دستخط کی خفیفی تصدیق&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ مرحلہ ہے&lt;strong&gt;ضروری&lt;/strong&gt;ڈاؤنلوڈ شدہ فائل واقعی ٹار پروژیکٹ سے آئی ہے اور اس میں کوئی تبدیلی نہیں کی گئی۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_1_tor_project_کی_عمومی_کلید_امپورٹ_کریں&quot;&gt;1. Tor Project کی عمومی کلید امپورٹ کریں&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --auto-key-locate nodefault,wkd --locate-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جسے یقینی بنائیں کہ کلیٹ مناسب طور پر ایمپورٹ ہو گئی ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --list-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_دستخط_کی_جانچ_کریں&quot;&gt;2. دستخط کی جانچ کریں&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر سب چیز درست ہے، درج ذیل پیغام ظاہر ہوگا:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg: Good signature from &quot;Tor Browser Developers (signing key)&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگر غیر مصدقہ کلید کا اخطار آئے تو، یہ صرف اس کا مطلب ہے کہ آپ نے ابھی تک ٹار پروجیکٹ کی اعتبار والی کلید پر دستخط نہیں کی ہے، لیکن دستخط اب بھی درست (VALID) ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_عملی_مثال_درست_دستخط_لیکن_غیر_مصدق_کلید&quot;&gt;عملی مثال : درست دستخط لیکن غیر مصدق کلید&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پتچکرون کے دوران اس طرح کے پیغامات کو ملنا متعارف ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz
gpg: Signature faite le mar. 16 sept. 2025 14:26:26 CEST
gpg:                avec la clef RSA CAAE408AEBE2288E96FC5D5E157432CF78A65729
gpg: Bonne signature de « Tor Browser Developers (signing key) &amp;lt;torbrowser@torproject.org&amp;gt; » [inconnu]
gpg: Attention : cette clef n&#39;est pas certifiée avec une signature de confiance.
gpg:          Rien n&#39;indique que la signature appartient à son propriétaire.
Empreinte de clef principale : EF6E 286D DA85 EA2A 4BA7  DE68 4E2C 6E87 9329 8290
     Empreinte de la sous-clef : CAAE 408A EBE2 288E 96FC  5D5E 1574 32CF 78A6 5729&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ پیغام بتاتا ہے کہ دستخط فنی طور پر « ٹھیک » ہے (فائل تبدیل نہیں کی گئی)، لیکن آپ کا GPG نظام &lt;strong&gt;اعتماد کی تصدیق&lt;/strong&gt; نہیں کر سکتا خود کلید کے بارے میں. اس شک کو دور کرنے کے لیے، primer کلید کا فنگر پرینٹ موازنہ کرنا لازمی ہے۔ (&lt;code&gt;EF6E 286D DA85 EA2A 4BA7 DE68 4E2C 6E87 9329 8290&lt;/code&gt;) جسے ٹار پروجیکٹ کی רשامی ویب سائٹ پر شائع کیا گیا ہے&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;رسمی سائٹ کے مطابق، متوقع چپ ہے :`EF6E286DDA85EA2A4BA7DE684E2C6E8793298290`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کیونکہ دکھائی گئی أثر سے`gpg`اس کی &lt;strong&gt;بالکل&lt;/strong&gt; مطابقت رسمی سائٹ کے ساتھ ہے، آپ یقین رکھ سکتے ہیں کہ کلید معتبر ہے اور فائل محفوظ ہے۔ &quot;غير مصدق کلید&quot; کا انتباہ اب آپ کی لوکل GPG configuration پر معلوماتی ہے، اور دستخط کی صحتی یا فائل کی الاصلیت پر نہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ہسائن_کی_تصدیق_کرنے_کیوں&quot;&gt;ہسائن کی تصدیق کرنے کیوں؟&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;GPG سائننگز کی تصدیق ڈیجیٹل سیکورٹی کی بنیادی کارروائی ہے۔ یہ اجازت دے دیتی ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;ضمانت دینا&lt;strong&gt;اصالت&lt;/strong&gt;ڈیاؤنلوڈ شدہ سافٹ ویئر کا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;خبیث کارکن کے ذریعے مُعرض شدہ فائل کی انسٹالیشن کو روکنا&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;شامل ہوں&lt;strong&gt;ڈیجیٹال سیادتی&lt;/strong&gt;انفرادی&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;مسؤول اور اخلاقی ڈیجیٹال ثقافت کو فروغ دینا&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
actor &quot;صارف&quot; as U
actor &quot;سرور TorProject&quot; as S

usecase &quot;Tor اور اس کی سائنچر ڈاؤنلوڈ کریں&quot; as D
usecase &quot;عمومی کلید کو امپورٹ کریں&quot; as K
usecase &quot;GPG سائنچ کی تصدیق کریں&quot; as V
usecase &quot;Tor کو انسٹال کریں اور چلائیں&quot; as I

U --&amp;gt; D
U --&amp;gt; K
U --&amp;gt; V
U --&amp;gt; I
S --&amp;gt; D

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ٹر_براؤزر_کی_اخذ_اور_شروع&quot;&gt;ٹر براؤزر کی اخذ اور شروع&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;فك کریں ダウンロード کردہ آرکائیو:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;tar -xvf tor-browser-linux-x86_64-14.5.7.tar.xz
cd tor-browser&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سپس براؤزر চালائیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پہلی بار چلنے پر، کنفیگریشن وینڈو کھل کر Tor نٹورك سے کنکشن برقرار کیا جائے گا۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_اوبونٹو_ڈیسک_پر_انٹیگریشن&quot;&gt;اوبونٹو ڈیسک پر انٹیگریشن&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایپلیکیشنز مینیو میں &lt;strong&gt;Tor Browser&lt;/strong&gt; شامل کرنے کے لئے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop --register-app&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آپ پھر کر سکتے ہیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Tor Browser&lt;/strong&gt; کو ایپلیکیشنز مینیو سے شروع کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اسے ڈاک فاویرٹس میں شامل کریں&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اگر خواہش کی جائے تو کیبورڈ شورت کٹ بنائیں&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Téléchargement de Tor;
:Importation de la clé GPG;
:Vérification de la signature;
if (Signature valide ?) then (Oui)
:Extraction du navigateur;
:Lancement du navigateur Tor;
:Enregistrement dans le bureau;
else (Non)
:Supprimer le fichier compromis;
endif
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tor_کے_ساتھ_تعلیمی_وسائل_کا_ایکسپلور_کریں&quot;&gt;Tor کے ساتھ تعلیمی وسائل کا ایکسپلور کریں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tor صرف ایک گُمنامی آلہ نہیں ہے۔ یہ تعلیم و تحقیق کے وسائل تک رسائی کا دروازہ بناتا ہے، مخصوصاً کے شعبوں میں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;OSINT (مفت سرچ انٹیلیجنس)&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://inteltechniques.com&quot;&gt;https://inteltechniques.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://osintframework.com&quot;&gt;https://osintframework.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;تعلیمی اشتراک اور اوپن سورس&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://archive.org&quot;&gt;https://archive.org&lt;/a&gt;(Tor کے ذریعے رسائی، زیادہ رازداری کے لئے)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/&quot;&gt;https://github.com/&lt;/a&gt;(Tor کے ذریعے قابل رسائی)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://librarygenesis.pro&quot;&gt;https://librarygenesis.pro&lt;/a&gt;(مفت علمی ادب تک رسائی)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;رقمی معاشرے میں علم کا انتقال اور انسانوں کی فهم&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ڈیجٹل ثقافت، اظہار آزادی اور علم تک رسائی کے وسائل&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آزاد مستندات سائبر سیکورٹی اور ٹیکنالوجیوں کی اخلاقیات پر&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ٹور_براؤزر_کی_اپ_ڈیٹ&quot;&gt;ٹور براؤزر کی اپ ڈیٹ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بہترین سیکورٹی فراہم کرنے کے لیے، &lt;strong&gt;Tor Browser&lt;/strong&gt; کو اپ ڈیٹ کردینا ضروری ہے۔ براؤزر میں خودکار اپ ڈیٹ کا نظام شامل ہے جو کمانڈ لائن سے فعال کیا جا سکتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tor Browser کی انسٹالیشن ڈائریکٹری سے، اس استارٹ سکرپٹ کو دوبارہ چلانا صرف کافی ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;cd ~/workspace/tipiak/tor/tor-browser
./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لونچ پر، &lt;strong&gt;Tor Browser&lt;/strong&gt; خودکار طور پر چیک کرے گا کہ آیا نیا ورژن موجود ہے یا نہیں۔ اگر یہ الحال ہے، تو وہ اس آپ ڈیٹ کو خودکار طور پر ڈاؤن لوڈ کرے گا اور آپ کے لیے انسٹال کرے گا۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ سادہ طریقہ یقینی بناتا ہے کہ آپ کو ہمیشہ حفاظتی پچز کے سب سے جدید اور سب سے نئی بہتریوں کے ساتھ رہنے ملے، جو محفوظ سیرے کے لیے ضروری ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجہ&quot;&gt;نتیجہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اپنے ڈاؤنلوڈز چیک کرنا کسی بھی شخص کے لیے ایک ضروری ردِ عمل ہے جو ایک محفوظ دیجٹیلی ماحول میں بڑھنا چاہتا ہے۔ Tor کو تصدیق شدہ طریقے سے انسٹال کرنا، یہ&lt;strong&gt;اپنی ڈیجیٹل ایمانداری کو محفوظ رکھیں&lt;/strong&gt;, &lt;strong&gt;فتور سافٹ ویئر میں اعتبار برقرار رکھیں&lt;/strong&gt;, et &lt;strong&gt;اپنی معلوماتی خودمختاری کو مضبوط کرنا&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ڈیجیٹل سکیورٹی ضمیر کا عمل ہے، پرانويا نہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title Tor کے استعمال کی خلاصی تصویر
actor Utilisateur
rectangle &quot;ٹور براؤزر&quot; {
rectangle &quot;گُمنامی&quot; as A
rectangle &quot;OSINT تلاش&quot; as O
rectangle &quot;اشتراک تعلیمی&quot; as E
}
Utilisateur --&amp;gt; A
Utilisateur --&amp;gt; O
Utilisateur --&amp;gt; E
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_حوالہ_جات&quot;&gt;حوالہ جات&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Tor Project کی רשmi سائٹ :https://www.torproject.org/download/[&lt;a href=&quot;https://www.torproject.org/download/&quot; class=&quot;bare&quot;&gt;https://www.torproject.org/download/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;ہسٹریکی تصدیق کی دستاویز :https://support.torproject.org/tbb/how-to-verify-signature/[&lt;a href=&quot;https://support.torproject.org/tbb/how-to-verify-signature/&quot; class=&quot;bare&quot;&gt;https://support.torproject.org/tbb/how-to-verify-signature/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اوبونتو کی دستاویزات :https://ubuntu.com[&lt;a href=&quot;https://ubuntu.com&quot; class=&quot;bare&quot;&gt;https://ubuntu.com&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;تعلیمی آر카이و :https://archive.org/details/opensource[&lt;a href=&quot;https://archive.org/details/opensource&quot; class=&quot;bare&quot;&gt;https://archive.org/details/opensource&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ مضمون &lt;strong&gt;Sécurité et Conscience Numérique&lt;/strong&gt; سیریز کا حصہ ہے، ذمہ دار اور تعلیمی مشقوں کو فروغ دینے کیلئے مفت ابزار کے اردگرد&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_تعارف&quot;&gt;تعارف&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_ورژنوں_کا_کیٹلاگ_libs_versions_toml_ایک_یاد_دہانی&quot;&gt;1. ورژنوں کا کیٹلاگ (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : ایک یاد دہانی&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_مسئله_ایک_کمپوزٹ_بنائ_اور_دو_الگ_عوالم&quot;&gt;2. مسئله: ایک کمپوزٹ بنائ اور دو الگ عوالم&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_حل_حتمیہ_کا_حل_بٹانا&quot;&gt;3. حل: حتمیہ کا حل بٹانا&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_نتیجہ_طاقتِ_کامپوزٹ_بیلڈز_کی_بہتر_طریقے_سے_منظم&quot;&gt;4. نتیجہ : طاقتِ کامپوزٹ بیلڈز کی بہتر طریقے سے منظم&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_تعارف&quot;&gt;تعارف&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&quot;.ہدفی عوام: گرadle ڈویلپرز انحصارات کے انتظام کا سامنا کرتے ہیں،マルチ-билڈ پروجيکٹس میں&lt;/div&gt;
&lt;p&gt;ہماری تلاش میں پلاگ ان بنانے کے لیے`site-baker`, ہم نے صاف اور مرکزی کُڈ بیس کو برقرار رکھنے کی کوشش کی۔ مودرن گریڈل اکوسیستم میں سب سے بہتر طریقے میں سے ایک اس کا استعمال ہے&lt;strong&gt;فہرست ورژنوں&lt;/strong&gt; (&lt;code&gt;libs.versions.toml&lt;/code&gt;) اس انحصارات کو منیج کرنے کے لیے۔ لیکن کیا ہوتا ہے جب آپ کا مشروع زیادہ پیچیدہ ہو جاتا ہے، جیسے ایک&lt;strong&gt;مرکب build&lt;/strong&gt;کجا ایک مستقل بناؤ (ہماری پلاگین) دوسرے میں شامل کرنا چاہیے؟&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ وہ جگہ ہے جہاں ہمارا مغامت غیر متوقع موڑ لی۔ ہم چاہتے تھے کہ ہمارا پلاگ‑إن`site-baker`, یہ خود ایک گریڈیل پراجیکٹ ہے، ہماری اصلی پراجیکٹ کے برابر ورژن کٹیلاگ استعمال کرتا ہے۔ یہ مضامین، ہماریسلسلہ کا پانچواں مضامین، بتاتا ہے کہ ہم نے اس چیلنج کو کیسے حل کیا۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_ورژنوں_کا_کیٹلاگ_libs_versions_toml_ایک_یاد_دہانی&quot;&gt;1. ورژنوں کا کیٹلاگ (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : ایک یاد دہانی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;فائل`gradle/libs.versions.toml`یہ Gradle کی ایک خاصیت ہے جو آپ کے پروジェکٹ کی انحصارات کے ورژن اور تنسیقات کو مرکزیت دے سکتی ہے۔ یہ عام طور پر چارsections (sections) میں منظم ہوتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[versions]&lt;/code&gt;: نسخے نمبروں کے لیے اسم مستعار بناتا ہے (مثل:`kotlin = &quot;1.9.20&quot;`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[libraries]&lt;/code&gt;: مکمل انحصارات کے لیے علیاسوں کا تعین کرتا ہے، اوپر کے تعریف کردہ ورژن استعمال کرتے ہوئے (مثال:`kotlin-stdlib = { module = &quot;org.jetbrains.kotlin:kotlin-stdlib&quot;, version.ref = &quot;kotlin&quot; }`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[bundles]`کئی لائبريریاں ایک alias تحت collectiveorta ہے (مثال:`jackson = [&quot;jackson-core&quot;, &quot;jackson-databind&quot;]&lt;/code&gt;).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[plugins]&lt;/code&gt;: Gradle پلاگین کے لیے علیاس مقرر کرتا ہے۔&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Une fois défini, Gradle génère automatiquement des accesseurs typés, ce qui rend votre `build.gradle.kts`بہت زیادہ پڑھنے کے قابل :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;dependencies {
    // Au lieu de : implementation(&quot;org.jetbrains.kotlin:kotlin-stdlib:1.9.20&quot;)
    implementation(libs.kotlin.stdlib)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;ورژن کے کیٹالگ کا ڈیٹا فلو&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
file &quot;gradle/libs.versions.toml&quot; as Toml
node &quot;گریڈل&quot; as G
file &quot;build.gradle.kts&quot; as BuildScript

Toml --&amp;gt; G : &quot;ne parha jata hai&quot;
G --&amp;gt; BuildScript : &quot;یہ `libs` کا accessor بناتی ہے&quot;
BuildScript -&amp;gt; G : &quot;استعمال کریں `libs` اعتماداٹ کا اعلان کرنے کے لیے&quot;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_مسئله_ایک_کمپوزٹ_بنائ_اور_دو_الگ_عوالم&quot;&gt;2. مسئله: ایک کمپوزٹ بنائ اور دو الگ عوالم&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہماری پروجييکٹ سٹرکچر ایک&lt;strong&gt;مرکب بنائیں&lt;/strong&gt;.اہم پروژیکٹ (&lt;code&gt;thymeleaf.cheroliv.com&lt;/code&gt;) پلاگین کا پروجیکٹ شامل ہے (&lt;code&gt;site-baker&lt;/code&gt;) via la commande`includeBuild(&quot;site-baker&quot;)&lt;code&gt;فائل میں`settings.gradle.kts&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;۔کمپوزٹ بنڈ کی ساخت&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
package &quot;اہم منصوبہ&quot; {
  file &quot;settings.gradle.kts&quot; as MainSettings
  folder &quot;gradle&quot; {
    file &quot;libs.versions.toml&quot; as MainToml
  }
}

package &quot;پلاگین `site-baker` (شامل بنائڈ)&quot; {
  file &quot;settings.gradle.kts&quot; as PluginSettings
  file &quot;build.gradle.kts&quot; as PluginBuild
}

MainSettings -&amp;gt; PluginSettings : `includeBuild(&quot;سائٹ-بیکر&quot;)`
PluginBuild ..&amp;gt; MainToml : **Voulait accéder à...**
note right on link: ...mais ne pouvait pas !
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مسئله یہ ہے کہ، ڈیفالٹ پر، شامل شدہ بنڈ ایک ہے&lt;strong&gt;الگ دنیا&lt;/strong&gt;. اس کی اپنی تنظیمات ہیں، اپنی زندگی کا دور ہے، اور وہ فائل کو نہیں دیکھتا`libs.versions.toml`اہم بناؤ کا. ہمارا`plugin/build.gradle.kts`استعمال کرنے کی کوشش کر رہا تھا`libs.plugins.kotlin.jvm`، لیکن یہ چیز`libs`من مناسب TOML فائل سے پیدا نہیں کیا گیا تھا، جس سے بنڈلڈ ایررز پیدا ہو رہے تھے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_حل_حتمیہ_کا_حل_بٹانا&quot;&gt;3. حل: حتمیہ کا حل بٹانا&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کئی تحقیق کے بعد، حل معلوم ہوا ایک Gradle کی خصوصیت جو مخصوص طور پر اس صورت کے لیے بنائی گئی ہے :`dependencyResolutionManagement`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;فائل میں`settings.gradle.kts` du &lt;strong&gt;build شامل&lt;/strong&gt;(&lt;code&gt;site-baker/settings.gradle.kts&lt;/code&gt;), ہم گرایڈل کو بتا سکتے ہیں کہ استعمال کرنے والا ورژن کیٹالوج کہاں مل سکتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ وہ تنصیب ہے جو ہم نے شامل کر لیا ہے`site-baker/settings.gradle.kts` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// site-baker/settings.gradle.kts

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        gradlePluginPortal()
        mavenCentral()
    }
    versionCatalogs {
        create(&quot;libs&quot;) {
            from(files(&quot;../gradle/libs.versions.toml&quot;))
        }
    }
}

rootProject.name = &quot;site-baker&quot;
include(&quot;plugin&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مہتوی حصے کا تجزیہ کریں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;versionCatalogs {
    create(&quot;libs&quot;) { // Crée un catalogue nommé &#39;libs&#39;
        from(files(&quot;../gradle/libs.versions.toml&quot;)) // En utilisant ce fichier
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;create(&quot;libs&quot;)`ہم ورژنوں کی ایک فہرست اعلان کرتے ہیں جو اس alias کے ذریعے قابل رسائی ہوگا۔`libs&lt;/code&gt;.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;from(files(&quot;../gradle/libs.versions.toml&quot;))`یہ جادو ہے۔ ہم Gradle کو بتاتے ہیں کہ اس کیتالگ کا ماخذ TOML فائل ہے جو ڈائریکٹری میں واقع ہے`gradle&lt;/code&gt; du &lt;strong&gt;والدین کا پروجيٹ&lt;/strong&gt;(&lt;code&gt;../&lt;/code&gt;).&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ کنفیگریشن کے ساتھ, بناؤ`site-baker`اب جان گیا ہے کہ اسے اساسی پروجيکٹ کے ورژن کیٹالوج استعمال کرنا چاہیے۔ چیز`libs`یہ صحیح طریقے سے پیدا کر دیا گیا ہے، اور 관련Mutfiq کر دیے گئے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_نتیجہ_طاقتِ_کامپوزٹ_بیلڈز_کی_بہتر_طریقے_سے_منظم&quot;&gt;4. نتیجہ : طاقتِ کامپوزٹ بیلڈز کی بہتر طریقے سے منظم&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ تجربہ سیکھنے سے بھرپور تھا۔ ورژنوں کا کٹیلاگ رکھاوت کی قابلیت کے لیے ایک شاندار اہلاٹ ہے، لیکن composite builds کے سیناریو میں اس کا رویہ ہمیشہ واضح نہیں ہوتا۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کلید یہ ہے کہ یاد رکھیں کہ ایک شامل بنڈ ایک独立 بنڈ رہتا ہے۔ ورژنوں کے فہرست جیسے ترتیبات کو شریک کرنے کے لیے، Gradle فراہم کردہواضح makaniizm استعمال کرنا ضروری ہے، جیسے کہ بلاک۔&lt;code&gt;dependencyResolutionManagement`میں`settings.gradle.kts&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مسئلہ کو حل کرتے ہوئے، ہم نے نہ صرف اپنی build کو زیادہ صاف بنایا، بلکہ ہم نے اپنا project کی یکجائی کو بھی مضبوط بنایا، جس سے ہم یقین دلائے ہیں کہ پلاگین اور اصلی project apni dependedencies کے لیے ایک ہی سچائی کا مصدر (source) شریک کرتے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آئندہ مضمون میں، ہم اپنی پلاگین کو مزید پیچیدہ کاموں شامل کر کے اس میں اضافہ کرتے رہیں گے، حالانکہ ہمارا انحصارات کا انتظام مضبوط اور مرکزی ہو گیا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_مقدمہ&quot;&gt;مقدمہ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_علامت_فانتوم_بنڈز&quot;&gt;علامت: فانتوم بنڈز&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_تحقیق_کنفیگری_کیش_کیا_ہے&quot;&gt;تحقیق: کنفیگری کیش کیا ہے؟&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مشکل_کا_سبب_ایک_غیر_متوافق_پلاگین&quot;&gt;مشکل کا سبب: ایک غیر متوافق پلاگین&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_محلول_موقت_کیش_کو_غیر_فعال_کریں&quot;&gt;محلول موقت : کیش کو غیر فعال کریں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_حقیقی_حل_پلاگان_کو_متوافق_بنانا&quot;&gt;حقیقی حل : پلاگ‑ان کو متوافق بنانا&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مقدمہ&quot;&gt;مقدمہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&quot;.ہدف شدہجمهور : Gradle ڈویلپرز جن نے پہلے سے ملاقات کی bilayerd کے &quot;جادوئی&quot; یا غیر متوقع سلوک۔&lt;/div&gt;
&lt;p&gt;ہماری پلاگ بنانے کی مسابقت`site-baker`, ہم نے ایک rigorous TDD approach अपनائی۔ ہر فچر کوٹسٹ کیا گیا، تصدیق کیا گیا، اور ہم اعتماد کے ساتھ آگے بڑھتے رہے۔ پھر ایک دن، غیر متوقع واقعہ پیش آیا۔ بنائڈز الگ الگ رویے سےرفتار کرنے لگی۔ پلاگ ان کی لاجک یا کنفیگریشن فائلز میں ہونے والی تبدیلیاں نظرانداز کی جانچ لگی، اور ہمارے فانکشنل ٹیسٹس، جو قبل ازیں قابل اعتماد تھے، بغیر کسی واضح وجہ کے خراب ہونا شروع ہوگئے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ قسم کا مسئلہ بے مثال ناراضگی ہو سکتا ہے۔ یہ ٹول کی قابل اعتمادی اور ہمارے کوڈ کی صحیحیت پر سوال اٹھاتا ہے۔ شدت سے ڈیبگ سیشن کے بعد، مجرم کی شناخت کر لی گئی ہے:&lt;strong&gt;Gradle کی کنفیگریش کیش&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_علامت_فانتوم_بنڈز&quot;&gt;علامت: فانتوم بنڈز&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مسئله مختلف طرائق میں ظاہر ہوتی تھی :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;میں ایک کام میں ایک سٹرنگ تبدیل کر رہا تھا`println`، لیکن پرانی سٹرنگ execution کے دوران دکھائی جاتی رہی۔&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;mein apni file mein ek qadar tabdeel kar raha tha`managed-jbake-context.yml`, پلاگینBehavior kar raha tha jaise ki file nahi badal di gayi thi.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;فونکشنل ٹیسٹس، جو پرانے کے ساتھ ٹیسٹ پروجیکتس بناتے ہیں، اس وجہ سے ناکام ہوگئے کیونکہ پلاگین نئی بنائے گئے کنفیگریشن فائلز کو دکھا رہا نہیں تھا۔&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سب کچھ اسی طرح ہو رہا تھا جیسے Gradle ایک &lt;code&gt;version fantôme&lt;/code&gt; ہمारा build کا Executeครا رہا تھا، ہمرے سب سے طAZA changes کو ignoreครا رہے ہو.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_تحقیق_کنفیگری_کیش_کیا_ہے&quot;&gt;تحقیق: کنفیگری کیش کیا ہے؟&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کنفیگریش کیش Gradle کی نسبتاً جدید اور بہت طاقتور خاصیت ہے جو نئی ورژنوں میں ڈیفالٹ طور پر فعال ہوتی ہے۔ اس کا مقصد بِلڈز کو زیادہ سے زیادہ جلد بنانا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;اصول سادہ ہے :&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;پہلا بار چلنے پر، Gradle مرحلہ کا تنفيذ کرتا ہے&lt;strong&gt;تنظیم&lt;/strong&gt;(Mطالعہ کے`build.gradle.kts`, ٹاسکوں کی تخلیق، اعتمادات کی حل) اور ایک ٹاسک گراف بناتا ہے.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;اس مرحلے کے آخر میں، گریڈل&lt;strong&gt;یہ ٹاسک گراف سیریلائز کریں&lt;/strong&gt;اور اسے کیش میں ڈالتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;آئندہ چلنوں کے دوران، اگر کچھ نہیں بدل (بیلڈ سکرپٹس،&lt;code&gt;gradle.properties&lt;/code&gt;, etc.), Gradle&lt;strong&gt;پوری طرح configuration کے مرحلے کو چھوڑ دیتا ہے&lt;/strong&gt;اور کیش کردہ ٹاسک گراف کو دوبارہ استعمال کرتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بڑے پروجیکٹس پر وقت کی بچت عجیب ہے۔ تاہم، اس کارکردگی کی ایک قیمت ہے: یہ پلاگینز کے لکھنے کے طریقے پر صارف قوانین適用 کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;کونفیگریشن کییش کا حیات چکر&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Première exécution;
:Phase de Configuration;
:Création du graphe de tâches;
:Mise en cache du graphe;
:Phase d&#39;Exécution;
end

start
:Exécution suivante;
if (Cache valide ?) then (oui)
  :Restauration du graphe depuis le cache;
  note right
    La phase de configuration
    est sautée !
  end note
else (non)
  :Phase de Configuration;
  :Mise à jour du cache;
endif
:Phase d&#39;Exécution;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مشکل_کا_سبب_ایک_غیر_متوافق_پلاگین&quot;&gt;مشکل کا سبب: ایک غیر متوافق پلاگین&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہمارا پلاگ‑إن`site-baker`بے خبری سے، وہ تنظیم کی کش کے بعدہ قواعد خلاف ورزے کر رہا تھا۔ ایک کاموں کا گراف سِریالائز ہونے کے لیے، کاموں کو پیچیدہ اشیاء کی références شامل نہیں کرنی چاہیے، جیسے object`Project`یا فائلوں کو تعسفی طور پر عمل کے مرحلے میں پڑھنا۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہماری بنیادی غلط یہ تھا کہ ہم نے YAML فائل کے مواد کو مستعمل ہونے والی ٹاسک کی لوجک کے اندر直接 پڑھا، ہمارے ایکسٹینشن میں محفوظ راستے کے حوالے سے۔ یہ اندازہ کش کے ساتھ متوافق نہیں ہے کیونکہ گرادیل بتا نہیں سکتا کہ فائل کا مواد بدل گیا ہے یا نہیں اگر یہ پڑھنا کسی طرح مودل نہیں کی جائی،مثل ایک&lt;strong&gt;ٹاسک داخلہ&lt;/strong&gt;(Task Input)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_محلول_موقت_کیش_کو_غیر_فعال_کریں&quot;&gt;محلول موقت : کیش کو غیر فعال کریں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہمیں آن لیکر سے نکلنے اور پیشگئی بیلڈ کے سلوک کو متوازن کرنے کے لیے، سب سے جلد حل کوन्फگریشن کییش کو غیر فعال کرنا تھا۔ صرف فائل میں درج ذیل لائن شامل کرنے درکار ہے۔&lt;code&gt;gradle.properties`پلاگ ان استعمال کرنے والی پروجرِکٹ (یا ہمارے場合 میں، ٹیسٹ پروجرِکٹ) کا`site-baker&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# site-baker/gradle.properties
org.gradle.configuration-cache=false&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;فوری طور پر، بِیلڈس نےاپناعادیسلوکپانالیاب۔ ہر ایکécution configuration کیمرحلہ دوبارہشروعہوجاتی تھی اور ہمارتبدیلاتذیناخذکیجاتھی۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لیکن یہ ایک اجتزائی حل ہے، permanent حل نہیں۔ یہ کارکردگی کو قربانی دیتی ہے اور ہماری پلاگین کے بنیادی مسئلے کا حل نہیں کرتی۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_حقیقی_حل_پلاگان_کو_متوافق_بنانا&quot;&gt;حقیقی حل : پلاگ‑ان کو متوافق بنانا&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جیکھے ایک پلاگن جدید Gradle نظام کا بھلا رہنےوالا ہو، اس کو کنفیگریشن کش کے ساتھ مطابقت رکھنا ضروری ہے۔ یہ اس بات کا مطلب ہے کہ ہم کو سोंچنا ہوگا کہ ڈیٹا کی روانگی کیسے ہمارے کاموں تک ہوتی ہے، اور اس میں تبدیلی لانی ہوگی۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کلید استعمال کرنے کی ہے&lt;strong&gt;فراہم کرنے والا APIS&lt;/strong&gt;Gradle سے۔ بجائے جانے والی سادہ قدر (جیسے ایک`String` ou un &lt;code&gt;File&lt;/code&gt;) ہمیں اپنے کام پر وقت گزارنا چاہیے`Property&amp;lt;T&amp;gt;`یا کچھ`Provider&amp;lt;T&amp;gt;`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;۔یہ ہے ریفакٹرنگ کا منصوبہ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;کاروں کی انٹریز کا اعلان :&lt;/strong&gt;YAML فائل کو پارس کرنے والا ٹاسک اس فائل کو انپٹ کے طور پر advertise کرنا ضروری ہے۔ اس کے لیے ہم annotation استعمال کرتے ہیں۔&lt;code&gt;@InputFile&lt;/code&gt;.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] ---- @get:InputFile abstract val configFile: RegularFileProperty ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_تعارف&quot;&gt;تعارف&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_سیاق_ہمارا_پلاگین_site_baker&quot;&gt;1. سیاق : ہمارا پلاگین `site-baker&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_kotlin_میں_کنفیگریشن_کی_مڈولنگ&quot;&gt;2. Kotlin میں کنفیگریشن کی مڈولنگ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_jackson_کو_build_gradle_kts_میں_شامل_کرنا&quot;&gt;3. Jackson کو &lt;code&gt;build.gradle.kts&lt;/code&gt; میں شامل کرنا&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_tdd_کاapproach_yaml_parsing_کا_ٹیسٹ&quot;&gt;4. TDD کاApproach : YAML Parsing کا ٹیسٹ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_یونٹ_ٹیسٹ_yaml_کو_kotlin_অবজেক্ট_मेंแมप_کریں&quot;&gt;4.1. یونٹ ٹیسٹ : YAML کو Kotlin অবজেক্ট मेंแมप کریں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_فنکشنل_ٹیسٹ_کنفیگریشن_فائل_کی_پڑھائی_کی_تصدیق&quot;&gt;4.2. فنکشنل ٹیسٹ : کنفیگریشن فائل کی پڑھائی کی تصدیق&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_پارسینگ_فلو_کی_نمائش&quot;&gt;5. پارسینگ فلو کی نمائش&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_نتیجہ&quot;&gt;نتیجہ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_تعارف&quot;&gt;تعارف&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;مقابلہする Urdu translation: &quot;.عام مقصد : متوسط سطح کے Gradle ڈویلپر جو پیچیدہ تنظیمات کو منیج کرنا چاہتے ہیں۔&lt;/div&gt;
&lt;p&gt;گریڈل پلاگائنز کی ترقیات میں پیچیدہ تنظیمات کی منظم کرنا ایک عام کام ہے۔ DSL کو سو سو خصوصیات سے بوجھ ڈالنے کی بجائے، اکثر ایک بیرونی فائل، جیسے YAML میں، تنظیم کو تعریف کرنا زیادہ صاف اور برقرار رکھنے میں آسان ہوتا ہے۔ یہ مضمون آپ کو Jackson طاقتور لائبریری کے اندراج کے ذریعے YAML فائلوں کو Kotlin اشیاء میں parse کرنے میں رہنمائی کرتا ہے، سخت TDD رویہ اپنائے تاکہ ہماری پلاگین کی مضبوطی یقینی بنائی جا sake۔&lt;code&gt;site-baker&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_سیاق_ہمارا_پلاگین_site_baker&quot;&gt;1. سیاق : ہمارا پلاگین `site-baker&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہمारा پلاگ‑ان`site-baker`اسے YAML فائل کی تنظیمات پڑھنے کی ضرورت ہے (&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) معلومات حاصل کرنے کے لئے جیسے sorce ke raste, deployment ki jagah, aur Git ki pehchaniyat&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم جو YAML کنفیگری پارس کرنا چاہتے ہیں وہ اس طرح ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;bake:
  srcPath: &quot;./site/jbake&quot;
  destDirPath: &quot;bake&quot;
  cname: &quot;cheroliv.com&quot;
pushPage:
  from: &quot;bake&quot;
  to: &quot;cvs&quot;
  repo:
    name: &quot;trainings&quot;
    repository: &quot;https://github.com/pages-content/pages-content.github.io.git&quot;
    credentials:
      username: &quot;USERNAME&quot;
      password: &quot;SECRET_TOKEN&quot;
  branch: &quot;main&quot;
  message: &quot;cheroliv.com&quot;
# ... autres configurations (pushMaquette, supabase, etc.)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_kotlin_میں_کنفیگریشن_کی_مڈولنگ&quot;&gt;2. Kotlin میں کنفیگریشن کی مڈولنگ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پارس کرنے سے پہلے، ہمیں کاتلن میں اپنی ڈیٹر کی ساخت تعین کرنا ہوگی۔ Jackson ان کلاسوں کا استعمال کر کے YAML contents کو خودکار طور پر map کرے گا۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/main/kotlin/com/cheroliv/site/baker/data/SiteConfiguration.kt
package com.cheroliv.site.baker.data

import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory
import com.fasterxml.jackson.module.kotlin.readValue
import com.fasterxml.jackson.module.kotlin.registerKotlinModule

fun parseSiteConfiguration(yaml: String): SiteConfiguration {
    val mapper = ObjectMapper(YAMLFactory()).registerKotlinModule()
    return mapper.readValue(yaml)
}

data class GitPushConfiguration(
    val from: String = &quot;&quot;,
    val to: String = &quot;&quot;,
    val repo: RepositoryConfiguration = RepositoryConfiguration(),
    val branch: String = &quot;&quot;,
    val message: String = &quot;&quot;,
)

data class RepositoryConfiguration(
    val name: String = &quot;&quot;,
    val repository: String = &quot;&quot;,
    val credentials: RepositoryCredentials = RepositoryCredentials(),
) {
    companion object {
        const val ORIGIN = &quot;origin&quot;
        const val CNAME = &quot;CNAME&quot;
        const val REMOTE = &quot;remote&quot;
    }
}

data class RepositoryCredentials(val username: String = &quot;&quot;, val password: String = &quot;&quot;)

data class SiteConfiguration(
    val bake: BakeConfiguration = BakeConfiguration(),
    val pushPage: GitPushConfiguration = GitPushConfiguration(),
    val pushMaquette: GitPushConfiguration = GitPushConfiguration(),
    val pushSource: GitPushConfiguration? = null,
    val pushTemplate: GitPushConfiguration? = null,
    val supabase: SupabaseContactFormConfig? = null
)

data class BakeConfiguration(
    val srcPath: String = &quot;&quot;,
    val destDirPath: String = &quot;&quot;,
    val cname: String? = null,
)

// ... (autres data classes pour Supabase, si nécessaire)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;فنکشن`parseSiteConfiguration`یہ ہمارے ڈی سیریالائزیشن کے لیے داخلہ کا نقطہ ہے۔ یہ استعمال karti hai`ObjectMapper`جیکسن کا، کنفیگرڈ کے ساتھ`YAMLFactory`YAML فارمٹ کے لیے اور`registerKotlinModule()`Kotlin کی خصوصیات کے سپورٹ کے لیے (جیسے پراپرٹیز کی بنیادی valeurs)۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_jackson_کو_build_gradle_kts_میں_شامل_کرنا&quot;&gt;3. Jackson کو &lt;code&gt;build.gradle.kts&lt;/code&gt; میں شامل کرنا&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جیکسن استعمال کرنے کے لیے، ہمیں ضروری ڈپینڈنسیز شامل کرنے ہوں گے داخل`build.gradle.kts`ہمارے ماڈیول کا`plugin`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/build.gradle.kts
dependencies {
    // Jackson for YAML parsing
    implementation(&quot;com.fasterxml.jackson.module:jackson-module-kotlin:2.18.3&quot;)
    implementation(&quot;com.fasterxml.jackson.dataformat:jackson-dataformat-yaml:2.18.3&quot;)

    // ... autres dépendances
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم استعمال کرتے ہیں`jackson-module-kotlin`Kotlin کے سپورٹ کے لئے اور`jackson-dataformat-yaml`YAML فارمٹ کے انتظام کے لیے&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_tdd_کاapproach_yaml_parsing_کا_ٹیسٹ&quot;&gt;4. TDD کاApproach : YAML Parsing کا ٹیسٹ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اب، ہم پارسنگ کی لاجک کی تصدیق کرنے کے لیے TDD لاگو کرتے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_یونٹ_ٹیسٹ_yaml_کو_kotlin_অবজেক্ট_मेंแมप_کریں&quot;&gt;4.1. یونٹ ٹیسٹ : YAML کو Kotlin অবজেক্ট मेंแมप کریں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم یونٹ ٹیسٹ سے شروع کرتے ہیں`SiteBakerPluginTest.kt`فونکشن کی جانچ کرنے`parseSiteConfiguration`یہ YAML سٹرنگ کو صحیح طریقے سے ایک آبجکٹ میں تبدیل کر سکتا ہے`SiteConfiguration`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/test/kotlin/com/cheroliv/site/baker/SiteBakerPluginTest.kt
@Test
fun `can map configuration text to SiteConfiguration object`() {
    val yamlString = &quot;../../managed-jbake-context.yml&quot;
        .run(::File)
        .readText()
        .trimIndent()

    val config: SiteConfiguration = parseSiteConfiguration(yamlString)

    assertEquals(&quot;cheroliv.com&quot;, config.bake.cname)
    assertEquals(&quot;main&quot;, config.pushPage.branch)
    assertEquals(&quot;https://github.com/pages-content/pages-content.github.io.git&quot;, config.pushPage.repo.repository)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ٹیسٹ فائل کی مواد پڑھتا ہے`managed-jbake-context.yml`(جو ٹیسٹ کے معتبر ہونے کے لیے موجود ہونا ضروری ہے) اور اشیاء پر تصدیقات کرتا ہے`SiteConfiguration`نتیجہ. وہ تصدیق کرتا ہے کہ YAML کی کلیدوں کی قيمتیں صحیح طور پر منقوش کی گئی ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_فنکشنل_ٹیسٹ_کنفیگریشن_فائل_کی_پڑھائی_کی_تصدیق&quot;&gt;4.2. فنکشنل ٹیسٹ : کنفیگریشن فائل کی پڑھائی کی تصدیق&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ضمان کرنے کے لیے کہ پلاگ ان اپنے DSL کے ذریعے کنفیگریشن فائل پڑھ سکتا ہے اور پارسنگ ایک واقعی Gradle ماحول میں کام کرتا ہے، ہم ایک فنکشنل ٹسٹ شامل کرتے ہیں`SiteBakerPluginFunctionalTest.kt`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ٹیسٹ ضروری ہے کیونکہ اس میں واقعی پروجیکٹ میں پلاگ ان کا تنفیذ سِملیتا ہے۔ یہ ہونا چاہیے&lt;strong&gt;مُحْکم&lt;/strong&gt;, یہ ہے کہ اسے خود ہی فائل بنانی ہے`managed-jbake-context.yml`کنٹرول شدہ مواد کے ساتھ، ٹیسٹ کی قابلیت بازپیدا کرنے اور ان کی algتاؤ کو یقینی بنانے کے لئے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/functionalTest/kotlin/com/cheroliv/site/baker/SiteBakerPluginFunctionalTest.kt
@Test
fun `config file contains good data`(){
    val configContent = configFile.readText(UTF_8)
    // Vérifications comme dans vos commentaires
    assertTrue(configContent.contains(&quot;bake&quot;))
    assertTrue(configContent.contains(&quot;pushPage&quot;))
    assertTrue(configContent.contains(&quot;repository&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ فَنکشنل ٹیسٹ جانچta ہے کہ ٹیسٹ کے موقت ڈائریکٹری میں کاپی کردہ کنفیگریشن فائل میں متوقع ڈیٹا موجود ہے۔ اگرچہ یہ ٹیسٹ YAML کو مستقیماً Kotlin شیئ میں parse نہیں کرتا، لیکن یہ فائل اور اس کے مضمون کی موجودگی کی تصدیق کرتا ہے، جو پلاگین کے ذریعے parsing کے لیے ایک بنیادی پیش شرط ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_5_پارسینگ_فلو_کی_نمائش&quot;&gt;5. پارسینگ فلو کی نمائش&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایک ڈائگرام YAML کنفیگریشن کے پارسنگ کے دوران ڈیٹا کا فلو اور انٹریکشنز کی نمائندگی کرتا ہے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor &quot;صارف Gradle&quot; as User
participant &quot;build.gradle.kts&quot; as BuildScript
participant &quot;سائیٹ بیکر پلاگین&quot; as Plugin
participant &quot;سائٹ ایکسٹینشن&quot; as Extension
participant &quot;managed-jbake-context.yml&quot; as ConfigFile
participant &quot;پارس سائٹ کنفیگریشن()&quot; as Parser
participant &quot;SiteConfiguration (Kotlin شیء)&quot; as KotlinObject

User -&amp;gt; BuildScript : Applique le plugin et configure le DSL
BuildScript -&amp;gt; Plugin : apply()
Plugin -&amp;gt; Extension : Crée et enregistre l&#39;extension &#39;site&#39;
User -&amp;gt; BuildScript : site { configPath = &quot;...&quot; }
BuildScript -&amp;gt; Extension : Définit configPath

Plugin -&amp;gt; ConfigFile : Lit le fichier (via configPath)
ConfigFile --&amp;gt; Plugin : Contenu YAML
Plugin -&amp;gt; Parser : Appelle parseSiteConfiguration(yamlString)
Parser -&amp;gt; KotlinObject : Mappe le YAML en objet SiteConfiguration
KotlinObject --&amp;gt; Plugin : Retourne l&#39;objet configuré

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجہ&quot;&gt;نتیجہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;TDD طریقے پر عمل کرتے ہوئے، ہم نے Jackson لائبریری کو کامیابی سے داخل کیا ہے تاکہ YAML کنفیگریشن فائلز کو Kotlin اشیاء میں بدل سکیں۔ ہمارے Gradle پلاگین کے اندر۔ اس طریقے نے ہمیں اجازت دی ہے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;واضح طور پر ماڈل بنائیں&lt;/strong&gt;ہماری کنفیگریشن Kotlin ڈیٹا کلاسوں کے ساتھ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پارسنگ لاجیک کی تصدیق کریں&lt;/strong&gt;مستهدف یونٹ ٹیسٹس کے ساتھ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;انٹیگریشن یقینی بنائیں&lt;/strong&gt;ایک واقعی Gradle ماحولیاتی میں، ہرمٹیک فنگش널 ٹسوں کی وجہ سے۔&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ مضبوط بنیاد ہمیں بڑی بھروسہ دےتی ہے تاکہ ہم اپنی پلاگ‑ان کو اس سیٹنگ پر مبنیFacilities کے ساتھ لاچا سکیں، اس کے ساتھ ساتھ کوڈ کی برقرار رکھنے کی قابلیت اور مضبوطی کو بھی یقینی بنائیں۔ اب YAML parsing ہماری پلاگ‑ان کی ایک قابل اعتماد اور ٹیسٹ کردہ فیچر بن گئی ہے۔&lt;code&gt;site-baker&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_پروجیکٹ_کی_ابتدائی&quot;&gt;پروجیکٹ کی ابتدائی&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_ہماری_پہلی_tdd_سikl_ایک_کام_ریکارڈ_کریں&quot;&gt;2. ہماری پہلی TDD سikl : ایک کام ریکارڈ کریں&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_2_1_پہلا_ٹیسٹ_ناکام_ٹیسٹ&quot;&gt;2.1. پہلا ٹیسٹ (ناکام ٹیسٹ)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_2_بعد_ذلك_کوڈ_ٹیسٹ_پاس_کرنے_کے_لئے&quot;&gt;2.2. بعد ذلك کوڈ (ٹیسٹ پاس کرنے کے لئے)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_دورہ_دوم_tdd_ایک_dsl_ای็กسٹنشن_شامل_کریں&quot;&gt;3. دورہ دوم TDD : ایک DSL ای็กسٹنشن شامل کریں&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_3_1_پہلا_ٹیسٹ&quot;&gt;3.1. پہلا ٹیسٹ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_2_کوڈ_بعد_میں&quot;&gt;3.2. کوڈ بعد میں&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_فونکشنل_ٹیسٹ_انٹیگریٹی_کی_تصدیق&quot;&gt;4. فونکشنل ٹیسٹ: انٹیگریٹی کی تصدیق&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_انٹیگریشن_ٹیسٹ_کنٹرولڈ_ماحول_بنائیں&quot;&gt;4.1. انٹیگریشن ٹیسٹ : کنٹرولڈ ماحول بنائیں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_منطق_کو_مکمل_کریں&quot;&gt;4.2. منطق کو مکمل کریں&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_نتیجہ&quot;&gt;نتیجہ&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اس مضامین میں، ہم جانگے کہ Gradle پلاگائن کے لیے مضبوط ڈویلپمنٹ بنیاد کیسے تیار کی جاتی ہے، جسے ٹیسٹ-محور ڈیولپمنٹ (TDD - Test-Driven Development) کے اندراج کے ذریعے استعمال کیا جاتا ہے۔ یہ طریقہ ہمیں یقین دلاتا ہے کہ ہمارا کوڈ مضبوط، قابلِ مرمت ہے اور شروع سے ہی ضروریات کو پوری طرح پورا کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_پروجیکٹ_کی_ابتدائی&quot;&gt;پروجیکٹ کی ابتدائی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle نے ایک کمانڈ کے ذریعے ایک نئے پلاگین کی بنائیت کو زیادہ آسان کردیا ہے`gradle init`ایک &#39;Gradle Plugin&#39; بنانے کا انتخاب کرنے سے Kotlin کے ساتھ، ہم تیار استعمال ہونے والے پروژیکٹ کی ساخت حاصل کرتے ہیں، جس میں دو اہم قسم کے ٹیسٹ شامل ہیں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;واحدی ٹیسٹ :&lt;/strong&gt;میں واقع`src/test`, وہ ہماری پلاگین کے الگ-الگ اجزاء کی تصدیق کرنے میں مدد دیتے ہیں، جیسے کسی کام کی اندرونی logique یا ایک extension کی تنظیم۔ وہ جلدی ہیں اور pôrī Gradle تنفیذ کی ضرورت نہیں ہے۔&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;فنکشنل ٹیسٹز:&lt;/strong&gt;موجود میں`src/functionalTest`, وہ استعمال کرتے ہیں`GradleRunner`ایک provisional test project میں پوری گریڈل بِلڈ چلانے کیلے. یہ ہم کنٹرولڈ ماحول میں پلاگ ان کی واقعی سلوک جانچنے کی اجازت دیتا ہے&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_ہماری_پہلی_tdd_سikl_ایک_کام_ریکارڈ_کریں&quot;&gt;2. ہماری پہلی TDD سikl : ایک کام ریکارڈ کریں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہماری پہلی ضرورت سادہ ہے: پلاگ ان کو ایک نامیدة ٹسک ریکارڈ کرنا ہوگا`printSiteConfig`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_1_پہلا_ٹیسٹ_ناکام_ٹیسٹ&quot;&gt;2.1. پہلا ٹیسٹ (ناکام ٹیسٹ)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;TDD کے مطابق، ہم سب سے پہلے ٹیسٹ لکھتے ہیں جو اس کام کی موجودگی کا تجزیہ کرتا ہے۔ میں`SiteBakerPluginTest.kt`(ہماری یونٹ ٹیسٹ فائل)، ہم شامل کرتے ہیں:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers task`() {
    // Créer un projet de test en mémoire
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Vérifier que la tâche a bien été enregistrée
    assertNotNull(project.tasks.findByName(&quot;printSiteConfig&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ٹیسٹ لہٰزہ ہے، کیونکہ ہم ابھی تک اپنے پلاگ ان میں کوئی کوڈ نہیں لکھے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_2_بعد_ذلك_کوڈ_ٹیسٹ_پاس_کرنے_کے_لئے&quot;&gt;2.2. بعد ذلك کوڈ (ٹیسٹ پاس کرنے کے لئے)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;حالی میں، ہم ضرورت کے مطابق سب سے کم کد لکھ رہے ہیں داخل`SiteBakerPlugin.kt`تا کہ ٹیسٹ passages ہو جائے:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer une tâche simple
        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            // ... la logique de la tâche viendra plus tard
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم ٹیسٹس دوبارہ چلاتے ہیں، اور وہ کامیاب ہو جاتے ہیں۔ ہماری پہلی فیچر تصدیق کردہ ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_دورہ_دوم_tdd_ایک_dsl_ای็กسٹنشن_شامل_کریں&quot;&gt;3. دورہ دوم TDD : ایک DSL ای็กسٹنشن شامل کریں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اگلا شرط استعمال کرنے والوں کو ہمارے پلاگین کو DSL بلاک کے ذریعےconfigure کرنے کی اجازت دینا ہے ان کے`build.gradle.kts`. ہم ایک بلوک چاہتے ہیں`site { &amp;#8230;&amp;#8203; }`جہاں کسی تنظیم کا راستہ محدد کیا جا سکتا ہے&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_1_پہلا_ٹیسٹ&quot;&gt;3.1. پہلا ٹیسٹ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم ایک ٹیسٹ شامل کر رہے ہیں تا extension کی جانچ کی جا سکے`site`یہ اچھی طرح سے ریکارڈ کی گئی ہے اور اس پر ایک قدر مقرر کر سکتے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers extension`() {
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Récupérer l&#39;extension et lui affecter une valeur
    project.extensions
        .findByType(SiteExtension::class.java)!!
        .configPath
        .set(&quot;config.yml&quot;)

    // Vérifier que la valeur a bien été prise en compte
    assertEquals(
        &quot;config.yml&quot;,
        project.extensions.findByType(SiteExtension::class.java)?.configPath?.get()
    )
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ٹیسٹ ناكام ہوتا ہے کیونکہ نہ کلاس`SiteExtension`او extension کی درج نہیں ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_2_کوڈ_بعد_میں&quot;&gt;3.2. کوڈ بعد میں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم کلاس بنارہے ہیں`SiteBakerExtension.kt`ہم اپ ڈیٹ کرتے ہیں`SiteBakerPlugin.kt` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// SiteBakerExtension.kt
open class SiteExtension @Inject constructor(objects: ObjectFactory) {
    val configPath: Property&amp;lt;String&amp;gt; = objects.property(String::class.java)
}

// SiteBakerPlugin.kt
class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer l&#39;extension
        val extension = project.extensions.create(&quot;site&quot;, SiteExtension::class.java)

        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            task.doLast {
                // On utilisera l&#39;extension plus tard
            }
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ٹیسٹس دوبارہ پاس ہو رہے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_فونکشنل_ٹیسٹ_انٹیگریٹی_کی_تصدیق&quot;&gt;4. فونکشنل ٹیسٹ: انٹیگریٹی کی تصدیق&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اب یونٹس ٹیسٹ ہو چکے ہیں، ہمیں یقینی بنانا چاہیے کہ سب چیز ایک ساتھ سچائی بنڈ میں کام کرے۔ یہ فنگیشنل ٹیسٹ کا کردار میں`SiteBakerPluginFunctionalTest.kt`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_انٹیگریشن_ٹیسٹ_کنٹرولڈ_ماحول_بنائیں&quot;&gt;4.1. انٹیگریشن ٹیسٹ : کنٹرولڈ ماحول بنائیں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ٹیسٹ ہمارے پلاگ ان استعمال کرنے والے اصل پروگرام کا ایک سیمیولیشن کرے گا۔ اس کو اعتماد سے بنانے کے لیے, اسے ہونا چاہیے&lt;strong&gt;ہawa band&lt;/strong&gt;, یعنی، اس کو موجودہ فائلوں پر نظام سے مستقل ہونا چاہیے۔ اس کو خود تمام ضروری شرائط بنانی چاہیے جو اس کی chalani ke liye larazmi ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;تست لہٰذا :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;ایک بنائیں`build.gradle.kts`test جو ہمارے پلاگ ان اور اس کے DSL استعمال کرتا ہے۔&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;کانفیگریشن فائل بنائیں&lt;/strong&gt; (&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) پلاگین کو پڑھنا چاہیے۔ یہ ٹیسٹ کی مضبوطی کے لیے ایک اہم قدم ہے۔&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;کام کو انجام دیں`printSiteConfig`کے ذریعے`GradleRunner`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;تأیید کریں کہ بنائیڈ کی آؤٹ پут درست ہے۔&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہر بار اس فائل کی کنفیگری کو نکال کر یا بنانے سے، ہم یقینی بناتے ہیں کہ ٹیسٹ ہے&lt;strong&gt;قابل بازآمد&lt;/strong&gt;اور بیرونی حالت پر منحصر نہیں ہے۔ یہ ہماری ٹیسٹس کو فائل کی پڑھنے سے متعلق ہو سکتی رجعیاں سے محفوظ رکھتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test fun `can run task with DSL`() {
    // 1. Créer un build.gradle.kts de test
    buildFile.writeText(&quot;&quot;&quot;
        plugins { id(&quot;com.cheroliv.site-baker&quot;) }
        site { configPath = &quot;managed-jbake-context.yml&quot; }
    &quot;&quot;&quot;.trimIndent())

    // 2. Créer le fichier de configuration pour un test contrôlé
    val configFile = File(projectDir, &quot;managed-jbake-context.yml&quot;)
    configFile.writeText(&quot;site: { title: &#39;Mon Site de Test&#39; }&quot;) // Contenu YAML simple

    // 3. Exécuter la build
    val runner = GradleRunner.create()
    runner.withPluginClasspath()
    runner.withArguments(&quot;printSiteConfig&quot;)
    runner.withProjectDir(projectDir) // Spécifier le répertoire du projet de test
    val result = runner.build()

    // 4. Vérifier la sortie
    assertTrue(result.output.contains(&quot;Site config path: managed-jbake-context.yml&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ ٹیسٹ ناکام ہوگا جب تک کام`printSiteConfig`یہ ایکسٹنشن کی قدر واقعاً استعمال نہیں کرے گا۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_منطق_کو_مکمل_کریں&quot;&gt;4.2. منطق کو مکمل کریں&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم اپ ڈیٹ کر رہے ہیں کام میں`SiteBakerPlugin.kt`تاکہ وہ سیٹ شدہ قیمت دکھائے :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
    task.doLast {
        println(&quot;Site config path: ${extension.configPath.get()}&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;سب ٹیسٹس، یونٹری اور فنکشنل، اب پاس ہو جاتے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_نتیجہ&quot;&gt;نتیجہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;TDD کے متبا میں ہم نے ایک پلاگ‑ایَن انکریمنٹل اور محفوظ طور پر بنایا۔ ہر چھوٹی فیچر فوراً ایک ٹست سے تصدیق کر دی جاتی ہے۔ تیز یونٹ ٹستس سے مکمل فنکشنل ٹستس تک جو پوری انٹیگریشن کی تصدیق کرتے ہیں۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اپنے ٹیسٹس کو فنگکشنل بنانے میں احتیاط برتہ&lt;strong&gt;محكم&lt;/strong&gt;— خاص طور پر پروگرام کے ذریعے ضروری کنفیگریشن فائلوں کو بناتے ہوئے — ہم ایک بہت مضبوط حفاظت کا جال بناتے ہیں۔ یہ سختی ہمیں واپسی سے مؤثر طور پر حفاظت کرتی ہے اور ہمیں بڑا اعتماد دیتی ہے کہ ہم بعد میں زیادہ پیچیدہ فیچرز شامل کر سکے، جیسے YAML کنفیگریشن فائل کا پارسنگ۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;یہ مضبوط ٹیسٹ کی بنیاد، plugin کے لیے نگہداشت اور مستقبل کی ترقی کے سب سے زیادہ قیمتی سامپٹی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_تعارف&quot;&gt;تعارف&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحلہ_1_منصوبہ_کے_ایسٹنٹ_کو_شروع_کریں&quot;&gt;مرحلہ 1 : منصوبہ کے ایسٹنٹ کو شروع کریں&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_مرحلہ_2_پیدا_شدہ_ڈھانچے_کی_سمجھ&quot;&gt;مرحلہ 2 : پیدا شدہ ڈھانچے کی سمجھ&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_اہم_فائلیں_اور_فولڈرز&quot;&gt;اہم فائلیں اور فولڈرز&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_تعارف&quot;&gt;تعارف&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;عامیاني ہدف : ابتدائی سے وسط سطح تک گریڈل کے ساتھ ڈویلپر&lt;/div&gt;
&lt;p&gt;نئی گرائیڈ پلاگائن پروجیکٹ شروع کرنا ڈراؤناک لگ سکتا ہے۔ خوش قسمتی سے، گرائیڈ ایک طاقتور انٹریکٹیو اسسٹنٹ فراہم کرتا ہے، یہ کام`init`, پریjekt کے ایک مکمل، صاف اور استعمال کے لئے تیار ڈھانچہ پیدا کرنے والا۔ یہ ہدایت آپ کو دکھائے گی کہ اس آلات کا استعمال کرنے سے ایک صحت مند پلگ ان کی بنیاد کیسے بنانی ہے، اس ڈھانچے کی وضاحت کرے گی اور آپ کو ڈکھائے گی کہ کس طرح ابتدائی بنڈ ٹاسک کو شروع کرنا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مرحلہ_1_منصوبہ_کے_ایسٹنٹ_کو_شروع_کریں&quot;&gt;مرحلہ 1 : منصوبہ کے ایسٹنٹ کو شروع کریں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کمانڈ`gradle init`یہ شروع نقطہ ہے۔ یہ ایک کمند لائن اسسٹنٹ چلاتا ہے جو آپ سے سوالوں کی سری پوچھتا ہے تا کہ پروجیکٹ کو کنفیجر کیا جا سکے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;اپنی ٹرمینل کو خالی ڈائریکٹری میں کھولیں اور چلائیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gradle init&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;آسسٹنٹ آپ کو راہ دے گا۔ یہ وہ انتخاب ہیں جو آپ کو ایک Kotlin میں لکھے گئے Gradle پلاگین کے لئے کرنے ہیں :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پروجیکٹ تیار کرنے کی قسم منتخب کریں:&lt;/strong&gt;چنیں`Gradle plugin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ایمپلیمنٹیشن زبان چنیے:&lt;/strong&gt;چنو`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Select build script DSL:&lt;/strong&gt;چنیجئے`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پروجیکٹ کا نام:&lt;/strong&gt;اپنا پروجیکٹ کا نام درج کریں (مثلاً:`site-baker`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پلاگن آئی ڈی:&lt;/strong&gt;اپنے پلاگ ان کو ایک منفرد شناخت دیں (ex:`com.cheroliv.site-baker`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;پلاگ ان کلاس:&lt;/strong&gt;Implementation class ka naam batayein (mesal:`com.cheroliv.SiteBakerPlugin`).&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مکمل ہونے پر، گریڈیل ایک مکمل فائلجر درخت پیدا کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;شروع ہونے کے عمل کا ڈائگرام&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Lancer `gradle init`;
:Choisir &quot;گریڈیل پلاگین&quot;;
:Choisir &quot;Kotlin&quot; (langage);
:Choisir &quot;Kotlin&quot; (DSL);
:Saisir nom, ID, et classe;
:Projet généré;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_مرحلہ_2_پیدا_شدہ_ڈھانچے_کی_سمجھ&quot;&gt;مرحلہ 2 : پیدا شدہ ڈھانچے کی سمجھ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایسسٹنٹ ایک multi-modules پروژیکٹ ڈھانچہ بناتا ہے جو رūt پروژیکٹ کو plug-in کے خود کے سرچس کوڈ سے الگ کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;.
├── gradle/
│   └── wrapper/
│       ├── gradle-wrapper.jar
│       └── gradle-wrapper.properties
├── gradlew
├── gradlew.bat
├── plugin/
│   ├── build.gradle.kts
│   └── src/
│       ├── main/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPlugin.kt
│       ├── test/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPluginTest.kt
│       └── functionalTest/
│           └── kotlin/
│               └── com/cheroliv/SiteBakerPluginFunctionalTest.kt
└── settings.gradle.kts&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_اہم_فائلیں_اور_فولڈرز&quot;&gt;اہم فائلیں اور فولڈرز&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;settings.gradle.kts`یہ فائل جڑ پر موجود ماڈیولز کو بیلڈ میں شامل کرنے کا تعرّف کرتی ہے۔ یہاں، یہ سب‑پروجیکٹ شامل کرتی ہے۔`plugin&lt;/code&gt;.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] (Empty output) rootProject.name = &quot;site-baker include(&quot;plugin&quot;) ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
