&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;loops&quot;&gt;لوپوں&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;06_loops.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Les boucles: Itérer sur arrays et objets.
 */

console.log(&quot;for loop over array&quot;);

var numbers = [12, 10, 8, 6, 4, 2, 0];

for (number of numbers) {
    console.log(number);
}

console.log(&quot;---------&quot;);

console.log(&quot;for loop over object key&quot;);

var obj = { a: 1, b: 2, c: 3, d: 4 };

for (key in obj) {
    console.log(key);
}

console.log(&quot;---------&quot;);

console.log(&quot;for loop over object value&quot;);

for (value in obj) {
    console.log(obj[value]);
}

console.log(&quot;---------&quot;);

console.log(&quot;another for loop over authors array&quot;)

var authors = [
    [&quot;Chrétien&quot;, &quot;de Troyes&quot;, &quot;fr&quot;],
    [&quot;François&quot;, &quot;Rabelais&quot;, &quot;fr&quot;],
    [&quot;René&quot;, &quot;Descartes&quot;, &quot;fr&quot;],
    [&quot;Jean-Jacques&quot;, &quot;Rousseau&quot;, &quot;fr&quot;],
    [&quot;Georg&quot;, &quot;Hegel&quot;, &quot;de&quot;],
    [&quot;Karl&quot;, &quot;Marx&quot;, &quot;de&quot;],
    [&quot;Friedrich&quot;, &quot;Engels&quot;, &quot;de&quot;],
    [&quot;Victor&quot;, &quot;Hugo&quot;, &quot;fr&quot;],
    [&quot;Paul&quot;, &quot;Verlaine&quot;, &quot;fr&quot;],
    [&quot;Antonio&quot;, &quot;Gramsci&quot;, &quot;it&quot;],
    [&quot;Georg&quot;, &quot;Lukacs&quot;, &quot;hu&quot;],
    [&quot;Franz&quot;, &quot;Kafka&quot;, &quot;hu&quot;],
    [&quot;Arthur&quot;, &quot;Rimbaud&quot;, &quot;fr&quot;],
    [&quot;Gérard&quot;, &quot;de Nerval&quot;, &quot;fr&quot;],
];

for (const [i, value] of authors.entries()) {
    console.log(`${value[0]}, ${value[1]} (${value[2]})`);
}

console.log(&quot;---------&quot;);

console.log(&quot;while loop over array&quot;)

var i = 0
while (i &amp;lt; authors.length) {
    console.log(`${authors[i][0]}, ${authors[i][1]} (${authors[i][2]})`);
    i++;
}

console.log(&quot;---------&quot;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;انٹرو جاواسکریپٹ&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;const_var_let&quot;&gt;Const, var اور let&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;07_const_var_let.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * const X var X let
 */
//var x du if n&#39;est pas confiné au scope du if
const varTest = () =&amp;gt; {
    var x = 1;
    console.log(x);
    console.assert(x === 1);
    if (true) {
        var x = 2;
        console.log(x);
        console.assert(x === 2);
    }
    console.log(x);
    console.assert(x !== 1);
    console.assert(x === 2);
}
varTest();

console.log(&quot;---------&quot;);

//var x est global à tous les fichier js
//chargés dans la page html
//var x issue du fichier 1_start.js
//ligne 46
console.log(x);
console.assert(x === 20);

console.log(&quot;---------&quot;);

//premier let x est confiné au scope de la fonction
//le let x du if est confiné au scope du if
const letTest = () =&amp;gt; {
    let x = 1;
    console.log(x);
    console.assert(x === 1);
    if (true) {
        let x = 2;
        console.log(x);
        console.assert(x === 2);
    }
    console.log(x);
    console.assert(x === 1);
    console.assert(x !== 2);
}
letTest();

console.log(&quot;---------&quot;);

/**
 * const: déclare un emplacement mémoire non réattribuable
 * c&#39;est modifiable pour un array,
 * mais non réinitialisable;
 * ex:
 * const arr = [25, 27, 29]
 * arr = [5, 7] //impossible
 * arr[0]=20 // possible
 * ex:
 * const n = 1;
 * n = 3; //impossible
 */
const arr = [25, 27, 29]
console.table(arr);
arr[0] = 20 // possible
console.table(arr);

arr.pop()
console.table(arr);
console.log(&quot;---------&quot;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;انٹرو جاواسکریپٹ&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;rest_and_spread_operators&quot;&gt;Rest اور spread operators&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;08_rest_and_spread_operators.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Opérateur de rest:
 * const add = (...operandes) =&amp;gt; a + b;
 * ou avec parametres avec valeur par défaut
 * const add = (a=0, b=0, ...operandes) =&amp;gt; a + b;
 */

/**
 * spread opérateur:
 * récupère l&#39;ensemble des elements d&#39;une collection,
 * dans un array
 */
const user_ages = [25, 56, 12, 58, 41, 62, 26];

const max_user_age = Math.max(...user_ages);
const min_user_age = Math.min(...user_ages);

console.assert(max_user_age == 62);
console.assert(min_user_age == 12);

console.log(&quot;---------&quot;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;انٹرو جاواسکریپٹ&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;ڈسٹراکچرنگ&quot;&gt;ڈسٹراکچرنگ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;09_destructuring.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * L&#39;affectation par décomposition (destructuring)
 */

const user = {
    first_name: &quot;Oliv&quot;,
    last_name: &quot;Cher&quot;,
    nick_name: &quot;cheroliv&quot;,
    gender: &quot;male&quot;,
    is_adult: true
};
console.log(user);

//première façon d&#39;initaliser des variables sans destructuration
let first_name_legacy = user.first_name;
let last_name_legacy = user.last_name;
let nick_name_legacy = user.nick_name;
let gender_legacy = user.gender;
let is_adult_legacy = user.is_adult;

console.assert(&quot;Oliv&quot; === first_name_legacy);
console.assert(&quot;Cher&quot; === last_name_legacy);
console.assert(&quot;cheroliv&quot; === nick_name_legacy);
console.assert(&quot;male&quot; === gender_legacy);
console.assert(true === is_adult_legacy);
console.log(&quot;---------&quot;);
/**
 * Initialisation par déstructuration
 */
const {
    first_name,
    last_name,
    nick_name,
    gender,
    is_adult
} = user;

console.assert(user.first_name === first_name);
console.assert(user.last_name === last_name);
console.assert(user.nick_name === nick_name);
console.assert(user.gender === gender);
console.assert(user.is_adult === is_adult);

/**
 * Intialisation par déstructuration des arrays
 */
//cible explicite
const [a1, a2] = [15, 25, 17, 81, 51, 46];
console.assert(a1 === 15);
console.assert(a2 === 25);

//cible avec position par rapport aux index par virgules
//je veux b3 à 46
const [b1, b2, , , , b3] = [15, 25, 17, 81, 51, 46];
console.assert(b1 === 15);
console.assert(b2 === 25);
console.assert(b3 === 46);

//déstructuration avec operateur de rest
// je contruit un autre avec avec les elements
// à partir du premier élèment non destructuré
const [c1, c2, ...sub_arr] = [15, 25, 17, 81, 51, 46];
console.assert(b1 === 15);
console.assert(b2 === 25);
console.assert(sub_arr.length === 4);
console.assert(sub_arr[0] === 17);
console.assert(sub_arr[1] === 81);
console.assert(sub_arr[2] === 51);
console.assert(sub_arr[3] === 46);


// Une boucle pour comparer le resultat attendu
for (const [i, value] of[15, 25, 17, 81, 51, 46].entries()) {
    //on reconstruit le tableau à chaque iteration
    console.assert([c1, c2].concat(sub_arr)[i] === value);
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;انٹرو جاواسکریپٹ&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;import_export&quot;&gt;مڈیولز کے امپورٹ اور ایکسپورٹ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;10_module_import_export.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Import et export de module
 *
 * Dans le fichier html
 * au niveau de la balise d&#39;import de script
 * spécifier le type module
 *
 * 1er technique: import nommé des fonctions:
 * import { sum, minus, times, div, rem } from &quot;./dummy_math_functions.js&quot;;
 *
 * 2eme technique: import global des fonction avec l&#39;asterisque(*)
 * en préfixant l&#39;import par un nommage du fichier importé:
 * import * as math from &quot;./dummy_math_functions.js&quot;;
 *
 * 3eme technique: import par alias avec le mot clé &quot;as&quot;
 * import {
 *     sum as add,
 *     minus as substract,
 *     times as multiply,
 *     div as divide,
 *     rem as modulo
 * } from &quot;./dummy_math_functions.js&quot;;
 */

import {
    sum,
    minus,
    times,
    div,
    rem
} from &quot;./dummy_math_functions.js&quot;;

console.assert(sum(1, 1) === 2);
console.assert(minus(4, 2) === 2);
console.assert(times(2, 2) === 4);
console.assert(div(4, 2) === 2);
console.assert(rem(4, 2) === 0);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;dummy_math_functions.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;//sum
const sum = (x, y) =&amp;gt; x + y;

// subtraction
const minus = (x, y) =&amp;gt; x - y;

// multiplication
const times = (x, y) =&amp;gt; x * y;

// division
const div = (x, y) =&amp;gt; x / y;

// remainder: reste de la division euclidiene
const rem = (x, y) =&amp;gt; x % y;

// log sum
const sum_log = (x, y) =&amp;gt; console.log(sum(x, y));

// log subtraction
const minus_log = (x, y) =&amp;gt; console.log(minus(x, y));

// log multiplication
const times_log = (x, y) =&amp;gt; console.log(times(x, y));

// log division
const div_log = (x, y) =&amp;gt; console.log(div(x, y));

// log remainder
const rem_log = (x, y) =&amp;gt; console.log(rem(x, y));

export {
    sum,
    minus,
    times,
    div,
    rem,
    sum_log,
    minus_log,
    times_log,
    div_log,
    rem_log
};&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;انٹرو جاواسکریپٹ&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;classes&quot;&gt;کلاسوں کا استعمال&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;11_classes.js&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;/**
 * Utilisation des classes
 */
//creation d&#39;un objet
class Account {
    constructor(username) {
        this.username = username;
    }
};

const acc1 = new Account(&quot;cheroliv&quot;);
console.table(acc1);
console.assert(acc1.username === &quot;cheroliv&quot;);

console.log(&quot;---------&quot;);

//création d&#39;un objet et ajout de getter et setter(accesseurs)
class AccountInfo {
    constructor(username) {
        this._username = username;
    }

    get username() {
        return this._username;
    }

    /**
     * @param {(arg0: string) =&amp;gt; void} new_username
     */
    set new_username(new_username) {
        this._username = new_username;
    }
};

const acc_info1 = new AccountInfo(&quot;cheroliv&quot;);
console.table(acc_info1);
//accés au membre _username avec le getter username()
console.assert(acc_info1.username === &quot;cheroliv&quot;);

//update la valeur username de acc_info1 avec le setter
acc_info1.new_username = &quot;imrandeh&quot;;
console.assert(acc_info1.username === &quot;imrandeh&quot;);

console.log(&quot;---------&quot;);&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;#toc_js&quot;&gt;&lt;span class=&quot;underline&quot;&gt;انٹرو جاواسکریپٹ&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ڈھانچہ&quot;&gt;ڈھانچہ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کارگاہ_1_بینائی&quot;&gt;کارگاہ 1 : بینائی&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_1_پryn_qqoqcp_کون_کیا_کہاں_کب_کیسے_کیوں&quot;&gt;1. پryn “QQOQCP” – کون، کیا، کہاں، کب، کیسے، کیوں&lt;/h4&gt;

&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_2_پروڈکٹ_ویژن_بورڈ&quot;&gt;2. پروڈکٹ ویژن بورڈ&lt;/h4&gt;
&lt;div class=&quot;sect4&quot;&gt;
&lt;h5 id=&quot;_ہدفی_گروپ&quot;&gt;ہدفی گروپ&lt;/h5&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کون product یا offer استعمال کرنے والے ہیں؟ (مستقیم، غیر مستقیم)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect4&quot;&gt;
&lt;h5 id=&quot;_ضرورتیں&quot;&gt;ضرورتیں&lt;/h5&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایپلیکیشن کے کلیدی استعمال کرنے والوں کے 5 بنیادی ضروریات کیا ہیں؟&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect4&quot;&gt;
&lt;h5 id=&quot;_پروڈکٹ&quot;&gt;پروڈکٹ&lt;/h5&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;میری قدر کی پيشکش کیا ہے؟ پروڈکٹ کی 5 بنیادی خصوصیات کیا ہیں جو اجازت دیتی ہیں کہ جواب دیا جائے aux ضرورتیں&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect4&quot;&gt;
&lt;h5 id=&quot;_کاروباری_مقصد&quot;&gt;کاروباری مقصد&lt;/h5&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;کامیابی کے معیارات کیا ہیں؟&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect4&quot;&gt;
&lt;h5 id=&quot;_رؤیا&quot;&gt;رؤیا&lt;/h5&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;جب 4 کالمیں مکمل ہو جائیں، تو آپ کو Product Vision کے vision حصے کو پر کرنا ہوگا۔ بورڈ ایک مکمل جملے میں.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ورکشاپ_2_شخصیاتصارف_کے_سَفَر&quot;&gt;ورکشاپ 2: شخصیات/صارف کے سَفَر&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہر پرسونا کے لیے صارف کا سفر:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;میرا سروس کون استعمال کرے گا؟ (ہدف)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;کیا وہ کرنا چاہتا ہے؟&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;وہ کس طرح کرے گا؟ (صارف کا سفر)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ورکشاپ_3_زُوننگ_اسٹری_بورڈ_سائٹ_میپ&quot;&gt;ورکشاپ 3: زُوننگ، اسٹری بورڈ، سائٹ میپ&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_زوننگ&quot;&gt;زوننگ&lt;/h4&gt;

&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_2_کیہانی_بورڈ&quot;&gt;2. کیہانی بورڈ&lt;/h4&gt;

&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_3_سائٹ_میپ&quot;&gt;3. سائٹ میپ&lt;/h4&gt;

&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کارگاہ_4_وائرفریممُڈ_بورڈ&quot;&gt;کارگاہ 4: وائرفریم/مُڈ بورڈ&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_1_وائرفریمز&quot;&gt;1. وائرفریمز&lt;/h4&gt;

&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_2_مودبورڈ&quot;&gt;2. مودبورڈ&lt;/h4&gt;

&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ورشاپ_5_اسٹوری_میپنگ_یوزر_استوریز&quot;&gt;ورشاپ 5: اسٹوری میپنگ / یوزر استوریز&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_ستوری_میپنگ_یوزر_سٹوریز_کی_ترجیحی_ترتیب&quot;&gt;ستوری میپنگ (یوزر سٹوریز کی ترجیحی ترتیب)&lt;/h4&gt;

&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_type_dutilisateur_کے_طور_پر_مجھے_un_objectif_چاہیے_تاکہ_une_raison&quot;&gt;&amp;lt;type d&amp;#8217;utilisateur&amp;gt; کے طور پر، مجھے &amp;lt;un objectif&amp;gt; چاہیے تاکہ &amp;lt;une raison&amp;gt;.&lt;/h4&gt;

&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ورش_عمل_6_باك_لاگ&quot;&gt;ورش عمل 6: باك لاگ&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://www.atlassian.com/fr/agile/scrum/backlogs&quot;&gt;پینڈنگ کار&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ورش_7_تقنیق_اور_معماری&quot;&gt;ورش 7: تقنیق اور معماری&lt;/h3&gt;

&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_اچھی_لنکس&quot;&gt;اچھی لنکس&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://play.kotlinlang.org/&quot;&gt;kotlinlang playground&lt;/a&gt;+&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://arrow-kt.io/&quot;&gt;arrow.kt&lt;/a&gt;+&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://arkivanov.github.io/MVIKotlin/&quot;&gt;MVI: ماڈل ویو نیّت&lt;/a&gt;&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/arkivanov/Essenty&quot;&gt;Essenty&lt;/a&gt;(Empty output)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://arkivanov.github.io/Decompose/&quot;&gt;تفرق ہو جاؤ&lt;/a&gt;(Empty output)&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_متنوع_کوڈ_کے_ٹکڑے&quot;&gt;متنوع کوڈ کے ٹکڑے&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_مپ_ریڈیوس&quot;&gt;مپ ریڈیوس&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;بائٹس کی فہرست کو سٹرنگز کی فہرست میں تبدیل کریں اور سٹرنگز کی فہرست کا خلاصہ کریں&lt;br&gt;
ایک سٹرنگ میں کنکینیٹیشن شامل ہے۔ کیسے لاگ کریں request بھیجا(requestBodyContent:byte[])&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;log.info(
    requestBodyContent!!.map { it.toInt().toChar().toString() }
        .reduce { request: String, s: String -&amp;gt; request + s }
)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_enum_aur_sealed_classes&quot;&gt;enum aur sealed classes&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;پوسٹ:&lt;a href=&quot;0038_training_kotlin_enum_sealed_class_post&quot; target=&quot;&quot;_blank&quot;&gt;training kotlin enum sealed class&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_فنکشنل_انٹرفیس_اور_طریقہ_رفرنس&quot;&gt;فنکشنل انٹرفیس اور طریقہ رفرنس&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ہم ایک انٹیٹی کو DTO ڈومین ماڈل میں ایک referência طریقے (فنکشنل سٹائل - java 8) استعمال کر کے بدل سکتے ہیں&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;fun findAllByLoginNot(
        pageable:Pageable,
        login:String)
    :Page&amp;lt;UserDto&amp;gt; {
    return userDao.findAllByLoginNot(
                    pageable,
                    login).map(::fromEntity)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ایکhttps://stackoverflow.com/a/22245383/837404[اچھی وضاحت]&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_معمولی_آؤٹ_پکپ_لینا&quot;&gt;معمولی آؤٹ پکپ لینا&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;package functional

import java.io.ByteArrayOutputStream
import java.io.PrintStream
import java.lang.System.out
import java.lang.System.setOut
import kotlin.test.AfterTest
import kotlin.test.BeforeTest
import kotlin.test.Test
import kotlin.test.assertEquals


class BasicsHOF {
    private val standardOut: PrintStream? = out
    private val outputStreamCaptor = ByteArrayOutputStream()

    @BeforeTest
    fun setUp() = setOut(PrintStream(outputStreamCaptor))

    @AfterTest
    fun tearDown() = setOut(standardOut)

    @Test
    fun `three times dope`() {

        3.times { println(&quot;Hello&quot;) }

        assertEquals(
            buildString {
                repeat(3) { append(&quot;Hello\n&quot;) }
                deleteAt(length - 1)
            }, outputStreamCaptor
                .toString()
                .trim()
        )
    }

    fun Int.times(fn: () -&amp;gt; Unit) = (1..this).forEach { _ -&amp;gt; fn() }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_کotlin_میں_apply_run_let_also_use_اور_with_کے_درمیان_فرق_کیا_ہے&quot;&gt;کotlin میں apply, run, let, also, use اور with کے درمیان فرق کیا ہے؟&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Kotlin فنگشنز کی موازاة اور لامبڈا فارمز کے استعمال کی رفرنس&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_لگو_لگانا&quot;&gt;لگو لگانا&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;مقدمہ Kotlin کے وظائف`apply`, &lt;code&gt;run&lt;/code&gt;, &lt;code&gt;let&lt;/code&gt;, &lt;code&gt;also&lt;/code&gt;, &lt;code&gt;use&lt;/code&gt;, et `with`یہ مختلف اشیاء کو متصرف کرنے کے مختلف طریقے فراہم کرتی ہیں۔ ہر کی اپنی مخصوص استعمال کے حالات اور سلوک ہیں۔ مزید، لامبڈا رفرنس فارمز کوڈ کو زیادہ پڑھنے میں آسان اور استعمال کرنے میں لچکدار بناتی ہیں، موجودہ لامبڈا فنکشنز کی طرف اشارہ کر کے۔&lt;/div&gt;
&lt;p&gt;فنکشن`apply`یہ ایک آبجکت کو بنانے کے دوران تنظیم کرنے کے لیے استعمال ہوتی ہے۔ یہ بنائے جانے والی آبجکت پر استعمال ہونے پر واپس लौٹاتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مثال لامبڈا رفرنس کے ساتھ :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val someObject = SomeClass().apply(::configureObject)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لامبڈا کے ساتھ مثال :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val someObject = SomeClass().apply {
// configuration des propriétés de someObject
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_دورنا&quot;&gt;دورنا&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;فونکشن`run`ایسے کوڈ بلاک کو ایک آبجیکٹ پر چلانے کے لیے استعمال ہوتا ہے اور کوڈ بلاک کا نتیجہ واپس کرتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لامبڈا رفرنس کے ساتھ مثال :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = someObject.run(::someFunction)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;مثال کے ساتھ lambda :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = someObject.run {
// bloc de code à exécuter sur someObject
// la dernière expression est renvoyée
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_let&quot;&gt;let&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;عمل`let`ایک شیء پر کوڈ کے بلوک کو چلانے اور اس بلوک کا نتیجہ واپس کرنے کے لیے استعمال کی جاتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لامبڈا رفرنس کے ساتھ مثال :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = someObject.let(::processObject)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لامبدا کے ساتھ مثال :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = someObject.let {
// bloc de code à exécuter sur someObject
// la dernière expression est renvoyée
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_بھی&quot;&gt;بھی&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;ال فانکشن`also`ایک اجسام پر اضافی عمل کرنے کے لئے استعمال کی جاتی ہے اور وہی اجسام واپس کر دیا جاتا ہے جس پر اس کی عمل کی جاتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لامبڈا رفرنس کے ساتھ مثال :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;someObject.also(::performAdditionalAction)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لامبڈا کے ساتھ مثال :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;someObject.also {
// action additionnelle sur someObject
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_استعمال&quot;&gt;استعمال&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;وظیفہ`use`اس استعمال کے بعد بند ہونے والی وسائل کے ساتھ کام کرنے کے لیے استعمال ہوتی ہے۔ یہ خودکار طور پر فنگکشن کو بلاتی ہے`close`بلوک کے آخر میں.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لامبڈا رفرنس کے ساتھ مثال :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;someResource.use(::useResource)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لامبدا کے ساتھ مثال :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;someResource.use {
// travailler avec la ressource
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ساتھ&quot;&gt;ساتھ&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;وظیفہ`with`یہ کسی اشیاء پر ایک سے زیادہ طریقے بلائے جانے کے لیے استعمال ہوتی ہے، جس میں اس کے نام کا تکرار نہیں ہوتا اور یہ آخری اظہار کے نتیجے کو واپس کر دیتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;lambda reference کے ساتھ مثال:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = with(someObject, ::processWithObject)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لامبدا کے ساتھ مثال :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;val result = with(someObject) {
// appeler des méthodes sur someObject
// la dernière expression est renvoyée
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لامبڈا ریفرنس فارمز یا بلاکس استعمال کرتے ہوئے`{}`, آپ لوجیک کو مختلف فنجن میں لفاف کر سکتے ہیں، جس سے کوڈ کی پڑھنی اور قابلیتِ استعمال میں اضافہ ہوتا ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_let_function_میں_kotlin&quot;&gt;let Function میں Kotlin&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;کیا let اشیاء کو اس کے اوپر انجام دیے گئے بارِحاشی اثرات کے ساتھ واپس کرتا ہے یا ابتدائی داخلے کی حالت میں، function(let) کے مطابق؟&lt;/div&gt;
&lt;p&gt;فونکشن`let`Kotlin کا استعمال ایک آبجیکٹ پر آپریشنز کرنے اور مختلف نتیجہ واپس کرنے کے لیے کیا جاتا ہے۔ تاہم، یہ ضروری ہے کہ ياد رکھا جائے کہ فنگشن`let`یہ شیء کی ابتدائی حالت کو تبدیل نہیں کرتی، جس پر یہ بولائی جاتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;امضا&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;code&gt;inline fun &amp;lt;T, R&amp;gt; T.let(block: (T) &amp;#8594; R): R&lt;/code&gt;&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;استعمال&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;فنکشن`let`یہ عام طور پر ایک اشیاء پر ترنسفرمیشنز عائد کرنے اور ان ترنسفرمیشنز پر مبنی ایک نتیجہ حاصل کرنے کے لیے استعمال ہوتی ہے۔&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;نتیجہ&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;فنکشن سے واپسی میں آنے والی مقدار`let`یہ لامبڈا ایکسپرشن کا نتیجہ ہے جو اس آرگومانٹ کے طور پر پاس کیا جاتا ہے، عام طور پر وہ نتیجہ ہوتا ہے جو اس اشیاء پر کردہ اعمال کا ہوتا ہے۔&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;col style=&quot;width: 50%;&quot;&gt;
&lt;/colgroup&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;&lt;strong&gt;سرحد کے اثرات&lt;/strong&gt;&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;اگرچہ فنکشن`let`� ًیہ لنبڈا ایکسپرشن میں استعمال ہونے پر آبجیکٹ پر جانچ دار اثرات ہو سکتے ہیں، لیکن یہ خود آبجیکٹ کی ابتدائی حالت کو تبدیل نہیں کرتی۔&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;لہٰذا، فنکشن`let`یہ ایک شاندار طریقہ ہے جس میں کسی آبجیکٹ پر آپریشنز انجام دیے جاتے ہیں، ساتھ ہی ایک مشتق شدہ نتیجہ بھی حاصل کیا جاتا ہے، اور اصل آبجیکٹ کی Integrity محفوظ رکھی جاتی ہے۔&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

