&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ groovy spe_char.groovy&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
